# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

def pipe_log(*args):
    """Log to stdout so it appears in OWUI's backend logs."""
    print(f"[openclaw-pipe] {' '.join(str(a) for a in args)}", flush=True)



# ---------------------------------------------------------------------------
# Background tasks
# ---------------------------------------------------------------------------

# The event loop keeps only a weak reference to a task, so a fire-and-forget
# asyncio.create_task() can be garbage-collected before it finishes and its
# work silently never happens. Background work goes through spawn_background,
# which holds the reference until the task is done.
_BACKGROUND_TASKS: set = set()


def spawn_background(coro):
    task = asyncio.create_task(coro)
    _BACKGROUND_TASKS.add(task)
    task.add_done_callback(_BACKGROUND_TASKS.discard)
    return task


# --- identity --------------------------------------------------------------

# ---------------------------------------------------------------------------
# Device Identity helpers
# ---------------------------------------------------------------------------

def _generate_device_identity():
    """Generate a fresh Ed25519 key pair and return a dict with id, publicKey,
    and privateKey (PEM)."""
    pk = ed25519.Ed25519PrivateKey.generate()
    pub = pk.public_key()
    raw = pub.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw
    )
    pub_b64 = base64.urlsafe_b64encode(raw).decode().rstrip("=")
    did = hashlib.sha256(raw).hexdigest()
    pem = pk.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    ).decode()
    return dict(id=did, publicKey=pub_b64, privateKey=pem)


def _sign_challenge(ident, nonce, ts, token_str="", scopes=None):
    """Sign the WebSocket challenge using the device identity. The Gateway
    checks the scope list in the signed payload against the scopes requested."""
    parts = [
        "v2", ident["id"], "webchat", "cli", "operator",
        ",".join(GATEWAY_SCOPES if scopes is None else scopes), str(ts), token_str, nonce
    ]
    pk = serialization.load_pem_private_key(
        ident["privateKey"].encode(), password=None, backend=default_backend()
    )
    sig = pk.sign(("|".join(parts)).encode())
    return dict(
        id=ident["id"],
        publicKey=ident["publicKey"],
        signature=base64.urlsafe_b64encode(sig).decode().rstrip("="),
        signedAt=ts,
        nonce=nonce
    )


def _parse_device_identity(raw):
    """Parse DEVICE_IDENTITY JSON, handling unescaped newlines in PEM keys."""
    if not raw:
        return None
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        pass
    try:
        def _fix_pem(m):
            return m.group(1) + m.group(2).replace("\n", "").replace("\r", "") + m.group(3)
        fixed = re.sub(
            r'("privateKey":\s*")(.*?)("[, \\}])',
            _fix_pem, raw, flags=re.DOTALL
        )
        return json.loads(fixed)
    except Exception:
        return None


# --- state -----------------------------------------------------------------


def _state_dir(path=None):
    """Return the persistent bridge state directory, creating it if possible."""
    root = path or os.environ.get("OPENCLAW_BRIDGE_STATE_DIR") or "/data/openclaw-bridge"
    try:
        os.makedirs(root, mode=0o700, exist_ok=True)
        return root
    except Exception as ex:
        fallback = "/tmp/openclaw-bridge"
        os.makedirs(fallback, mode=0o700, exist_ok=True)
        pipe_log(f"STATE_DIR unavailable ({root}: {ex}); using {fallback}")
        return fallback


def _read_json_file(path):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return None
    except Exception as ex:
        pipe_log(f"Failed reading {path}: {ex}")
        return None


def _write_json_file(path, data):
    try:
        tmp = f"{path}.tmp"
        with open(tmp, "w") as f:
            json.dump(data, f, separators=(",", ":"))
        os.chmod(tmp, 0o600)
        os.replace(tmp, path)
        return True
    except Exception as ex:
        pipe_log(f"Failed writing {path}: {ex}")
        return False




# ---------------------------------------------------------------------------
# Sub-agent child index: the child sessions each chat's session spawned.
#
# The Status dialog lists a chat's children, ended ones included (ELI-152).
# The Gateway has no "children of" read: `sessions.list {spawnedBy}` keeps an
# ended child for 30 minutes only, and a read without it returns every session
# (1.35 MB for 422 rows live). So the Pipe records each spawn it sees accepted
# (`_spawned_child`), and the Status Action keeps each child's last row here,
# so an ended child is listed from this file and a child the window dropped is
# looked up by its own key. One file in the bridge state dir, shared by the
# Pipe and the Action (separate modules in one Open WebUI process), so it
# survives restarts and redeploys. Each change is a read-modify-write under an
# flock. Parents untouched for 180 days are dropped, and each keeps its 200
# newest children. `tasks`: the task each spawn call was given, by child key,
# which titles the child before its transcript holds the spawn message (on
# 2026.10 that is written after the spawn returns, ELI-178). `seeded`: children
# spawned before this file existed were folded in once, from one full list.
# ---------------------------------------------------------------------------

_SUBAGENT_INDEX_NAME = "subagent-children.json"
_SUBAGENT_INDEX_KEEP_MS = 180 * 86400 * 1000
_SUBAGENT_INDEX_PER_PARENT = 200
# What a Subagents row needs of a child session's row.
_SUBAGENT_SNAPSHOT_KEYS = ("key", "label", "status", "startedAt", "createdAt", "updatedAt", "endedAt",
                           "lastRunError", "spawnedBy", "parentSessionKey")


def _subagent_index_path():
    return os.path.join(_state_dir(), _SUBAGENT_INDEX_NAME)


def _subagent_index_read() -> dict:
    data = _read_json_file(_subagent_index_path())
    if not isinstance(data, dict) or not isinstance(data.get("parents"), dict):
        return {"seeded": False, "parents": {}}
    return data


def _subagent_index_update(change) -> None:
    """Apply `change(index)` to the file under its lock, then prune it."""
    path = _subagent_index_path()
    try:
        import fcntl
    except ImportError:
        fcntl = None
    try:
        with open(path + ".lock", "a") as lock:
            if fcntl:
                fcntl.flock(lock, fcntl.LOCK_EX)
            index = _subagent_index_read()
            change(index)
            now = int(time.time() * 1000)
            parents = index["parents"]
            for parent in [p for p, e in parents.items() if now - (e.get("at") or 0) > _SUBAGENT_INDEX_KEEP_MS]:
                del parents[parent]
            for entry in parents.values():
                children = entry["children"]
                if len(children) > _SUBAGENT_INDEX_PER_PARENT:
                    # A key with no row yet is the newest spawn: kept first.
                    newest = sorted(children, key=lambda k: -((children[k] or {}).get("startedAt")
                                                              or (children[k] or {}).get("createdAt")
                                                              or now))
                    entry["children"] = {k: children[k] for k in newest[:_SUBAGENT_INDEX_PER_PARENT]}
                if entry.get("tasks"):
                    entry["tasks"] = {k: t for k, t in entry["tasks"].items() if k in entry["children"]}
            _write_json_file(path, index)
    except Exception as ex:
        pipe_log(f"[subagents] could not update the child index: {ex}")


def _subagent_children(parent) -> dict:
    """{child key: its last row (or None, a spawn not read yet)} of `parent`."""
    entry = _subagent_index_read()["parents"].get(parent) or {}
    return dict(entry.get("children") or {})


def _subagent_tasks(parent) -> dict:
    """{child key: the task its spawn call was given} of `parent`."""
    entry = _subagent_index_read()["parents"].get(parent) or {}
    return dict(entry.get("tasks") or {})


def _subagent_remember(parent, rows=(), keys=(), tasks=None) -> None:
    """Record `parent`'s children: `keys` seen spawned, `rows` as just read,
    `tasks` {child key: the task its spawn call was given}."""
    rows, keys, tasks = list(rows), list(keys), dict(tasks or {})
    if not parent or not (rows or keys or tasks):
        return

    def change(index):
        entry = index["parents"].setdefault(parent, {"at": 0, "children": {}})
        entry["at"] = int(time.time() * 1000)
        for key in [*keys, *tasks]:
            entry["children"].setdefault(key, None)
        if tasks:
            entry.setdefault("tasks", {}).update(tasks)
        for row in rows:
            entry["children"][row["key"]] = {k: row[k] for k in _SUBAGENT_SNAPSHOT_KEYS if row.get(k) is not None}
    _subagent_index_update(change)


def _subagent_index_seeded() -> bool:
    return bool(_subagent_index_read().get("seeded"))


def _subagent_index_mark_seeded(rows=()) -> None:
    """Fold every child in `rows` (one full list) in by its parent, once."""
    rows = list(rows)

    def change(index):
        now = int(time.time() * 1000)
        for row in rows:
            parent = row.get("spawnedBy") or row.get("parentSessionKey")
            if not parent or not row.get("key") or row["key"] == parent:
                continue
            entry = index["parents"].setdefault(parent, {"at": now, "children": {}})
            entry["children"].setdefault(
                row["key"], {k: row[k] for k in _SUBAGENT_SNAPSHOT_KEYS if row.get(k) is not None})
        index["seeded"] = True
    _subagent_index_update(change)


# --- turns -----------------------------------------------------------------

# ---------------------------------------------------------------------------
# Turn identity (ELI-100, docs/design/agent-turns.md 2.2)
# ---------------------------------------------------------------------------
# Every run on an Open WebUI session key renders as one assistant message, and
# which message is decided from the run id alone: any connection, deploy or
# restarted process gets the same answer without shared memory.
#
#   msg-<chat>-<M>-<suffix>   a pipe-started run: its message is M, the reply
#                             Open WebUI created for it (the user turn), or
#                             the reply a resume / ask-user answer continues
#   owui-action-<...>         the Status Action's own runs (/compact): none
#   anything else             an agent turn: uuid5(TURN_NS, "<key>:<run>")

TURN_NS = uuid.UUID("6f1c3e2a-9d4b-4c6e-8a1f-0e0a1b100100")
ACTION_RUN_PREFIX = "owui-action-"
_UUID_RE = r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
_PIPE_RUN_RE = re.compile(rf"^msg-(?P<chat>{_UUID_RE})-(?P<message>{_UUID_RE})-(?P<rest>.+)$")


def pipe_run_id(chat_id: str, message_id: str, kind: str | None = None) -> str:
    """The run id for a pipe-started run that writes into Open WebUI message
    `message_id`: `msg-<chat>-<M>-<t>` for the reply itself, and
    `msg-<chat>-<M>-<kind>-<t>` for a run continuing it (`input`, `resume`).
    The trailing send time is what `_run_id_sent_at` reads."""
    return f"msg-{chat_id}-{message_id}-{kind + '-' if kind else ''}{time.time()}"


def parse_pipe_run_id(run_id: str) -> dict | None:
    """{chat, message, kind} of a pipe-started run id, else None. `kind` is
    `reply` for the reply's own run, or the continuation kind."""
    m = _PIPE_RUN_RE.match(run_id or "")
    if not m:
        return None
    head = m.group("rest").split("-", 1)[0]
    kind = head if head in ("input", "resume") else "reply"
    return {"chat": m.group("chat"), "message": m.group("message"), "kind": kind}


def parse_announce_run_id(run_id: str) -> dict | None:
    """{child_session, child_run} of a sub-agent announce run, else None.

    The Gateway runs a child's completion in the parent session with run id
    `announce:` + `v1:<childSessionKey>:<childRunId>` (announce-idempotency-
    D7LnUTJR.mjs:4-10), suffixed `:wake` or `:retry-<n>` on redelivery. A
    `announce:requester-settle:...` run wakes a yielded parent for a batch
    of children and names no single child."""
    if not (run_id or "").startswith("announce:v1:"):
        return None
    rest = re.sub(r":(?:wake|retry-\d+)$", "", run_id[len("announce:v1:"):])
    child_session, _, child_run = rest.rpartition(":")
    if not child_session.startswith("agent:") or not child_run:
        return None
    return {"child_session": child_session, "child_run": child_run}


def turn_message_id(session_key: str, run_id: str, chat_id: str | None = None) -> str | None:
    """The Open WebUI message run `run_id` on `session_key` renders into, or
    None when it renders nothing (the Status Action's own runs). A pipe run
    id naming another chat than `chat_id` is treated as an agent turn: the
    message id is only trusted inside the chat it was minted for."""
    if not run_id or run_id.startswith(ACTION_RUN_PREFIX):
        return None
    parsed = parse_pipe_run_id(run_id)
    if parsed and (chat_id is None or parsed["chat"] == chat_id):
        return parsed["message"]
    return str(uuid.uuid5(TURN_NS, f"{session_key}:{run_id}"))


# ---------------------------------------------------------------------------
# Claim: one message per run, anchored at the tail (DESIGN 2.3)
# ---------------------------------------------------------------------------
# The claim lives in Open WebUI's DB under the chat's row lock, not in a
# process map, so an old deploy's connection, a new one and a restarted
# process all agree: whoever inserts M first owns it, and two different runs
# that start together chain off the tail each reads under the lock.

_TURN_WRITERS_ATTR = "_openclaw_turn_writers"


def _live_turn_writers() -> set:
    """Writer ids of the connections alive in this Open WebUI process. Kept on
    `open_webui.socket.main` so every load of this Function (a redeploy keeps
    the old module objects alive until they are reaped) shares one set."""
    mod = sys.modules.get("open_webui.socket.main")
    if mod is None:
        return set()
    writers = getattr(mod, _TURN_WRITERS_ATTR, None)
    if writers is None:
        writers = set()
        setattr(mod, _TURN_WRITERS_ATTR, writers)
    return writers


def _register_turn_writer(writer_id: str) -> None:
    _live_turn_writers().add(writer_id)


def _retire_turn_writer(writer_id: str) -> None:
    _live_turn_writers().discard(writer_id)


# Writer ids name their process, so another Open WebUI worker's writer can
# be judged: `<host>/<boot>/<pid>.<start>:<uuid>`, with the
# kernel's boot id and the process start time guarding against a reused pid.
# A writer of this process is alive while its connection is (the set above);
# one of another process on this host while that process runs. A writer of
# another host or boot, or an older pipe's `<pid>:<uuid>`, is judged gone, as
# before: a takeover across hosts needs a shared lease, which a single-host
# Open WebUI does not.
_WRITER_ID_RE = re.compile(r"^(?P<host>[^/]*)/(?P<boot>[^/]*)/(?P<pid>\d+)\.(?P<start>\d+):")


def _proc_start(pid: int) -> str | None:
    """Start time of process `pid` (/proc/<pid>/stat field 22), None if gone."""
    try:
        with open(f"/proc/{pid}/stat") as f:
            return f.read().rsplit(")", 1)[1].split()[19]
    except (OSError, IndexError):
        return None


def _boot_id() -> str:
    try:
        with open("/proc/sys/kernel/random/boot_id") as f:
            return f.read().strip()[:8]
    except OSError:
        return ""


def turn_writer_id() -> str:
    import socket
    pid = os.getpid()
    return f"{socket.gethostname()}/{_boot_id()}/{pid}.{_proc_start(pid) or 0}:{uuid.uuid4()}"


def _turn_writer_alive(writer: str | None) -> bool:
    if not writer:
        return False
    if writer in _live_turn_writers():
        return True
    m = _WRITER_ID_RE.match(writer)
    if not m or int(m.group("pid")) == os.getpid():
        return False
    import socket
    if (m.group("host"), m.group("boot")) != (socket.gethostname(), _boot_id()):
        return False
    return _proc_start(int(m.group("pid"))) == m.group("start")


def _writer_may_take_over(existing: dict) -> bool:
    """A message another writer recorded can be taken only when that writer
    is gone (its connection retired or its process exited) and the message
    is unfinished. A message with no recorded writer is Open WebUI's own stub
    for a user turn; only its own inline request hands it over
    (`takeover=True`, DESIGN 2.6)."""
    writer = (existing.get("meta") or {}).get("openclaw_writer")
    return bool(writer) and existing.get("done") is False and not _turn_writer_alive(writer)


async def _uncancellable(coro):
    """Await `coro`, a write to Open WebUI's DB, to its end even when this task
    is cancelled meanwhile (a Stop), then let the cancel go on. A cancel inside
    Open WebUI's DB call (BEGIN IMMEDIATE or the commit run in aiosqlite's
    thread) can wedge it and keep SQLite's write lock for good, so every later
    write fails (ELI-205)."""
    task = spawn_background(coro)
    try:
        return await asyncio.shield(task)
    except asyncio.CancelledError:
        if not task.done():
            await asyncio.wait({task})
        raise


async def _owui_upsert_message(chat_id: str, message_id: str, fields: dict):
    """Open WebUI's message upsert, never cut short by a cancel (ELI-205)."""
    from open_webui.models.chats import Chats
    return await _uncancellable(
        Chats.upsert_message_to_chat_by_id_and_message_id(chat_id, message_id, fields))


async def _claim_turn_message(chat_id: str, user_id: str, message_id: str, run_id: str,
                              writer_id: str, takeover: bool = False) -> dict:
    """Claim message `message_id` for run `run_id` in chat `chat_id`.

    Under the chat's row lock (`Chats._chat_transaction`): if the message
    exists, it is someone's already, unless `takeover` (a pipe run taking its
    own stub, DESIGN 2.6) or its recorded writer is gone. Another live
    writer's message is never taken. Otherwise it
    is inserted under the deepest leaf, which becomes its parent, and
    `currentId` moves to it. The `chat_message` row is mirrored as
    `insert_chat_turn` does.

    Returns {claimed, how: new|takeover|taken, message_id, parent, messages}:
    `messages` holds the changed nodes, for the `chat:messages` introduce.
    Never cut short by a cancel (ELI-205)."""
    return await _uncancellable(_claim_turn_message_now(
        chat_id, user_id, message_id, run_id, writer_id, takeover))


async def _claim_turn_message_now(chat_id: str, user_id: str, message_id: str, run_id: str,
                                  writer_id: str, takeover: bool) -> dict:
    from open_webui.models.chats import Chats
    from open_webui.models.chat_messages import ChatMessages
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        if chat is None:
            # Deleted in Open WebUI while its session lives on (ELI-218).
            return {"claimed": False, "how": "gone", "message_id": message_id,
                    "parent": None, "messages": {}}
        data = chat.chat or {}
        history = data.get("history") or {"messages": {}, "currentId": None}
        msgs = history.setdefault("messages", {})
        existing = msgs.get(message_id)
        if existing is not None:
            holder = (existing.get("meta") or {}).get("openclaw_writer")
            held = bool(holder) and holder != writer_id and _turn_writer_alive(holder)
            if held or not (takeover or _writer_may_take_over(existing)):
                return {"claimed": False, "how": "taken", "message_id": message_id,
                        "parent": existing.get("parentId"), "messages": {}}
            meta = {**(existing.get("meta") or {}), "openclaw_run": run_id,
                    "openclaw_writer": writer_id}
            msgs[message_id] = {**existing, "meta": meta}
            changed = {message_id: msgs[message_id]}
            how, parent = "takeover", existing.get("parentId")
        else:
            parent = _deepest_leaf_id(msgs, history.get("currentId"))
            leaf = msgs.get(parent) or {}
            model = leaf.get("model") or next(iter(data.get("models") or []), None)
            msgs[message_id] = {
                "id": message_id, "parentId": parent, "childrenIds": [], "role": "assistant",
                "content": "", "output": [], "done": False, "model": model,
                "modelName": leaf.get("modelName") or model, "timestamp": int(time.time()),
                "meta": {"openclaw_run": run_id, "openclaw_writer": writer_id},
            }
            changed = {message_id: msgs[message_id]}
            if parent:
                msgs[parent] = {**leaf, "childrenIds": [*(leaf.get("childrenIds") or []), message_id]}
                changed[parent] = msgs[parent]
            history["currentId"] = message_id
            chat.current_message_id = message_id
            how = "new"
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        chat.updated_at = int(time.time())
        for mid, m in changed.items():
            await ChatMessages.upsert_message(mid, chat_id, user_id, m, db=db)
        return {"claimed": True, "how": how, "message_id": message_id, "parent": parent,
                "messages": changed}


# ---------------------------------------------------------------------------
# Owner rule: who continues an interrupted run (DESIGN 2.7)
# ---------------------------------------------------------------------------
# Read from the run's PERSISTED session row: the settled push after its
# terminal (hasActiveRun false), or the first sessions.list after hello-ok.
# The Gateway recovers only rows still `running`; the pipe resumes only rows
# already terminal with an outside kill, so one run never gets two
# continuations.

MAX_TURN_RESUMES = 3
# The child's exit reaches the row only as this text (no structured field;
# dist cli-transport line pinned in test_fixture_openclaw_exit_errors.json,
# re-checked against the installed dist by ExitTextFixtureTest): SIGTERM
# (143) and SIGKILL / OOM (137) by exit code, or a raw signal.
_EXTERNAL_KILL_RE = re.compile(r"process exited with (?:code (?:143|137)\b|signal SIG[A-Z]+)")


def turn_owner(row: dict, stop_notice_before: bool = False) -> str:
    """`gateway`, `pipe` or `none` for an interrupted run's settled row.

    `stop_notice_before`: a `shutdown` event without `restartExpectedMs`
    reached this connection before the run's terminal (a stop-mode abort,
    which the Gateway never recovers)."""
    status = (row or {}).get("status")
    if status == "running":
        return "gateway"
    if status == "interrupted":
        # 2026.10: marked for restart recovery, not started yet (probe
        # 2026-10-17); a recovery it gives up on tombstones the row to failed.
        return "gateway"
    if status == "failed" and _EXTERNAL_KILL_RE.search(str(row.get("lastRunError") or "")):
        return "pipe"
    if status == "killed" and stop_notice_before:
        return "pipe"
    return "none"


def judges_cut_runs_after_listening(version) -> bool:
    """A 2026.10+ Gateway serves session rows before its restart-recovery pass
    has judged the runs a crash cut (about 8 s, probe 2026-10-17). 2026.9.3
    keeps a cut run's row `running` (persisted at lifecycle start,
    session-lifecycle-state-C7hBzJwC.mjs:77, 102) and marks within ms. An
    unknown version is treated as the old one: never wait on a no-status row."""
    m = re.match(r"\s*(\d{4})\.(\d{1,2})\.", str(version or ""))
    return bool(m) and (int(m.group(1)), int(m.group(2))) >= (2026, 10)


def next_continuation(row: dict, stop_notice_before: bool, resumes_so_far: int,
                      after_restart: bool = False) -> str:
    """What the writer of M does when its run settles: `gateway` (keep M open
    for the recovery run), `wait` (another run holds the session: send
    nothing, decide again on its settle), `resume` (send
    msg-<chat>-<M>-resume-<t>), or `finalize`. A resume sent into a busy
    session is queued as a follow-up, and after a restart recovery that
    follow-up fails (M3-crash 04351f67), so a session with an active run
    never gets one. The budget is counted on M, so a resume that is cut the
    same way again (an OOM loop) ends after MAX_TURN_RESUMES.

    `after_restart`: the Gateway restarted since the run's first event, the
    run never reached its terminal, and the Gateway judges cut runs only after
    it listens (`judges_cut_runs_after_listening`). Its idle no-status row is
    then not a settle: the next pushed row decides, or the next transcript
    append (a recovery's turn, or a give-up's tombstone notice)."""
    if after_restart and not (row or {}).get("hasActiveRun") and (row or {}).get("status") is None:
        return "gateway"
    owner = turn_owner(row, stop_notice_before)
    if owner == "gateway":
        return "gateway"
    if (row or {}).get("hasActiveRun"):
        return "wait"
    if owner == "pipe" and resumes_so_far < MAX_TURN_RESUMES:
        return "resume"
    return "finalize"


# ---------------------------------------------------------------------------
# Rule E and the active run, from the transcript (DESIGN 2.1, case 5)
# ---------------------------------------------------------------------------

RECOVERY_SOURCE_TOOL = "main_session_restart_recovery"


def _history_user_turns(messages: list) -> list:
    """[(run_id, provenance sourceTool)] of the admitted user turns, in order."""
    out = []
    for m in messages or []:
        run = _history_user_run_id(m)
        if run:
            out.append((run, (m.get("provenance") or {}).get("sourceTool")))
    return out


def recovery_source_run(messages: list, run_id: str) -> str | None:
    """Rule E: for a restart-recovery run (its `<id>:user` turn carries the
    `main_session_restart_recovery` provenance, dist
    main-session-restart-recovery-CPJjd8da.mjs:441, 452-456), the run it
    recovers: the newest non-recovery admitted turn before it, which is what
    the Gateway's restartRecoveryDeliverySourceRunId names
    (chat-send-handler-kZQfUabO.mjs:635-636, agent-command-C9QUtzmi.mjs:1019).
    None for any other run."""
    turns = _history_user_turns(messages)
    for i, (run, tool) in enumerate(turns):
        if run == run_id:
            if tool != RECOVERY_SOURCE_TOOL:
                return None
            return next((r for r, t in reversed(turns[:i]) if t != RECOVERY_SOURCE_TOOL), None)
    return None


def run_message_id(session_key: str, chat_id: str, run_id: str, messages: list | None = None) -> str | None:
    """The message run `run_id` writes into: its source run's for a restart
    recovery (rule E), else its own (turn_message_id)."""
    source = recovery_source_run(messages, run_id) if messages else None
    return turn_message_id(session_key, source or run_id, chat_id)


# ---------------------------------------------------------------------------
# Cron wakes: one run id for every wake into a session (ELI-103)
# ---------------------------------------------------------------------------
# The cron executor runs a session wake with runId = the session's sessionId
# (run-executor.runtime-ro-4Z0fM.mjs:499), so the id names no single wake.
# What does: the wake's own admitted user turn, `<logicalTurnId>:user` with the
# prompt `[cron:<jobId> <name>] ...` (isolated-agent-C_VaOV3U.mjs:1066) and no
# provenance. On claude-cli it is committed before the CLI starts, so before
# the wake's first event (cli-runner-9MSP9PU4.mjs:1370 awaits it ahead of
# runCliRecovery). The next wake's turn is committed only once this wake's
# execution has ended (session work admission). So the wake's turn is the
# newest one committed at or before the event's `ts`. The run's closing
# message is keyed `cli-assistant:<sessionId>` and deduplicated by that key
# (session-accessor-CX17Bx59.mjs:3343-3347), so only the first wake into a
# session ever gets one: never end or rebuild a wake from it.

#
# OpenClaw 2026.10.2+ records the wake's turn differently: no header in the
# text but the cron provenance ({kind: internal_system, sourceTool: cron,
# jobId, sourcePromptPrefix}), returned by `chat.history` as role "assistant"
# (`_is_forwarded_turn`). Such a wake runs under its own run id and closes with
# its own `cli-assistant:<runId>` (2026.10.3 and 10.5 fixtures), so it is an
# ordinary agent turn: `shared_run` False, and no sessionId event binds it.

_CRON_PROMPT_RE = re.compile(r"^\[cron:(?P<job>[^\s\]]+)[\s\]]")


def _cron_turn_job(m: dict) -> str | None:
    """The cron job a wake turn names: its provenance's (10.2+), else its
    prompt's header (9.3, no provenance). None for any other turn."""
    prov = m.get("provenance") if isinstance(m.get("provenance"), dict) else None
    if prov:
        if (prov.get("kind"), prov.get("sourceTool")) != ("internal_system", "cron"):
            return None
        hit = _CRON_PROMPT_RE.match(str(prov.get("sourcePromptPrefix") or ""))
        return prov.get("jobId") or (hit.group("job") if hit else None)
    hit = _CRON_PROMPT_RE.match(((_history_item(m) or {}).get("text") or "").lstrip())
    return hit.group("job") if hit else None


def wake_turns(messages: list) -> list:
    """[{key, at, job, shared_run}] of the cron wake turns, in transcript
    order: `key` is the turn id (its `:user` key without the suffix), `at` its
    commit time (`recordTimestampMs`), `job` the cron job id, `shared_run`
    True when the wake runs under the session's id (9.3, ELI-103). Reads
    `chat.history` as returned or with its roles restored (`_transcript_roles`)."""
    out = []
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        key = _history_user_run_id({**m, "role": "user"} if _is_forwarded_turn(m) else m)
        if not key or parse_pipe_run_id(key):
            continue
        job = _cron_turn_job(m)
        if not job:
            continue
        meta = m.get("__openclaw") if isinstance(m.get("__openclaw"), dict) else {}
        at = meta.get("recordTimestampMs") or m.get("timestamp")
        out.append({"key": key, "at": at if isinstance(at, (int, float)) else None,
                    "job": job, "shared_run": not m.get("provenance")})
    return out


def _shared_wake_turns(messages: list) -> list:
    """The wake turns whose wake runs under the session's id: the only ones a
    sessionId event can belong to."""
    return [w for w in wake_turns(messages) if w["shared_run"]]


def wake_turn_at(messages: list, at_ms: float, bound=frozenset()) -> dict | None:
    """The wake whose event was emitted at `at_ms`: the newest wake turn
    committed at or before it that no earlier wake on this session took
    (`bound`). None while it is not committed yet (the embedded runtime writes
    the user turn without awaiting it, embedded-agent-DNQn_PMM.mjs:5891): the
    caller tries again on the wake's next event."""
    for turn in reversed(_shared_wake_turns(messages)):
        if turn["at"] is not None and turn["at"] <= at_ms:
            return None if turn["key"] in bound else turn
    return None


def wake_turn_of_run(messages: list, job: str, start_ms: float, bound=frozenset()) -> dict | None:
    """The wake turn cron job `job`'s run that started at `start_ms` wrote:
    its newest turn committed since, unless an earlier wake took it. None
    while it is not committed yet: the embedded runtime writes it after the
    run's first events, so a turn is not looked for before the event (as
    `wake_turn_at` must, knowing no run)."""
    for turn in reversed(_shared_wake_turns(messages)):
        if turn["job"] == job and turn["at"] is not None and turn["at"] >= start_ms:
            return None if turn["key"] in bound else turn
    return None


def wake_span(messages: list, start_ms: float, end_ms: float) -> list:
    """A wake's assistant messages: runs on one session are serialized, and
    claude-cli imports its transcript stamped with the CLI's own times, so
    everything the wake wrote lies between its turn's commit and its terminal.
    A user turn queued meanwhile is committed inside that window too; it is
    not the wake's and is left out."""
    out = []
    for m in messages or []:
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        ts = m.get("timestamp")
        if isinstance(ts, (int, float)) and start_ms <= ts <= end_ms:
            out.append(m)
    return out


# --- thinking --------------------------------------------------------------
# Shared by BOTH the Thinking filter and the Pipe: the filter offers the levels
# and the pipe enforces them against the live session ladder, so the ranks and
# the clamping rule have to be one implementation, not two that agree today.
#
# Deliberately has no imports, no classes, and no module-level names beyond the
# five below. It is concatenated into the Pipe artifact, where every name in it
# lands in the same flat namespace as every other fragment: a helper named like
# one of the pipe's own (a `_state_dir`, say) would silently shadow it
# depending on fragment order. Filter-only helpers live in `thinking_filter`
# for exactly that reason.

# ---------------------------------------------------------------------------
# Levels
# ---------------------------------------------------------------------------

# Ranks mirror the gateway's own table (off is genuinely a level, not an
# absence). Used to order the dropdown and to clamp downward, never upward:
# asking for less thinking than requested is a safe degradation, asking for
# more is a surprise on someone's bill.
LEVEL_RANKS = {
    "off": 0,
    "minimal": 10,
    "low": 20,
    "medium": 30,
    "adaptive": 30,
    "high": 40,
    "xhigh": 60,
    "max": 70,
    "ultra": 80,
}

# The sentinel meaning "do not send the field at all". Distinct from "off",
# which is an explicit instruction to not think. "default" leaves the agent's
# own configured level alone; "off" overrides it.
UNSET = "default"

# Used until the pipe has run once and written a real ladder cache. Every
# provider observed supports at least these, so nothing here can be a lie.
FALLBACK_LEVELS = ["off", "minimal", "low", "medium", "high"]

LADDER_CACHE_NAME = "thinking-ladders.json"

# The Gateway's rejection lists LABELS, not ids, and for most profiles the two
# are identical (`label: id`). The one divergence is the binary profile, which
# labels `low` as "on". Mapping it back is the difference between learning a
# model's real two-level ladder and learning a one-level lie.
LEVEL_LABEL_ALIASES = {"on": "low"}

# The exact anchors of the Gateway's hard validation error, e.g.:
#   Thinking level "high" is not supported for claude-cli/claude-opus-5. Use one of: off.
# All three must be present and in order. That is deliberately at least as
# narrow as matching the whole sentence: it can never fire on genuine assistant
# text that happens to discuss thinking levels.
_REJECT_HEAD = 'Thinking level "'
_REJECT_MID = '" is not supported for '
_REJECT_TAIL = ". Use one of: "


def parse_thinking_rejection(text):
    """Read the Gateway's own rejection as an authoritative per-model ladder.

    This exists because `sessions.describe` cannot be trusted for this. Describe
    builds its ladder with no model catalog in scope, so `resolveThinkingProfile`
    never sees the catalog's `reasoning: false` and falls through to the generic
    base profile -- it reported all 8 levels for `claude-cli/claude-opus-5`,
    whose real ladder is `["off"]`. The send path resolves the same question
    WITH the catalog and rejects. So the rejection is the only place the truth
    is stated, and throwing it away is what made this misfire once per turn
    forever instead of once per model.

    Returns None when `text` is not that rejection. Otherwise a dict:
    `{"level": requested, "model": "provider/model", "levels": [ids]}`.
    `levels` may be empty if every listed label is unrecognised -- the caller
    still learns which model rejected which level, so it must check for None
    rather than for falsiness.

    Pure string parsing on purpose: this fragment is shared with the Thinking
    filter, which imports nothing (not even `re`) so that a filter running on
    every message can never fail on an import it did not need.
    """
    if not text:
        return None
    head = text.find(_REJECT_HEAD)
    if head < 0:
        return None
    level_start = head + len(_REJECT_HEAD)
    mid = text.find(_REJECT_MID, level_start)
    if mid < 0:
        return None
    tail = text.find(_REJECT_TAIL, mid)
    if tail < 0:
        return None

    level = text[level_start:mid].strip().lower()
    model = text[mid + len(_REJECT_MID):tail].strip()
    if not level or not model or " " in model:
        # A model ref never contains a space. Anything that does means the
        # anchors matched something that merely reads like the rejection.
        return None

    listed = text[tail + len(_REJECT_TAIL):]
    stop = listed.find(".")
    if stop >= 0:
        listed = listed[:stop]
    levels = []
    for token in listed.split(","):
        name = token.strip().lower()
        name = LEVEL_LABEL_ALIASES.get(name, name)
        if name in LEVEL_RANKS and name not in levels:
            levels.append(name)
    levels.sort(key=lambda lv: LEVEL_RANKS[lv])
    return {"level": level, "model": model, "levels": levels}


def clamp_to_ladder(level, ladder):
    """Fit a requested level to what a model actually supports.

    Returns (resolved_level, note). `note` is None when the request went
    through untouched, otherwise a short human sentence explaining what
    changed, which the caller is expected to show rather than swallow.

    Clamping is always downward to the nearest supported rank. If the model
    supports nothing at or below the request (a ladder of only higher levels,
    which no observed provider has, but which costs nothing to handle), the
    lowest supported level is used.
    """
    if not level or level == UNSET:
        return None, None
    if not ladder:
        # No ladder known: pass the request through and let the gateway rule on
        # it. Silently dropping a level the user explicitly picked is worse.
        return level, None
    if level in ladder:
        return level, None

    want = LEVEL_RANKS.get(level)
    if want is None:
        return None, f"Unknown thinking level {level!r}, ignoring it."

    ranked_ladder = [lv for lv in ladder if lv in LEVEL_RANKS]
    if not ranked_ladder:
        return None, "This model reported no recognized thinking levels; ignoring the selection."

    at_or_below = [lv for lv in ranked_ladder if LEVEL_RANKS[lv] <= want]
    if at_or_below:
        best = max(at_or_below, key=lambda lv: LEVEL_RANKS[lv])
    else:
        best = min(ranked_ladder, key=lambda lv: LEVEL_RANKS[lv])
    return best, (
        f"This model does not support thinking level {level!r}, "
        f"using {best!r} instead."
    )


# --- gateway ---------------------------------------------------------------
GATEWAY_SCOPES = ["operator.admin", "operator.read", "operator.write"]
# A connection for users not in OWNER_USERS. Without operator.admin the
# Gateway does not record its turns as the owner's, and the agent withholds
# owner-only tools from them. read: history, sessions, models, usage and the
# event subscriptions. write: send, abort and the model override.
RESTRICTED_SCOPES = ["operator.read", "operator.write"]


def _parse_owner_users(raw: str) -> frozenset:
    """OWNER_USERS as a set of lowercase user ids and emails."""
    return frozenset(p.strip().lower() for p in (raw or "").split(",") if p.strip())


def _is_owner_user(owners: frozenset, user_id, email) -> bool:
    """An empty list makes everyone an owner (the behaviour before the valve)."""
    if not owners:
        return True
    return any(v and str(v).strip().lower() in owners for v in (user_id, email))


# The requests that start, steer or end a run. The Gateway records a turn as
# the owner's when the connection that sends it holds operator.admin, so these
# go out only through `_run_request`, which picks the connection.
RUN_SEND, RUN_ABORT, RUN_PATCH = "chat.send", "chat.abort", "sessions.patch"
# chat.send fields the Gateway accepts only from an operator.admin connection
# ("system provenance fields require admin scope"). A send over the restricted
# connection leaves them out; the conversation metadata block goes in the
# message text instead (see `_non_owner_send_params`).
ADMIN_ONLY_SEND_FIELDS = (
    "systemInputProvenance",
    "systemProvenanceReceipt",
    "suppressCommandInterpretation",
    "originatingChannel",
    "originatingTo",
    "originatingAccountId",
    "originatingThreadId",
)
_OWUI_KEY_USER = re.compile(r"^agent:[^:]+:openwebui-([0-9a-fA-F-]{36})-")


# ---------------------------------------------------------------------------
# Custom exceptions
# ---------------------------------------------------------------------------

class GatewayError(Exception):
    """Raised when the Gateway WebSocket handshake fails, or a request is
    refused. `error` is the refusal's error shape ({code, message, details,
    retryable, retryAfterMs}), when the Gateway sent one."""

    def __init__(self, message: str = "", error: dict | None = None):
        super().__init__(message)
        self.error = error or {}


# How long to wait for the Gateway's TCP/WS accept before giving up. Mirrors
# websockets' own open_timeout default; kept explicit so the bound is visible
# and tunable in one place rather than inherited silently.
_GATEWAY_CONNECT_TIMEOUT_S = 10.0

# Largest Gateway frame the socket accepts. websockets defaults to 1 MiB and
# answers a bigger frame by closing the WHOLE connection (1009, "message too
# big"), dropping every session's events: a long `chat.history` is several
# MB, and one large tool result in an agent or `session.message` event is
# enough. Bounded, not None, so a
# runaway frame still can't take the Open WebUI process's memory with it.
GATEWAY_WS_MAX_SIZE = 64 * 1024 * 1024


def _explain_connect_rejection(message: str, *, device_id: str | None = None) -> str:
    """Turn the Gateway's terse connect rejection into something actionable.

    Device approval is a mandatory step of every first install, not an
    exceptional case, yet the raw response is just "pairing required" -- and the
    command that fixes it appears nowhere in the product, only in the README.
    The device id the operator has to match is already in hand here.
    """
    lowered = message.lower()
    if "pairing" in lowered or "not approved" in lowered:
        ident = f"\n\nThis device's id is `{device_id}`." if device_id else ""
        return (
            "This Open WebUI instance is not an approved device on the OpenClaw "
            "Gateway yet.\n\nOn the Gateway host, run:\n\n"
            "    openclaw devices list\n"
            "    openclaw devices approve <request-id>\n"
            f"{ident}\n\nThen send your message again."
        )
    if any(k in lowered for k in ("unauthor", "invalid token", "forbidden", "bad token")):
        return (
            f"The Gateway rejected the credentials ({message}). Check the "
            "GATEWAY_TOKEN valve in Open WebUI under Admin Panel > Functions > "
            "OpenClaw Gateway > valves; it must match `gateway.auth.token` in "
            "your OpenClaw config."
        )
    return message


def _parse_gateway_url(raw: str) -> tuple[str, int]:
    """Parse the GATEWAY_URL valve into (host, port).

    The valve wants a bare ``host:port`` -- but it renders as a text box that
    looks exactly like a URL field, so pasting ``http://host:18789`` is the
    single most likely new-user mistake. A naive ``rsplit(":", 1)`` handles that
    input catastrophically quietly:

      ``http://gw:18789``  -> host ``http://gw``  -> websockets parses the
                              hostname as literally ``http`` on port 80
      ``http://gw``        -> ``int("//gw")`` -> a raw ValueError that escapes
                              pipe()'s ``except GatewayError`` and surfaces as
                              an unattributed error naming no valve

    So: accept a scheme and strip it (being liberal costs three lines and kills
    the whole failure class), and raise a GatewayError naming the valve for
    anything still unparseable, so it lands in the one handler that prints
    nicely into the chat.
    """
    value = (raw or "").strip()
    if not value:
        raise GatewayError(
            "The GATEWAY_URL valve is empty. Set it to your OpenClaw Gateway "
            "as host:port, for example localhost:18789."
        )
    if "://" in value:
        scheme, _, value = value.partition("://")
        if scheme.lower() not in ("ws", "wss", "http", "https"):
            raise GatewayError(
                f"GATEWAY_URL has an unsupported scheme '{scheme}://'. Use a "
                "bare host:port, for example localhost:18789."
            )
    # Drop any path/query a pasted URL dragged along ("host:8443/" -> "host:8443").
    value = value.split("/", 1)[0].split("?", 1)[0]

    if value.startswith("["):
        # Bracketed IPv6, "[::1]:18789". Split on the closing bracket, not the
        # last colon, and keep the brackets -- websockets needs them in the URL.
        addr, sep, rest = value.partition("]")
        if not sep:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} is missing a closing ']' on the IPv6 "
                "address. Expected [address]:port, for example [::1]:18789."
            )
        inner = addr[1:]
        # Brackets mean IPv6 to every URL parser. If the contents are not an
        # IPv6 literal, websockets' urlsplit().hostname raises a bare ValueError
        # -- which is neither OSError nor WebSocketException, so it escapes the
        # connect handler AND pipe()'s except GatewayError. Reject it here.
        # This is reachable by following our own advice: the bare-IPv6 branch
        # below says "wrap it in brackets", and a user who wraps a *hostname*
        # lands exactly on this input.
        try:
            ipaddress.IPv6Address(inner)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has {inner!r} in brackets, but brackets "
                "are only for IPv6 literals. Use a plain host:port such as "
                f"{inner}:18789, or bracket an actual IPv6 address like "
                "[::1]:18789."
            )
        host = addr + "]"
        port_str = rest[1:] if rest.startswith(":") else (rest or "18789")
    elif value.count(":") > 1:
        # More than one colon and no brackets. If it parses as IPv6, say so;
        # otherwise it is something like "host:80:90" or a pasted URL with
        # userinfo, and calling that "an IPv6 address" would be wrong.
        try:
            ipaddress.IPv6Address(value)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has more than one ':' and is not an IPv6 "
                "address, so the port is ambiguous. Expected host:port, for "
                "example localhost:18789."
            )
        # A bare IPv6 literal. rpartition(":") would read "::1" as host ":" on
        # port 1 -- silently wrong on both counts, which is the whole failure
        # class this function exists to remove.
        raise GatewayError(
            f"GATEWAY_URL {raw!r} is an IPv6 address. Wrap it in brackets so "
            "the port is unambiguous, for example [::1]:18789."
        )
    else:
        host, sep, port_str = value.rpartition(":")
        if not sep:
            host, port_str = value, "18789"

    if not host or host == "[]":
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has no host. Expected host:port, "
            "for example localhost:18789."
        )
    if not (port_str.isascii() and port_str.isdigit()):
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has a non-numeric port {port_str!r}. "
            "Expected host:port, for example localhost:18789."
        )
    port = int(port_str)
    if not 1 <= port <= 65535:
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has port {port}, which is outside 1-65535. "
            "The OpenClaw Gateway default is 18789."
        )
    return host, port


# Budget for reading back an interrupted turn's tail. `chat.history` honors
# maxChars per message (schema max 500000) up to a 128 KiB per-message byte
# cap; 50000 chars stays under that cap even for 2-byte scripts like Hebrew.
RECOVERY_HISTORY_LIMIT = 40
RECOVERY_HISTORY_MAX_CHARS = 50000


def _event_frame(payload: dict) -> dict:
    """A routed event payload as the receive loop hands frames to an inline
    reply, which reads `msg["payload"]`: a `chat` event has a state and no
    stream, anything else (including a rebuilt session.tool copy) is `agent`."""
    event = "chat" if "state" in payload and "stream" not in payload else "agent"
    return {"type": "event", "event": event, "payload": payload}


def _history_item(message) -> dict | None:
    """Flatten one `chat.history` message to {role, text}. Only `text` blocks
    count: tool calls, tool results and thinking blocks are not part of the
    visible answer."""
    if not isinstance(message, dict):
        return None
    content = message.get("content")
    if isinstance(content, str):
        text = content
    elif isinstance(content, list):
        text = "".join(
            str(block.get("text") or "")
            for block in content
            if isinstance(block, dict) and block.get("type") == "text"
        )
    else:
        text = str(message.get("text") or "")
    return {"role": message.get("role"), "text": text}


def _history_recovery_text(history: dict, user_text: str) -> str | None:
    """Return the full assistant text saved after this user message, read from
    a `chat.history` response."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    return _recovery_text_from_items([_history_item(m) for m in messages], user_text)


def _recovery_user_text_matches(item_text: str, user_text: str) -> bool:
    """True if a stored user message is the one this turn sent.

    The transcript can hold it verbatim or behind the Gateway's metadata
    envelope ("Conversation info (untrusted metadata): ...", then a blank
    line, then the text).
    """
    return item_text == user_text or item_text.endswith("\n" + user_text)


def _recovery_text_from_items(items, user_text: str) -> str | None:
    """The turn's final assistant text: the LAST non-empty assistant item after
    the last user item matching `user_text`, stopping at the next user message.

    Last, not first: a tool-using turn stores several assistant messages. On
    the claude-cli runtime the closing one repeats the whole turn's text
    (preambles included); on the embedded runtime it is the final answer. The
    first one is only the opening preamble ("I'll look at ...").
    """
    if not isinstance(items, list):
        return None

    normalized_user_text = (user_text or "").strip()
    if not normalized_user_text:
        return None

    last_matching_user_index = None
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            continue
        if item.get("role") != "user":
            continue
        if _recovery_user_text_matches(
            str(item.get("text", "")).strip(), normalized_user_text
        ):
            last_matching_user_index = idx

    if last_matching_user_index is None:
        return None

    found = None
    for item in items[last_matching_user_index + 1:]:
        if not isinstance(item, dict):
            continue
        text = str(item.get("text", "")).strip()
        if item.get("role") == "user" and text:
            break  # the next turn; tool results are user items with no text
        if item.get("role") == "assistant" and text:
            found = text
    return found


async def _recover_turn_text(conn, session_key: str, user_text: str) -> str | None:
    """Read back the assistant text of a turn whose live stream was lost,
    from `chat.history`, which returns the message whole (ELI-74)."""
    try:
        history = await conn.session_history(session_key)
    except Exception as ex:
        pipe_log(f"  history recovery failed: {ex}")
        return None
    text = _history_recovery_text(history, user_text)
    if not text:
        pipe_log("  history recovery found no reply")
    return text


def _owui_session_key(agent_id: str, user_id: str, chat_id: str) -> str:
    return f"agent:{agent_id}:openwebui-{user_id}-{chat_id}"


def _session_thinking_ladder(desc: dict) -> list | None:
    """Pull the thinking levels a session's CURRENT model supports out of a
    `sessions.describe` response.

    `models.list` cannot answer this: it carries a `reasoning` boolean and
    nothing else. `agents.list` does carry a ladder, but the agent's PRIMARY
    model's, which is wrong the moment a session overrides the model. Only
    describe reflects what is actually resolved for this session right now.

    `thinkingLevels` is authoritative: the gateway defines it as the raw
    `{id, label}` objects (`resolveGatewaySessionThinkingProjectionInternal`
    -> `thinkingLevels: metadata.levels`), keyed by the canonical lowercase
    ids (`off`, `minimal`, ...) that LEVEL_RANKS and clamp_to_ladder match
    against. `thinkingOptions` is display-only -- the SAME gateway function
    derives it as `metadata.levels.map(level => level.label)`, i.e. human
    labels ("Off", "Extra High", ...), not ids. Matching a requested level
    against labels silently breaks clamping (nothing in LEVEL_RANKS looks
    like a label), so `thinkingOptions` must never be used for the ladder:
    an unsupported level would fall through the clamp and reach the
    gateway's own hard validation error on every turn (ELI-85). Kept only as a last-resort fallback in case a future gateway build ever
    stops emitting `thinkingLevels` -- an imperfect ladder beats none.

    Returns None (not []) when the field is absent, because "no ladder known"
    and "this model supports nothing" have to lead to different behaviour: the
    first passes the request through to the gateway, the second would clamp
    every request away.
    """
    row = (desc or {}).get("session") or {}
    levels = row.get("thinkingLevels")
    if isinstance(levels, list) and levels:
        out = [str(lv.get("id")) for lv in levels
               if isinstance(lv, dict) and lv.get("id")]
        if out:
            return out
    opts = row.get("thinkingOptions")
    if isinstance(opts, list) and opts:
        return [str(x).strip().lower() for x in opts]
    return None


def _session_model_key(row) -> str | None:
    """`provider/model` for a `sessions.describe` row, or None.

    Formatted to match the Gateway's own rejection text verbatim
    ("...is not supported for claude-cli/claude-opus-5.") so a ladder learned
    from a rejection and one observed from describe key the same entry.
    """
    row = row or {}
    provider = str(row.get("modelProvider") or "").strip()
    model = str(row.get("model") or "").strip()
    if not provider or not model:
        return None
    return f"{provider}/{model}"


def _ladder_cache_path(state_dir: str = "") -> str:
    return os.path.join(_state_dir(state_dir), LADDER_CACHE_NAME)


# Guards the ladder cache's read-merge-write sequence below. Pipe and Status
# Action requests can land in different threads of the same OWUI process, and
# without this a slower worker's read-merge-write can finish after a faster
# one's and silently drop the faster worker's update. A unique temp file (see
# _write_json_file) only makes each individual write atomic; it does nothing
# for two workers racing on the read-then-write in between.
_LADDER_CACHE_LOCK = threading.Lock()


def _record_thinking_ladder(levels, model_key=None, authoritative=False,
                             state_dir: str = "") -> None:
    """Fold a ladder we just saw into the cache, both as a union and per model.

    Two different consumers, two different needs, one file:

    * `levels` (union across every model seen) is what the Thinking filter
      offers, because Open WebUI builds a valve dropdown once from the class
      and cannot vary it per selected model.
    * `models[<provider/model>]` is what the SEND path clamps against, and it
      must be exact: clamping against the union lets `high` reach a model
      whose only level is `off`.

    `authoritative` marks a ladder the Gateway stated itself by rejecting a
    send. A merely observed one (from `sessions.describe`) must never overwrite
    it: describe resolves the ladder with no model catalog in scope and so
    reports the generic base profile for catalog-gated models.

    Best-effort by design: a failed write costs a stale dropdown and one more
    rejected turn, and must never affect the message being sent.
    """
    known = [lv for lv in (levels or []) if lv in LEVEL_RANKS]
    path = _ladder_cache_path(state_dir)

    with _LADDER_CACHE_LOCK:
        current = _read_json_file(path) or {}

        have = current.get("levels")
        have = [x for x in have if x in LEVEL_RANKS] if isinstance(have, list) else []
        merged = sorted(set(have) | set(known), key=lambda lv: (LEVEL_RANKS[lv], lv))

        models = current.get("models")
        models = dict(models) if isinstance(models, dict) else {}
        model_changed = False
        if model_key:
            prior = models.get(model_key)
            prior = prior if isinstance(prior, dict) else {}
            if prior.get("source") == "gateway" and not authoritative:
                # Keep the stated truth; a describe-sourced ladder is not
                # evidence against it.
                pass
            else:
                entry = {
                    "levels": known,
                    "source": "gateway" if authoritative else "describe",
                    "updated": int(time.time()),
                }
                if (prior.get("levels") != entry["levels"]
                        or prior.get("source") != entry["source"]):
                    models[model_key] = entry
                    model_changed = True

        if merged == have and not model_changed:
            return
        payload = {"levels": merged, "updated": int(time.time())}
        if models:
            payload["models"] = models
        if not _write_json_file(path, payload):
            return
    if merged != have:
        pipe_log(f"thinking ladder cache updated: {merged}")
    if model_changed:
        pipe_log(
            f"thinking ladder for {model_key}: {known} "
            f"({'stated by gateway' if authoritative else 'observed'})"
        )


def _read_model_thinking_ladder(model_key, state_dir: str = ""):
    """The exact ladder for one model, or None if we have not learned it.

    None and [] mean different things here and the caller relies on it: None is
    "unknown, pass the request through", [] would be "supports nothing", which
    no model is. Entries that somehow persisted empty are treated as unknown.
    """
    if not model_key:
        return None
    cache = _read_json_file(_ladder_cache_path(state_dir)) or {}
    models = cache.get("models")
    if not isinstance(models, dict):
        return None
    entry = models.get(model_key)
    if not isinstance(entry, dict):
        return None
    levels = entry.get("levels")
    if not isinstance(levels, list):
        return None
    known = [lv for lv in levels if lv in LEVEL_RANKS]
    return known or None


def _owui_chat_send_params(
    session_key: str,
    message: str,
    idempotency_key: str,
    owui_chat_id: str | None,
    owui_user_id: str | None,
    attachments: list | None = None,
    thinking: str | None = None,
) -> dict:
    params = dict(
        sessionKey=session_key,
        message=message,
        idempotencyKey=idempotency_key,
    )
    if attachments:
        params["attachments"] = attachments
    # Only when actually chosen. chat.send reads an absent `thinking` as "use
    # whatever the agent is configured for", which is a different instruction
    # from any value we could send, "off" very much included.
    if thinking:
        params["thinking"] = thinking
    if owui_chat_id:
        metadata = {
            "chat_id": owui_chat_id,
            "source": "openwebui",
        }
        if owui_user_id and owui_user_id != "unknown":
            metadata["user_id"] = owui_user_id
        params["systemProvenanceReceipt"] = "\n".join([
            "Conversation info (untrusted metadata):",
            "```json",
            json.dumps(metadata, ensure_ascii=False, indent=2),
            "```",
        ])
    return params


def _resolved_model_key(patch_resp: dict) -> str | None:
    resolved = patch_resp.get("resolved", {})
    provider = resolved.get("modelProvider")
    model = resolved.get("model")
    if provider and model:
        return f"{provider}/{model}"
    return None


# Provider namespaces that name a *serving runtime* rather than the model's
# canonical API vendor. A model keyed under one of these (e.g.
# "claude-cli/claude-opus-5") resolves, on sessions.patch, to the model's
# canonical provider ("anthropic/claude-opus-5") -- the gateway always reports
# the vendor, not the runtime. Without treating these as equal, any model
# keyed by its runtime can never pass the post-patch equality check and the
# pipe wrongly aborts with "model override did not apply" (opus-5 was the only
# such model; the claude-cli/ key was chosen deliberately to avoid a separate
# compaction bug, so the fix belongs here, not in gateway config).
_RUNTIME_PROVIDER_NAMESPACES = {"claude-cli", "google-gemini-cli", "codex-cli"}


def _model_patch_matches(model_override: str | None, patch_resp: dict) -> bool:
    if model_override is None:
        return True
    if _resolved_model_key(patch_resp) == model_override:
        return True
    # Runtime-namespaced key (claude-cli/<id>) vs canonical vendor readback
    # (anthropic/<id>): same model, different provider label -- treat as applied.
    if "/" in model_override:
        want_provider, want_model = model_override.split("/", 1)
        got_model = patch_resp.get("resolved", {}).get("model")
        if want_provider in _RUNTIME_PROVIDER_NAMESPACES and want_model == got_model:
            return True
    return False


def _coerce_text(value) -> str:
    """Extract text from common stream payload shapes."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("delta", "text", "content", "message"):
            text = _coerce_text(value.get(key))
            if text:
                return text
        return ""
    if isinstance(value, list):
        parts = [_coerce_text(item) for item in value]
        return "".join(part for part in parts if part)
    return ""


def _content_has_image(raw_content) -> bool:
    """True if an OWUI message's `content` is a multimodal block list
    that includes at least one image_url block. `content` is a
    plain string for ordinary text-only messages -- only the list shape
    (sent when a user attaches an image) can carry one, so this returns
    False immediately for the common string case."""
    if not isinstance(raw_content, list):
        return False
    return any(
        isinstance(block, dict) and block.get("type") == "image_url"
        for block in raw_content
    )


_DATA_URL_RE = re.compile(r"^data:([^;,]*)(?:;[^,]*)?,(.*)$", re.DOTALL)


def _extract_image_attachments(raw_content) -> list:
    """Pull inline images out of an OWUI multimodal `content` block list
    and shape them for the gateway's `chat.send` `attachments` param:
    `{type, mimeType, fileName, content}` with `content` as base64.

    OWUI sends attached/pasted images as `image_url` blocks whose `url` is
    a `data:<mime>;base64,<data>` URI -- there is no plain-HTTP(S)
    `image_url` case to support here, so anything else is skipped rather
    than guessed at.
    """
    if not isinstance(raw_content, list):
        return []
    attachments = []
    for idx, block in enumerate(raw_content):
        if not (isinstance(block, dict) and block.get("type") == "image_url"):
            continue
        image_url = block.get("image_url")
        url = image_url.get("url") if isinstance(image_url, dict) else None
        if not isinstance(url, str):
            continue
        match = _DATA_URL_RE.match(url.strip())
        if not match or ";base64" not in url.split(",", 1)[0]:
            continue
        mime = match.group(1) or "image/png"
        ext = mimetypes.guess_extension(mime) or ".png"
        attachments.append({
            "type": "image",
            "mimeType": mime,
            "fileName": f"image-{idx + 1}{ext}",
            "content": match.group(2),
        })
    return attachments


def _item_assistant_text(data: dict) -> str:
    """Return visible assistant text carried by item/preamble events."""
    kind = str(data.get("kind", "")).strip().lower()
    if kind not in ("assistant", "message", "output", "preamble"):
        return ""
    for key in ("delta", "text", "content", "message"):
        text = _coerce_text(data.get(key)).strip()
        if text:
            return text
    return ""


# Queue item `_GatewayConnection._mark_event_gap` puts where events were lost.
_GAP_MARKER_TYPE = "_pipe_gap"
# Queue item `_GatewayConnection._note_gateway_boot` puts in every run queue
# when a reconnect lands on a new Gateway process: the run may be gone, and
# its owner (DESIGN 2.7) is decided from its row, not by the reply.
_RESTART_MARKER_TYPE = "_pipe_restart"
# Queue item carrying a session row to the inline replies of that session:
# `{"type", "row", "resync"}`. A run's own settle row (hasActiveRun false,
# lastRunId = the run) ends its reply even when its final event was lost;
# `resync` marks a row read after a reconnect or a frame gap, where an idle
# session means every admitted run is over; a `queued` row tells a reply
# waiting for its first event why.
# `read_at` (time.monotonic) is when the row was read: a reply trusts an idle
# row only when it was read after its run was admitted.
_ROW_MARKER_TYPE = "_pipe_row"


# How much of the already-received text anchors a cumulative text that does not
# extend it by prefix. Long enough that a match means "this text contains what
# we have", never a coincidence of a short phrase ("OK.", "Done.").
_WHOLE_TEXT_ANCHOR_CHARS = 200
_MIN_WHOLE_TEXT_ANCHOR_CHARS = 64
_LINE_BREAKS_RE = re.compile(r"\n+")


def _one_break(text: str) -> str:
    """`text` with each run of line breaks as one: a claude-cli run's closer
    joins its messages by one newline, where the stream put the Gateway's
    two-newline message break (ELI-219)."""
    return _LINE_BREAKS_RE.sub("\n", text)


def _item_delta_text(item_text: str, last_item_text: str, assistant_stream_text: str) -> str:
    """Compute the new text (if any) an `item` event adds beyond what's
    already been shown, either by a prior `item` event or by the regular
    `assistant` delta stream.

    Some item events of kind "message"/"output" echo the *complete* final
    assistant text (not just a genuine tool-preamble) -- without this check
    that full text gets yielded a second time on top of what the assistant
    stream already delivered, duplicating the whole final message.
    """
    baseline = last_item_text or assistant_stream_text
    if not baseline:
        return item_text
    if item_text == baseline:
        return ""
    if item_text.startswith(baseline):
        return item_text[len(baseline):]
    if _one_break(item_text) == _one_break(baseline):
        return ""
    if last_item_text and item_text.endswith("\n" + last_item_text):
        # The run's whole text, its messages joined by newlines, closing with
        # the message item already shown: a claude-cli run's closer after a
        # second message (ELI-219), whose last item can be too short for the
        # anchors below.
        return ""
    # Not a prefix extension. If the item still contains the tail of what was
    # already received, it is the cumulative text with something missing
    # from the middle or the start (events lost while the Gateway socket was
    # reconnecting): only what follows that tail is new; returning the whole
    # item would post a second full copy of the reply. The missing piece comes back with the turn writer's transcript rebuild
    # (ELI-147), never appended here.
    # Shorter anchors too: the hole may sit inside the longest one.
    for n in (_WHOLE_TEXT_ANCHOR_CHARS, 128, _MIN_WHOLE_TEXT_ANCHOR_CHARS):
        anchor = baseline[-n:]
        if len(anchor) < _MIN_WHOLE_TEXT_ANCHOR_CHARS:
            break
        pos = item_text.rfind(anchor)
        if pos >= 0:
            return item_text[pos + len(anchor):]
    return item_text


def _suppress_already_shown(delta: str, visible_message_text: str) -> str:
    """Final safety net against re-yielding text that's already been shown.

    `_item_delta_text`'s dedup baseline (`assistant_stream_text` or
    `last_item_text`) is a separate accumulator from `visible_message_text`
    and can drift from it -- e.g. a provider's final catch-all event races
    an idle-timeout recovery cycle, or arrives after other text (tool
    blocks, recovered previews) has been recorded into
    `visible_message_text` without also updating `assistant_stream_text`.
    When that happens, `_item_delta_text`'s prefix check fails to match and
    it falls through to returning the *entire* cumulative text unchanged,
    which then gets appended a second time with no separator.

    `visible_message_text` is the true, complete record of everything
    already recorded for this turn, so checking whether `delta` is already
    its tail catches this regardless of which upstream baseline caused the
    false negative -- without touching the primary dedup logic (so a
    genuine partial catch-up, which is never already at the tail, still
    yields normally).
    """
    if delta and visible_message_text.endswith(delta):
        return ""
    return delta


def _attr(value: str) -> str:
    """Escape a string for use as an HTML attribute value in a tool card.

    `html.escape` alone is NOT enough here. OWUI's frontend parses these
    `<details>` attributes with a non-dotAll regex (`/(\\w+)="(.*?)"/g`, chunk
    `_UcCb4Vt.js`), so `.` never matches a newline: any attribute value
    containing a literal newline fails to match and is silently DROPPED -- the
    tool card then renders with INPUT and no OUTPUT at all, with no error.

    `arguments` is always `json.dumps`-ed, so its newlines are already the
    two-char `\\n` escape; a multi-line `result` is passed through raw.

    Encoding the newline as the numeric character reference `&#10;` keeps the
    attribute on one physical line for that regex while still decoding back to
    a real newline when the browser parses the attribute -- the same path that
    already turns `&quot;` into `"` in the rendered card.
    """
    return (
        html.escape(value)
        .replace("\r\n", "&#10;")
        .replace("\n", "&#10;")
        .replace("\r", "&#10;")
    )


# `output_index` for an item that goes at the end of Open WebUI's output
# list. Both of its reducers append an `output_item.added` whose index is at
# or past the end; without one, the backend appends but the chat tab splices
# the item in before the last one (ELI-122). The pipe cannot see that list
# (a tag in the text can add items to it), so it names no exact length.
_OUTPUT_APPEND_INDEX = 1 << 30


def _tool_call_started_event(name: str, tool_call_id: str, args_str: str) -> dict:
    """Announce a tool call as a Responses-API output item (live spinner).

    Yielding a *dict* from the pipe is a supported protocol switch: OWUI
    serializes it verbatim as an SSE `data:` line (`functions.py::process_line`)
    instead of wrapping it in a chat chunk, and any event whose `type` starts
    with `response.` is folded into the backend's OWN output list by
    `handle_responses_streaming_event` (`middleware.py`).

    That matters because the backend's output list is what feeds the live
    `chat:completion` emissions, the final done event AND the DB write -- so a
    tool call announced this way is mutable, unlike yielded markdown, which is
    append-only for the rest of the turn. The frontend renders a `function_call` with no matching
    `function_call_output` as a spinner (`structuredOutput.ts::buildToolCallToken`).

    Ordering is by arrival: the item goes at the end of the output list, after
    the text streamed before it. It says so with `output_index`
    (`_OUTPUT_APPEND_INDEX`): the backend appends an item without one, but
    the chat tab's reducer (`structuredOutput.ts::applyResponseStreamEvent`)
    splices it in BEFORE the last item, and the live card would show above
    the text written before the call until a reload (ELI-122).

    The tool call id goes in `id`, and `call_id` is deliberately ABSENT.
    Open WebUI replaces an added item that shares its `id` or its `call_id`
    with one it holds:

        existing_index = next(idx for idx, existing in enumerate(new_output)
            if (item['id'] and existing['id'] == item['id'])
            or (item['call_id'] and existing['call_id'] == item['call_id']))
        if existing_index is not None: new_output[existing_index] = item

    -- so the `function_call_output` we send next, which must share the call
    id to pair, would match this item on `call_id` and REPLACE it. The card
    is built from the `function_call` item alone (`structuredOutput.ts`
    reads `call_id ?? id` and looks the output up in a by-call_id map), so
    losing it means no card at all.

    Carrying the id in `id` only keeps both items distinct for the dedup
    (`<tid>` vs `fco_<tid>`, and neither has a `call_id` the other shares)
    while every consumer that matters reads `call_id or id`:
    `structuredOutput.ts` for the card, `middleware.py`'s post-stream sweep
    for the "already has a result, don't execute it" guard, and
    `pause_for_tool_approval`, which even backfills `call_id` from `id`.
    """
    return {
        "type": "response.output_item.added",
        "output_index": _OUTPUT_APPEND_INDEX,
        "item": {
            "type": "function_call",
            "id": tool_call_id,
            "name": name,
            "arguments": args_str[:3000],
            "status": "in_progress",
        },
    }


# A note the Pipe adds to a reply (ELI-197): a Responses message item of its
# own, carried as a run event of this made-up stream so the live reply and a
# turn writer show it through the same `_TurnRenderer`. Its id is stable per
# note, so the same note again replaces it.
PIPE_NOTE_STREAM = "pipe_note"
_NOTE_ITEM_PREFIX = "msg_note_"


def _tool_call_result_event(tool_call_id: str, result_str: str) -> dict:
    """Complete a tool call announced by `_tool_call_started_event`.

    A `function_call_output` whose `call_id` matches the started item's id is
    what flips the card to done and reveals the Output section. If we never
    send one (run cancelled, pipe torn down), the backend still marks every
    leftover `in_progress` item completed before the final event, so a card
    can't be left spinning forever.

    This item keeps `call_id`; the started item does not carry one at all. See
    `_tool_call_started_event` for why that asymmetry is load-bearing on OWUI
    0.11.1+.
    """
    return {
        "type": "response.output_item.added",
        "output_index": _OUTPUT_APPEND_INDEX,
        "item": {
            "type": "function_call_output",
            "id": f"fco_{tool_call_id}",
            "call_id": tool_call_id,
            "output": [{"type": "output_text", "text": result_str[:8000]}],
            "status": "completed",
        },
    }


def _tool_result_text(result) -> str:
    """The text a tool card shows for a tool event's `result`.

    OpenClaw sends a string, a list of content blocks, or the agent-tool
    envelope `{"content": [...], "details": {...}}` (`sanitizeToolResult`).
    The card shows the content: text blocks one per line, an image (its data
    is already stripped) as a short note. `details` is the tool's metadata
    (status, exit code, cwd, ...), not its output; dumping the whole envelope
    put it in every card (ELI-121). Anything else is shown as JSON.
    """
    if isinstance(result, str):
        return result
    blocks = result.get("content") if isinstance(result, dict) else result
    if not isinstance(blocks, list):
        return json.dumps(result)
    lines = []
    for block in blocks:
        kind = block.get("type") if isinstance(block, dict) else None
        if kind == "text" and isinstance(block.get("text"), str):
            lines.append(block["text"])
        elif kind == "image":
            lines.append(f"[{block.get('mimeType') or 'an'} image]")
        else:
            lines.append(block if isinstance(block, str) else json.dumps(block))
    return "\n".join(lines)


TOOL_ERROR_MARK = "❌"
# What a call the run ended without answering shows as its output.
TOOL_NO_RESULT_NOTE = "(no result -- the run ended first)"

# A sub-agent's title is one line on a phone: its spawn label, else its
# task's first sentence cut to this many characters. The Status Action's
# rows and drawer use it too (ELI-155).
SUBAGENT_TITLE_MAX = 60
_FIRST_SENTENCE_RE = re.compile(r"(?<=[.!?])\s|\n")
# How much of a sub-agent's task its spawn card shows as input.
SPAWN_TASK_LINES = 3
SPAWN_TASK_CHARS = 300


def _short_title(text: str) -> str:
    """The first sentence of `text`, cut on a word to SUBAGENT_TITLE_MAX
    characters with an ellipsis: a sub-agent's title when it has no label."""
    first = _FIRST_SENTENCE_RE.split(text.strip(), 1)[0].strip()
    if len(first) <= SUBAGENT_TITLE_MAX:
        return first
    cut = first[:SUBAGENT_TITLE_MAX - 1]
    space = cut.rfind(" ")
    if space >= SUBAGENT_TITLE_MAX // 2:
        cut = cut[:space]
    return cut.rstrip(" ,;:(") + "…"


def _is_spawn_tool(name: str) -> bool:
    """`sessions_spawn`, bare (the Gateway's runtime) or as claude-cli names
    the OpenClaw MCP tool (`mcp__openclaw__sessions_spawn`)."""
    return name == "sessions_spawn" or (name.startswith("mcp__")
                                        and name.endswith("__sessions_spawn"))


def _json_object(text: str) -> dict:
    try:
        value = json.loads(text)
    except (TypeError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _spawn_title(args: dict) -> str:
    """A sub-agent's name: its spawn label, else its task's first sentence."""
    task = str(args.get("task") or "").strip()
    return str(args.get("label") or "").strip() or (_short_title(task) if task else "Sub-agent")


def _spawn_task_head(task: str) -> str:
    """The first SPAWN_TASK_LINES lines of a task, at most SPAWN_TASK_CHARS."""
    lines = [line for line in task.strip().splitlines() if line.strip()]
    head = "\n".join(lines[:SPAWN_TASK_LINES])
    if len(head) > SPAWN_TASK_CHARS:
        head = head[:SPAWN_TASK_CHARS - 1].rsplit(" ", 1)[0].rstrip(" ,;:(") + "…"
    elif len(lines) > SPAWN_TASK_LINES:
        head += "\n…"
    return head


# The tools a model calls a deferred tool through, by its catalog id or name:
# `tool_call` on OpenClaw 2026.10.1 to 10.4, `dispatch_action` from 10.10. The
# Gateway also reports the target as a nested call of its own
# (`parentToolCallId` = the wrapper's id, id `tool_call:<wrapper id>:...`).
DEFERRED_CALL_TOOLS = ("dispatch_action", "tool_call")


def _is_nested_tool_call(data: dict, known: "set | dict") -> bool:
    """A tool event for a call another call made on the model's behalf (the
    target of a deferred-tool wrapper). Its card is the wrapper's: a second
    card would show the same action twice, nested inside the first."""
    if data.get("parentToolCallId"):
        return True
    tcid = str(data.get("toolCallId") or "")
    parts = tcid.split(":")
    return len(parts) > 2 and parts[0] == "tool_call" and parts[1] in known


OPENCLAW_MCP_PREFIX = "mcp__openclaw__"


def _bare_tool_name(name: str) -> str:
    """An OpenClaw tool by the name the Gateway's live events give it. claude-cli
    calls them over MCP as `mcp__openclaw__<name>`, and its imported transcript
    keeps that name while the live events strip it, so a rebuilt card was
    titled differently from the one that streamed (on 2026.10 every claude-cli
    shell command: `exec`)."""
    return name[len(OPENCLAW_MCP_PREFIX):] if name.startswith(OPENCLAW_MCP_PREFIX) else name


def _deferred_call_view(name: str, args_str: str) -> tuple[str, str] | None:
    """A deferred-tool wrapper call as the call it makes: the target's name
    (the last part of a catalog id like `openclaw:core:session_status`) and
    its arguments. None for any other call."""
    if _bare_tool_name(name) not in DEFERRED_CALL_TOOLS:
        return None
    args = _json_object(args_str)
    target = args.get("id") if isinstance(args.get("id"), str) else args.get("name")
    if not isinstance(target, str) or not target.strip():
        return None
    inner = args.get("args")
    if not isinstance(inner, dict):  # a flattened call: the target's arguments beside `id`
        inner = {k: v for k, v in args.items() if k not in ("id", "name")}
    return target.strip().rsplit(":", 1)[-1], json.dumps(inner)


def _deferred_call_result_text(result_str: str) -> str:
    """The target's result inside a wrapper's `{"tool": ..., "result": ...}`
    envelope. Anything else (an error, external content in its fence) is
    shown as it came."""
    envelope = _json_object(result_str)
    if not isinstance(envelope.get("tool"), dict) or "result" not in envelope:
        return result_str
    return _tool_result_text(envelope["result"])


def _tool_card_view(name: str, args_str: str) -> tuple[str, str]:
    """The title and input a tool card shows. A spawn card is named after the
    sub-agent it started ("🤖 <label>") and shows the head of its task, not
    the whole prompt; any other card shows the call as made (ELI-155)."""
    name = _bare_tool_name(name)
    if not _is_spawn_tool(name):
        return name, args_str
    args = _json_object(args_str)
    task = str(args.get("task") or "")
    return f"🤖 {_spawn_title(args)}", json.dumps({"task": _spawn_task_head(task)} if task.strip() else {})


def _spawn_result_view(args_str: str, result_str: str) -> tuple[str, bool]:
    """A spawn's receipt as one line, and whether the spawn failed. The
    receipt is JSON ({status, childSessionKey, runId, ...} or {status,
    error}); anything else is shown as it came."""
    receipt = _json_object(result_str)
    status = receipt.get("status")
    if not isinstance(status, str):
        return result_str, False
    if status == "accepted":
        return f"Started: {_spawn_title(_json_object(args_str))}", False
    error = str(receipt.get("error") or "").strip()
    return f"Not started ({status})" + (f": {error}" if error else ""), True


def _spawned_child(payload: dict):
    """(parent session key, child session key) of a tool event that is an
    accepted spawn's result, else None: what the child index records. On
    2026.10 the wrapper's nested call carries the spawn itself; the wrapper's
    own envelope is read too."""
    data = payload.get("data") or {}
    if payload.get("stream") != "tool" or data.get("phase") != "result" or data.get("isError") is True:
        return None
    parent = payload.get("sessionKey")
    text = _tool_result_text(data.get("result", {}))
    name = _bare_tool_name(data.get("name") or "")
    if _is_spawn_tool(name):
        receipt = _json_object(text)
    elif name in DEFERRED_CALL_TOOLS:
        receipt = _json_object(_deferred_call_result_text(text))
    else:
        return None
    child = receipt.get("childSessionKey")
    if receipt.get("status") != "accepted" or not isinstance(child, str) or not child or not parent:
        return None
    return parent, child


def _spawn_call_task(payload: dict) -> str | None:
    """The task a tool event's spawn call was given (the call itself, or the
    one a deferred-tool wrapper makes), from its start event; else None."""
    data = payload.get("data") or {}
    if payload.get("stream") != "tool" or data.get("phase") != "start":
        return None
    name, args_str = _bare_tool_name(data.get("name") or ""), json.dumps(data.get("args") or {})
    view = _deferred_call_view(name, args_str)
    if view:
        name, args_str = view
    if not _is_spawn_tool(name):
        return None
    task = str(_json_object(args_str).get("task") or "").strip()
    return task or None


def _tool_call_error_relabel_event(name: str, tool_call_id: str, args_str: str) -> dict:
    """Re-announce a failed call's `function_call` item with ❌ in its name.

    The card's collapsed row shows `attributes.name` and nothing else about
    outcome: its status icon is chosen by `isDone` alone, with no failure
    branch (`ToolCallDisplay.svelte:136`), so a red icon is unreachable
    without patching OWUI. The name is the only outcome-carrying field we
    control, and it renders through `Markdown`, so an emoji survives.

    The event is the start event again, same id and arguments: both of OWUI's
    reducers replace an `output_item.added` item that has the id of one they
    hold, the backend (`handle_responses_streaming_event`, what is saved) and
    the chat tab (`structuredOutput.ts::applyResponseStreamEvent`, what shows
    while the reply streams). So the mark shows live, on any card, last or
    not. `response.name.done` would reach only the backend's last item, and
    the tab ignores it (ELI-124). (`response.output_item.done` replaces by
    position in the backend, which the pipe cannot know.)
    """
    return _tool_call_started_event(f"{name} {TOOL_ERROR_MARK}", tool_call_id, args_str)


def _tool_error_banner(result_str: str) -> str:
    """Prefix a failed tool's Output with an explicit failure line.

    Used both as the fallback when the card label can't be safely relabeled
    (parallel calls) and alongside a relabel, so the reason is visible once
    the card is expanded rather than only implied by the ❌.
    """
    return f"{TOOL_ERROR_MARK} tool call failed\n\n{result_str}"


def _render_tool_result_block(name: str, tool_call_id: str, args_str: str,
                              result_str: str, meta) -> str:
    """Render a finished tool call as OWUI's collapsible `tool_calls` card.

    The markdown path, used when native tool items are off and by the shadow
    `_TurnRenderer` (which completes a run's OWUI message when the inline turn
    ended early, outside any live stream -- so it has no protocol channel and
    must bake the card into text).
    """
    return (
        '\n<details type="tool_calls" done="true" '
        f'id="{_attr(tool_call_id)}" '
        f'name="{_attr(name)}" '
        f'arguments="{_attr(args_str[:3000])}" '
        f'result="{_attr(result_str[:8000])}" '
        f'meta="{_attr(str(meta)[:500])}" '
        'files="[]" embeds="[]">'
        f'\n<summary>{html.escape(name)}</summary>\n</details>\n'
    )


class _TurnRenderer:
    """Reconstructs the visible assistant content of a run from its raw gateway
    event stream, mirroring the inline pipe loop's rendering.

    Purpose: when the inline pipe generator ends BEFORE a long run finishes
    (cancel, or a torn-down request), the turn writer takes the message over
    (ELI-100). This renderer accumulates the COMPLETE content (assistant text
    + every tool block, in order) straight from the same events the
    persistent connection already dispatches, so the run's ORIGINAL OWUI
    message can be finalized to exactly what a non-interrupted turn would
    have stored.

    Scope: assistant text deltas, item-carried text, tool-result blocks, and
    the Pipe's own notes (`PIPE_NOTE_STREAM`).
    It holds the raw run text: the turn writer shows a resolved `MEDIA:` image
    and an answered ask-user card through the rewrites the inline reply
    recorded (`note_turn_rewrite`).
    """

    def __init__(self):
        self.visible_text = ""
        # The same run the way OWUI 0.12 stores a streamed reply: `text` is the
        # message `content` (assistant text only) and `output` holds the
        # Responses-API items the cards are drawn from. The frontend renders
        # `output` whenever a message has one, so a tool block baked into
        # `content` as markdown is no card there (ELI-92).
        self.text = ""
        self.output: list[dict] = []
        self._assistant_stream_text = ""
        self._last_item_text = ""
        self._active_tool_args: dict[str, str] = {}
        # A result may carry no tool name (claude-cli's `tool_result`).
        self._active_tool_names: dict[str, str] = {}
        self._tool_items: dict[str, dict] = {}
        self._tool_results: set[str] = set()
        # A new run continues the message (resume, recovery, answer run): its
        # first text gets the break the live stream puts between messages.
        # The Gateway inserts it only inside one run.
        self.run_boundary = False
        # Text that opens a message item and is, so far, a silent sentinel or
        # the start of one (`_add_text`).
        self._held = ""
        # The run answered with a silent sentinel alone (`flush`): no text is
        # its reply, not something lost.
        self.silenced = False

    @property
    def received(self) -> str:
        """All the run text that arrived, shown or not: the dedup baseline."""
        return self._assistant_stream_text

    @property
    def last_item(self) -> str:
        """The last item event's text, the baseline for the next one."""
        return self._last_item_text

    def seed(self, run_text: dict | None) -> None:
        """Continue a run another reply showed: take its dedup baselines, so
        its closing whole-text events are not shown again."""
        if run_text:
            self._assistant_stream_text = run_text.get("received", "")
            self._last_item_text = run_text.get("item", "")

    def drop_shown(self, shown: str) -> bool:
        """Drop the start of the run that `shown` is, which another message
        already holds (an adopted run, ELI-147): its text and the cards
        inside it. False, changing nothing, when the text does not start
        with it."""
        if not self.text.startswith(shown):
            return False
        cut, pos, kept = len(shown), 0, []
        for item in self.output:
            if item.get("type") == "message":
                text = item["content"][0]["text"]
                start, pos = pos, pos + len(text)
                if pos <= cut:
                    continue
                if start < cut:
                    item = copy.deepcopy(item)
                    item["content"][0]["text"] = text[cut - start:]
            elif pos < cut:
                continue
            kept.append(item)
        self.output, self.text = kept, self.text[cut:]
        self.visible_text = self.text
        return True

    def _add(self, chunk: str) -> None:
        if chunk:
            self.visible_text += chunk

    def _add_text(self, chunk: str) -> str:
        """Append `chunk` to the run's text; returns it as added. A message
        item that opens with a silent sentinel is held until it is told from
        text: a sentinel followed by more text is dropped, and the run's own
        answer follows (a claude-cli run that answered `NO_REPLY` and went on
        after its background task reported, ELI-219). A sentinel alone stays
        out; anything else is shown as it came (`flush` at the run's end)."""
        if not chunk:
            return ""
        last = self.output[-1] if self.output else None
        if last is None or last.get("type") != "message" or not last["content"][0]["text"]:
            pending = self._held + chunk
            lead = pending.lstrip()
            if any(s.startswith(lead) for s in _SILENT_SENTINELS):
                self._held = pending
                return ""
            self._held = ""
            for s in _SILENT_SENTINELS:
                if lead.startswith(s) and lead[len(s):len(s) + 1].isspace():
                    pipe_log(f"  dropped a leading {s} before the run's text")
                    pending = lead[len(s):].lstrip()
                    break
            chunk = pending
        return self._append_text(chunk)

    def flush(self) -> str:
        """The run ended, or a card follows: held text that is not a
        sentinel is shown after all; returns it as added."""
        held, self._held = self._held, ""
        if held.strip() in _SILENT_SENTINELS:
            self.silenced = True
        if not held.strip() or held.strip() in _SILENT_SENTINELS:
            return ""
        return self._append_text(held)

    def _append_text(self, chunk: str) -> str:
        if not chunk:
            return ""
        if self.run_boundary:
            self.run_boundary = False
            chunk = _message_boundary_separator(self.text, chunk) + chunk
        self._add(chunk)
        self.text += chunk
        last = self.output[-1] if self.output else None
        if (last is None or last.get("type") != "message"
                or str(last.get("id", "")).startswith(_NOTE_ITEM_PREFIX)):
            last = {
                "type": "message",
                "id": f"msg_{uuid.uuid4().hex[:24]}",
                "status": "in_progress",
                "role": "assistant",
                "content": [{"type": "output_text", "text": ""}],
            }
            self.output.append(last)
        last["content"][0]["text"] += chunk
        return chunk

    def _tool_item(self, name: str, tcid: str, args_str: str, events: list) -> dict:
        """The call's card, opened (and its start event added to `events`)
        the first time the call is seen, by its start or, when that was
        missed, by its result. `name` and `args_str` are as the card shows
        them (`_tool_card_view`)."""
        item = self._tool_items.get(tcid)
        if item is None:
            event = _tool_call_started_event(name, tcid, args_str)
            item = copy.deepcopy(event["item"])
            self._tool_items[tcid] = item
            self.output.append(item)
            events.append(event)
        return item

    def _unanswered(self, note: str) -> list[dict]:
        """A result event for every call with no result yet, saying `note`."""
        return [_tool_call_result_event(tcid, note) for tcid in self._tool_items
                if tcid not in self._tool_results]

    def close_open_calls(self, note: str) -> list[dict]:
        """Answer every call still open with `note` and return those events.
        Open WebUI runs a streamed `function_call` that has no output when
        the stream ends and sends the result back as a new turn; stored, it
        is a spinner forever."""
        events = self._unanswered(note)
        for event in events:
            self._tool_results.add(event["item"]["call_id"])
            self.output.append(copy.deepcopy(event["item"]))
        return events

    def finished_output(self) -> list[dict]:
        """`output` as stored once the run is over: a call the run never
        answered is closed, and every item still in progress is completed,
        as OWUI does before its final write."""
        out = copy.deepcopy(self.output)
        out += [e["item"] for e in self._unanswered(TOOL_NO_RESULT_NOTE)]
        for item in out:
            if item.get("status") == "in_progress":
                item["status"] = "completed"
        return out

    def feed(self, payload: dict) -> list:
        """Grow the run's content by one event. Returns what it added for a
        live stream: the new text (a str) and the Responses events of a tool
        card opened, relabelled as failed, or answered. The inline reply
        shows them, so it and a turn writer show the same text and cards
        (ELI-147)."""
        events: list = []
        data = payload.get("data", {}) or {}
        stream = payload.get("stream")
        name = data.get("name", "")
        phase = data.get("phase", "")

        if stream == "assistant":
            raw_delta = data.get("delta")
            if raw_delta:
                delta = raw_delta
            else:
                raw_text = data.get("text") or ""
                delta = (
                    _item_delta_text(raw_text, "", self._assistant_stream_text)
                    if raw_text else ""
                )
                if raw_text and not delta:
                    pipe_log("  suppressed duplicate catch-all assistant text")
                delta = _suppress_already_shown(delta, self.visible_text)
            if delta:
                if (
                    "Sender (untrusted metadata)" in delta
                    or "UnTrustedMetadata" in delta
                ):
                    pipe_log("  filtered metadata block")
                    return events
                self._assistant_stream_text += delta
                events.append(self._add_text(delta))

        if stream == "item":
            item_text = _item_assistant_text(data)
            if item_text:
                item_delta = _item_delta_text(
                    item_text, self._last_item_text, self._assistant_stream_text
                )
                self._last_item_text = item_text
                item_delta = _suppress_already_shown(item_delta, self.visible_text)
                if item_delta:
                    events.append(self._add_text(item_delta))

        if stream == PIPE_NOTE_STREAM:
            nid, text = data.get("id"), data.get("text")
            if nid and text:
                item = {"type": "message", "id": nid, "status": "completed", "role": "assistant",
                        "content": [{"type": "output_text", "text": text}]}
                at = next((n for n, i in enumerate(self.output) if i.get("id") == nid), None)
                if at is None:
                    self.output.append(item)
                else:
                    self.output[at] = item
                events.append({"type": "response.output_item.added",
                               "output_index": _OUTPUT_APPEND_INDEX, "item": copy.deepcopy(item)})
            return events

        if stream == "tool":
            tcid = data.get("toolCallId", "")
            if _is_nested_tool_call(data, self._active_tool_names.keys() | self._tool_results):
                return events
            if phase == "start":
                if tcid:
                    events.append(self.flush())
                    args_str = json.dumps(data.get("args", {}))
                    self._active_tool_args[tcid] = args_str
                    self._active_tool_names[tcid] = name
                    card_name, card_args = _tool_card_view(*(_deferred_call_view(name, args_str)
                                                             or (name, args_str)))
                    self._tool_item(card_name, tcid, card_args, events)
            elif phase == "result":
                if tcid and tcid in self._tool_results:
                    return events
                result = data.get("result", {})
                result_str = _tool_result_text(result)
                args_str = self._active_tool_args.pop(tcid, None) or json.dumps(
                    data.get("args", {})
                )
                name = self._active_tool_names.pop(tcid, None) or name
                deferred = _deferred_call_view(name, args_str)
                if deferred:
                    name, args_str = deferred
                    result_str = _deferred_call_result_text(result_str)
                failed = data.get("isError") is True
                if _is_spawn_tool(name) and not failed:
                    result_str, failed = _spawn_result_view(args_str, result_str)
                card_name, card_args = _tool_card_view(name, args_str)
                self._add(_render_tool_result_block(
                    card_name, tcid, card_args, result_str, data.get("meta", "")
                ))
                if tcid:
                    self._tool_results.add(tcid)
                    item = self._tool_item(card_name, tcid, card_args, events)
                    item["status"] = "completed"
                    if failed:
                        item["name"] = f"{card_name} {TOOL_ERROR_MARK}"
                        events.append(_tool_call_error_relabel_event(card_name, tcid, card_args))
                        result_str = _tool_error_banner(result_str)
                    event = _tool_call_result_event(tcid, result_str)
                    self.output.append(copy.deepcopy(event["item"]))
                    events.append(event)
        return events


# ---------------------------------------------------------------------------
# Persistent Gateway Connection (singleton)
# ---------------------------------------------------------------------------

# Anchor for state that must be shared by *every* `_GatewayConnection` alive in
# this Python process -- not just the current module's singleton. OWUI's function
# loader execs each redeploy into a brand-new module object with no teardown hook
# on the old one, so a connection left running by a previous deploy (a "zombie")
# keeps its own event loop. With private bookkeeping it would not know that the
# live connection already showed a run, and would write that turn into the chat
# a second time. Stashing the bookkeeping on
# `open_webui.socket.main` (OWUI's own stable module, never reloaded by our
# function) makes all connections read and write the *same* dicts. Since
# ELI-100 a retired connection writes no turns at all (`_turn_route_now`).
_SHARED_STATE_ATTR = "_openclaw_gateway_shared_state_v1"


def _shared_gateway_state() -> dict | None:
    """Return the process-global bookkeeping dicts shared across all
    `_GatewayConnection` instances, or None when not running inside OWUI
    (e.g. unit tests), in which case callers keep instance-local state so
    each test connection stays isolated."""
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return None
    state = getattr(_owui_socket_main, _SHARED_STATE_ATTR, None)
    if state is None:
        state = {}
        setattr(_owui_socket_main, _SHARED_STATE_ATTR, state)
    # `setdefault` per key (not a one-shot dict literal on the `is None`
    # branch): this same dict persists across redeploys of the function
    # (stashed on OWUI's stable socket module), so a *new* key added in a
    # later version must be backfilled into the already-existing dict --
    # otherwise `__init__` does `_shared["new_key"]` and KeyErrors on the
    # first request after redeploy.
    state.setdefault("delivered_live", {})
    state.setdefault("claimed_runs", {})
    state.setdefault("chat_write_locks", {})
    state.setdefault("turn_rewrites", {})
    return state


# The replies this process is streaming, for the Status Action (ELI-186):
# {(chat_id, message_id): the reply's _TurnRenderer}. Open WebUI saves a
# reply's tool cards (its `output`) only when the reply ends, in the chat and
# in its message row alike, so while it runs only the Pipe has them. The Pipe
# and the Action are separate Function modules: like the Pipe's shared state,
# the map lives on Open WebUI's own stable module, and outside Open WebUI on
# this one.
_LIVE_REPLIES_ATTR = "_openclaw_live_replies_v1"
_live_replies_local: dict = {}


def _live_replies() -> dict:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return _live_replies_local
    replies = getattr(_owui_socket_main, _LIVE_REPLIES_ATTR, None)
    if replies is None:
        replies = {}
        setattr(_owui_socket_main, _LIVE_REPLIES_ATTR, replies)
    return replies


def _live_reply_output(chat_id, message_id):
    """A copy of the tool cards and text a running reply shows so far, or
    None when this process streams no such reply."""
    renderer = _live_replies().get((chat_id, message_id))
    output = getattr(renderer, "output", None)
    return copy.deepcopy(output) if isinstance(output, list) else None


class _RunQueue(asyncio.Queue):
    """A run's event queue. Events wait for room (`await put`): a reply read
    slower than its run streams holds the receive loop back instead of losing
    text. Control markers (a gap, a restart, a session row) go in past the
    bound: they are few, a lost one can leave a reply that never ends, and
    the receive loop that puts them must never wait or raise: QueueFull there
    would kill the loop and hang every run on the connection."""

    def put_control(self, item) -> None:
        bound, self._maxsize = self._maxsize, 0
        try:
            self.put_nowait(item)
        finally:
            self._maxsize = bound

    def take_all(self) -> list:
        """Everything queued now, in order, without waiting."""
        items = []
        while not self.empty():
            items.append(self.get_nowait())
        return items


# Open WebUI's uvicorn Server, kept while it serves (see `owui_shutting_down`).
_UVICORN_SERVER = None


def remember_owui_server() -> None:
    """Keep a reference to the uvicorn Server that runs Open WebUI.

    uvicorn installs `Server.handle_exit` as the SIGTERM/SIGINT handler while
    it serves, and that sets `should_exit` when a signal arrives. It restores
    the old handlers before asyncio cancels the tasks still running, which is
    when Open WebUI's reply tasks reach the pipe, so the Server is taken from
    the handler earlier: at import and at every request."""
    global _UVICORN_SERVER
    if _UVICORN_SERVER is not None:
        return
    try:
        server = getattr(signal.getsignal(signal.SIGTERM), "__self__", None)
    except (ValueError, TypeError):
        return
    if server is not None and hasattr(server, "should_exit"):
        _UVICORN_SERVER = server


def owui_shutting_down() -> bool:
    """True once Open WebUI's server got SIGTERM or SIGINT (`ha apps stop`,
    restart, update). Its shutdown cancels every open reply the way a Stop
    does, and no page is left to say which it was (ELI-94)."""
    remember_owui_server()
    return bool(getattr(_UVICORN_SERVER, "should_exit", False))


remember_owui_server()


@dataclass
class _Consumer:
    """An active run consumer -- its ``asyncio.Queue`` receives events."""
    session_key: str
    run_id: str
    queues: list[asyncio.Queue] = field(default_factory=list)


# The turn writer's entry points (writer.py's `_TurnHooks`), which the Pipe
# build registers. None in the Status Action's build: it carries no turn
# writer, and its own connection only makes requests (ELI-149).
_TURNS = None
# The Pipe's handlers for `question.requested` / `question.resolved`
# (askuser.py, ELI-96), set by pipe.py. None in the Status Action, which asks
# nothing; only the connection that writes turns asks, so a question is asked once.
_QUESTION_HOOKS = None


class _GatewayConnection:
    """Singleton persistent WebSocket connection to the Gateway.

    Maintains one WS connection, dispatches events to per-run queues, and
    auto-reconnects on disconnect with exponential backoff.
    """

    def __init__(self, valves_ref, writes_turns: bool = True, scopes: list | None = None,
                 identity_name: str = "identity", requests_only: bool = False):
        # Weak reference to Pipe valves (re-read on each call)
        self._valves = valves_ref
        # The scopes this connection requests and signs. A connection built with
        # RESTRICTED_SCOPES has its own device identity (`identity_name`) and
        # only sends requests (`requests_only`: no subscriptions, it renders
        # nothing); see `_run_request`.
        self.scopes = list(GATEWAY_SCOPES if scopes is None else scopes)
        self._identity_name = identity_name
        self.requests_only = requests_only
        self._ws: websockets.WebSocketClientProtocol | None = None
        self._event_loop_task: asyncio.Task | None = None
        self._init_lock = asyncio.Lock()

        # Identity
        self._ident: dict | None = None
        self._device_token: str | None = None

        # Request-response futures (keyed by request id)
        self._pending_reqs: dict[str, asyncio.Future] = {}

        # Run consumers (keyed by f"{session_key}:{run_id}")
        self._consumers: dict[str, _Consumer] = {}

        # Per-session locks serializing the queue-release -> chat.send -> run
        # registration critical section (`session_send_lock`, ELI-56).
        self._session_send_locks: dict[str, asyncio.Lock] = {}
        # Open `send_section`s: a message waiting for its turn, then sending.
        # A retired connection stays up for them as it does for consumers:
        # closing it would leave the waiter with no settle push, ever (ELI-172).
        self._open_send_sections = 0

        # Cancelled turns parked until they are claimed or released, by
        # session key (`park_cancelled_turn`). An immediate chat.abort on a
        # cancel would kill the turn AND every subagent it spawned, and Send
        # now cancels the same way Stop does.
        self._pending_cancel_aborts: dict[str, dict] = {}

        # Last model applied per session, {session_key: (model, ts)}, and the
        # per-session patch locks (`model_patch_lock`, ELI-59). Each Open
        # WebUI worker process keeps its own.
        self._model_patch_cache: dict[str, tuple[str | None, float]] = {}
        self._model_patch_locks: dict[str, asyncio.Lock] = {}

        # Last thinking-clamp note shown per session, so a standing mismatch
        # between the picked level and the model's ladder is explained ONCE
        # instead of prefixing every single answer with the same italic line.
        self._thinking_note_shown: dict[str, str] = {}

        # Reconnect state
        self._reconnect_attempt = 0
        self._max_backoff = 30  # seconds
        # A turn that needs the connection while the event loop waits out a
        # backoff asks it to try now (`_reconnect_now`) and waits for that
        # attempt's outcome (a future in `_reconnect_waiters`): the event loop
        # is the only reader of the socket, so the turn must not connect one of
        # its own (ELI-176).
        self._reconnect_now = asyncio.Event()
        self._reconnect_waiters: list = []
        # Turns waiting through a Gateway that refuses connections (down or
        # restarting): while there are any, the event loop tries again at its
        # first backoff step, not its longest.
        self._turns_awaiting_gateway = 0
        # The Gateway sends a `tick` event every `policy.tickIntervalMs` of
        # hello-ok (30 s, server-maintenance-Wf2jQ0wx.mjs:156); its own client
        # drops a socket that sent no frame for twice that ("tick timeout",
        # client-CKDmO6tp.mjs:1447-1459). The event loop does the same.
        self._tick_interval_s = 30.0
        self._stopped = False
        # Set once a newer deploy of this function has taken over (see
        # `retire()`). A retired connection still serves runs it already
        # has consumers for, but never writes turns (`_turn_route_now`) and
        # never reconnects once those runs are gone.
        self._retired = False
        # This connection's identity as a turn writer. A message whose
        # recorded writer is gone (`_turn_writer_alive`: retired here, or its
        # worker process exited) can be taken over (DESIGN 2.3); retire()
        # removes it.
        self.writer_id = turn_writer_id()
        # Only a build with the turn writer writes turns (not the Status Action's).
        self.writes_turns = writes_turns and _TURNS is not None
        self._turn_pumps: dict = {}     # (session_key, run_id) -> _RunPump
        self._turn_writers: dict = {}   # (chat_id, message_id) -> _TurnWriter
        self._turn_skip_runs: dict = {}  # (session_key, run_id) of heartbeat runs
        # (session_key, run_id) -> events of an agent run not yet known to be
        # no heartbeat, and the runs known (`_turn_kind_known`)
        self._turn_unkinded: dict = {}
        self._turn_kinded: dict = {}
        # (child session, child run) -> a sub-agent's result
        self._child_results: dict = {}
        # session_key -> run id of an inline reply with no Open WebUI message
        # waiting for its interrupted run's owner
        self._awaiting_owner: dict = {}
        self._session_ids: dict = {}     # session_key -> sessionId (a cron wake's run id)
        self._wake_turns_bound: dict = {}  # session_key -> wake turn keys given a message
        # session_key -> [{job, start, end}] of the cron job runs into it this
        # socket heard start (`cron` events), newest last (`note_cron_event`)
        self._cron_runs: dict = {}
        self._turn_resolve_lock = asyncio.Lock()
        self._frame_seq: int | None = None
        self._stop_notice_seen = False  # `shutdown` without restartExpectedMs on this socket
        self._shutdown_seen = False     # any `shutdown` on this socket
        # Bumped on every successful connect/reconnect. A consumer that
        # captures this before `chat.send` can later tell "the queue is quiet
        # because the agent is thinking" from "the queue is quiet because the
        # Gateway went away and came back, taking my run with it" -- the
        # Gateway only persists a turn once it COMPLETES, so a restart mid-run
        # destroys it silently and no terminal event is ever emitted.
        self.connection_epoch = 0
        # A reconnect is not a restart. `hello-ok.server.bootId` names the
        # Gateway process: same id after a reconnect = the same Gateway, its
        # runs are still going; a new id = it restarted and took them with it.
        # A reconnect counted as a restart would send a bogus resume turn into
        # live sessions and close their replies. `gateway_restarts` only counts
        # real restarts; consumers compare it, not `connection_epoch`.
        self.gateway_boot_id: str | None = None
        self.gateway_restarts = 0
        self.gateway_version: str | None = None   # hello-ok.server.version
        # hello-ok.features: what this Gateway offers, checked instead of its
        # version number (a feature can land in several release lines).
        self.gateway_methods: frozenset = frozenset()
        self.gateway_events: frozenset = frozenset()

        # Next request id
        self._next_req_id = 1

        # Delivery bookkeeping. When running inside OWUI these dicts are the
        # *same objects* for every `_GatewayConnection` in the process (see
        # `_shared_gateway_state`), so a turn shown live by one connection is
        # seen as delivered by all of them. Outside OWUI
        # (unit tests) each connection gets its own isolated dicts.
        _shared = _shared_gateway_state()

        # Runs the startup stub reconcile already finished, keyed by
        # "claim:<chat>:<stub>", so two connections never finalize one stub twice.
        self._claimed_runs: dict[str, bool] = (
            _shared["claimed_runs"] if _shared is not None else {}
        )

        # `_delivered_live`: by "session_key:run_id", every *final* event
        # dispatched to a live consumer queue (shown to an open tab, which
        # persists it). A duplicate or retried final for that run id after
        # the tab's request closed is caught by identity, never by comparing
        # text (two turns can both end with "OK.").
        # `_held_for_live`: events of a run continuing a message (an ask-user answer) that
        # arrived before its reply registered for it, while that reply still
        # streams the message: never a turn writer's.
        self._held_for_live: dict[tuple[str, str], list] = {}
        self.unreachable_held_drains = 0
        self._delivered_live: dict[str, float] = (
            _shared["delivered_live"] if _shared is not None else {}
        )

        # Per-chat write locks for the read-modify-write paths that are not
        # turn writers (stub reconcile). Shared across connections.
        # Keyed by chat_id.
        self._chat_write_locks: dict[str, asyncio.Lock] = (
            _shared["chat_write_locks"] if _shared is not None else {}
        )

        # Shadow bookkeeping. For a run that a live pipe() call is rendering
        # into a known OWUI message, `_run_targets[key]` holds that message's
        # (chat_id, message_id) and `_run_renderers[key]` a `_TurnRenderer`
        # accumulating the full content from this run's event stream -- so if
        # the inline turn ends before the run does (cancel, close, a torn-down
        # request), a turn writer continues the SAME message from it
        # (`_turn_route_now`, DESIGN 2.6). Instance-local
        # (not shared): only the singleton connection runs pipe() and dispatches
        # its own events; a zombie connection never registers a target.
        self._run_targets: dict[str, dict] = {}
        self._run_renderers: dict[str, "_TurnRenderer"] = {}
        # What each reply's message went out as, by "session_key:message_id"
        # (`note_reply_sent`, ELI-82).
        self._sent_replies: dict[str, dict] = {}
        # What the inline reply showed in place of raw run text, by
        # "chat_id:message_id": [(raw, shown)] for each resolved `MEDIA:`
        # directive and each ask-user prompt (its card, or its fallback text).
        # A turn writer that takes the message over repeats them. Shared, so
        # a successor deploy's writer has them too.
        self._turn_rewrites: dict[str, list] = (
            _shared["turn_rewrites"] if _shared is not None else {}
        )

        # Sessions whose transcript events (`session.tool`) this connection
        # asked for with `sessions.messages.subscribe`. A subscription ends
        # with the socket, so `_subscribe_all` renews every one after each
        # connect. Tool events for one call can arrive twice (as the run's
        # initiator AND as a subscriber); `_tool_events_seen` keeps the first.
        self._message_subscriptions: set[str] = set()
        # OWUI session key -> run ids active when this socket last subscribed
        # (ELI-100 DESIGN 2.1): runs that started before the subscription,
        # restart recovery above all, whose start push this socket never got.
        # An empty list means "active, ids not given": the Gateway omits
        # activeRunIds for claude-cli runs (session-active-runs-BURU1M8_.mjs:90).
        self.active_run_snapshot: dict[str, list[str]] = {}
        self._subscriptions_stale = False
        # One Event per session someone is waiting on, set by the next
        # `sessions.changed` that carries run state for it (ELI-88).
        self._session_change_waiters: dict[str, asyncio.Event] = {}
        # The same, set by the next `session.message` (a transcript append)
        # for the session (ELI-164).
        self._session_message_waiters: dict[str, asyncio.Event] = {}
        self._tool_events_seen: dict[tuple, bool] = {}
        # (session key, tool call id) -> the task of a spawn call that started
        # and has no result yet (`_spawn_call_task`), for the child index.
        self._spawn_tasks: dict[tuple, str] = {}

    async def _subscribe_all(self) -> None:
        """Renew this socket's subscriptions: the session index
        (`sessions.changed`, which carries run start/settle), and transcript
        events for every OWUI session subscribed so far."""
        try:
            # List params make it one request: the Gateway registers this
            # socket for pushes, THEN lists (sessions-subscriptions:21-36), so a
            # run is in this snapshot or its start push comes after it.
            resp = await self.send_request("sessions.subscribe", {"activeOnly": True}, timeout=15)
        except Exception as ex:
            pipe_log(f"  sessions.subscribe failed: {ex}")
        else:
            self._note_active_snapshot(((resp or {}).get("list") or {}).get("sessions") or [])
            self._stop_notice_seen = False
            self._shutdown_seen = False
            if _TURNS:
                spawn_background(_TURNS.after_hello(self))
        for key in list(self._message_subscriptions):
            await self._subscribe_messages(key)
        # A waiter that read run state before the subscription existed would
        # sleep through a settle it was never sent; make every waiter read
        # again now that settles are pushed.
        self._wake_session_waiters()

    def _note_active_snapshot(self, rows: list) -> None:
        """Keep the active runs of OWUI sessions from a subscribe snapshot."""
        snap = {}
        for row in rows:
            key = str(row.get("key") or "")
            runs = [r for r in (row.get("activeRunIds") or []) if r]
            if (runs or row.get("hasActiveRun")) and self.parse_owui_session_key(key):
                snap[key] = runs
        self.active_run_snapshot = snap
        if snap:
            pipe_log(f"  subscribe snapshot: {len(snap)} OWUI session(s) with an active run")

    async def _subscribe_messages(self, session_key: str) -> bool:
        try:
            # Refused like a run while a Gateway that just started prepares
            # the agent: given up, the renewed session would get no tool
            # events until the next reconnect.
            await _send_when_prepared(
                self, "sessions.messages.subscribe", {"key": session_key}, timeout=15
            )
            return True
        except Exception as ex:
            pipe_log(f"  sessions.messages.subscribe {session_key[-36:]} failed: {ex}")
            return False

    async def ensure_message_subscription(self, session_key: str) -> None:
        """Receive `session.tool` for `session_key` from now on. Tool events
        reach the connection that STARTED a run as `agent` events; everyone
        else, including this connection after a reconnect and for any run the
        Gateway starts itself (restart recovery, wakes, announces), gets them
        only as `session.tool` on a transcript subscription (ELI-92)."""
        if not session_key or session_key in self._message_subscriptions:
            return
        self._message_subscriptions.add(session_key)
        if not await self._subscribe_messages(session_key):
            self._message_subscriptions.discard(session_key)

    def _first_tool_event(self, payload: dict) -> bool:
        """False for a tool event this connection already dispatched: the
        same call's start/result can arrive both as the initiator's `agent`
        event and as a subscriber's `session.tool`."""
        data = payload.get("data") or {}
        tcid = data.get("toolCallId")
        phase = data.get("phase")
        if not tcid or phase not in ("start", "result"):
            return True
        key = (payload.get("sessionKey"), tcid, phase)
        if key in self._tool_events_seen:
            return False
        self._tool_events_seen[key] = True
        if len(self._tool_events_seen) > 4000:
            for stale in list(self._tool_events_seen)[:2000]:
                self._tool_events_seen.pop(stale, None)
        return True

    def _spawn_seen(self, payload: dict):
        """(parent, child, task or None) of an accepted spawn's result event,
        else None. The task is the one the call's start event carried: the
        receipt has none, and the child's transcript may not hold it yet."""
        data = payload.get("data") or {}
        call = (payload.get("sessionKey"), data.get("toolCallId"))
        task = _spawn_call_task(payload)
        if task:
            self._spawn_tasks[call] = task
            if len(self._spawn_tasks) > 200:
                for stale in list(self._spawn_tasks)[:100]:
                    self._spawn_tasks.pop(stale, None)
            return None
        if data.get("phase") != "result":
            return None
        task = self._spawn_tasks.pop(call, None)
        spawned = _spawned_child(payload)
        return (*spawned, task) if spawned else None

    def session_change_event(self, session_key: str) -> asyncio.Event:
        """An Event set by the next pushed change to `session_key`'s run state
        (`sessions.changed` with `hasActiveRun`: run started, run settled).

        Take it BEFORE reading the state, then wait on it only if the read
        said busy: a change landing between the read and the wait has already
        set it, so no change can slip through and no polling is needed. A
        socket drop sets every waiter too (the change may be among the lost
        events), so a waiter always re-reads after a gap."""
        ev = self._session_change_waiters.get(session_key)
        if ev is None:
            ev = self._session_change_waiters[session_key] = asyncio.Event()
        return ev

    def _wake_session_waiters(self, session_key: str | None = None) -> None:
        keys = [session_key] if session_key else list(self._session_change_waiters)
        for key in keys:
            ev = self._session_change_waiters.pop(key, None)
            if ev is not None:
                ev.set()
        if session_key is None:
            # A gap or a fresh subscription: an append may be among the lost.
            for key in list(self._session_message_waiters):
                self._session_message_waiters.pop(key).set()

    def session_message_event(self, session_key: str) -> asyncio.Event:
        """An Event set by the next `session.message` for `session_key` (the
        Gateway appended a transcript message), or by a socket gap. Take it
        BEFORE reading the transcript, as with `session_change_event`."""
        ev = self._session_message_waiters.get(session_key)
        if ev is None:
            ev = self._session_message_waiters[session_key] = asyncio.Event()
        return ev

    def _on_session_message(self, payload: dict) -> None:
        key = payload.get("sessionKey") or ""
        ev = self._session_message_waiters.pop(key, None)
        if ev is not None:
            ev.set()
        if _TURNS and key:
            _TURNS.session_message(self, key)

    def _on_shutdown(self, payload: dict) -> None:
        """DESIGN 2.7 F4: the Gateway announces its close before it aborts any
        run. No restartExpectedMs = stop mode, whose aborted runs it never
        recovers; with it, restart mode, whose aborted rows stay `running`."""
        self._shutdown_seen = True
        if payload.get("restartExpectedMs") is None:
            self._stop_notice_seen = True

    def _on_sessions_changed(self, payload: dict) -> None:
        """A session row changed. Waiters on its run state re-read it, and an
        OWUI session whose run just started gets a transcript subscription
        before its first tool call (measured: run start is pushed ~3s ahead of
        the first `session.tool`)."""
        key = payload.get("sessionKey") or payload.get("key") or ""
        self.note_session_id(key, payload.get("sessionId"))
        if key and "hasActiveRun" in payload:
            self._wake_session_waiters(key)
            self.row_to_consumers(key, payload)
        if _TURNS and key and payload.get("hasActiveRun") is False:
            _TURNS.settled(self, key, payload)
        if (payload.get("hasActiveRun") and key
                and key not in self._message_subscriptions
                and self.parse_owui_session_key(key)):
            spawn_background(self.ensure_message_subscription(key))

    def row_to_consumers(self, session_key: str, row: dict, resync: bool = False,
                         read_at: float | None = None, outside_loop: bool = False) -> None:
        """Hand session row `row` to every inline reply of `session_key`.
        `read_at`: when the row was read, if not just now (a resync's read
        started before its reply came back). `outside_loop`: put by a task,
        not the receive loop, which may be waiting to put an earlier event
        into a full queue; the row waits its turn behind it, in a task per queue so one stalled reply holds up no other."""
        marker = {"type": _ROW_MARKER_TYPE, "row": row, "resync": resync,
                  "read_at": time.monotonic() if read_at is None else read_at}
        for key, consumer in list(self._consumers.items()):
            if key.startswith(f"{session_key}:"):
                for q in consumer.queues:
                    if outside_loop:
                        spawn_background(q.put(dict(marker)))
                    else:
                        q.put_control(dict(marker))

    async def push_row(self, session_key: str) -> None:
        """Read the session's row now and hand it to its inline replies."""
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  row read for {session_key[-12:]} failed: {ex!r}")
            return
        row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
        if row is not None:
            self.row_to_consumers(session_key, row, outside_loop=True)

    def stop_awaiting_owner(self, session_key: str, run_id: str) -> None:
        """The reply decided: the agent runs held for it go on (`_release_held`)."""
        if self._awaiting_owner.get(session_key) == run_id:
            del self._awaiting_owner[session_key]
            self._release_held(session_key)

    def note_cron_event(self, payload: dict) -> None:
        """Record a cron job run into a session from the Gateway's `cron`
        event: `started` at `runAtMs`, `finished` after `durationMs`. A wake's
        events are known by this run (`cron_run_at`): on 2026.9 a short wake's
        one-shot job is deleted, and leaves `cron.list`, before its first
        event is judged (ELI-181)."""
        job = payload.get("job") if isinstance(payload.get("job"), dict) else {}
        target, job_id, start = job.get("sessionTarget"), payload.get("jobId"), payload.get("runAtMs")
        if not (job_id and isinstance(start, (int, float))):
            return
        run = next((r for runs in self._cron_runs.values() for r in runs
                    if r["job"] == job_id and r["start"] == start), None)
        if run is None:
            if payload.get("action") != "started" or not (
                    isinstance(target, str) and target.startswith("session:")):
                return
            runs = self._cron_runs.setdefault(target[len("session:"):], [])
            run = {"job": job_id, "start": start, "end": None}
            runs.append(run)
            del runs[:-20]
        if payload.get("action") == "finished" and isinstance(payload.get("durationMs"), (int, float)):
            run["end"] = start + payload["durationMs"]

    def cron_run_at(self, session_key: str, at_ms: float) -> dict | None:
        """The recorded cron job run into `session_key` that `at_ms` falls in,
        the newest such, else None."""
        for run in reversed(self._cron_runs.get(session_key) or []):
            if run["start"] <= at_ms and (run["end"] is None or at_ms <= run["end"]):
                return run
        return None

    def note_session_id(self, session_key: str, session_id) -> None:
        if session_key and isinstance(session_id, str) and session_id:
            self._session_ids[session_key] = session_id

    async def session_id_for(self, session_key: str) -> str | None:
        """The session's sessionId, which is also the run id of every cron wake
        into it. Session rows and lifecycle / session.tool events carry it;
        assistant and chat events do not, so a wake whose first event is one
        of those reads the row."""
        known = self._session_ids.get(session_key)
        if known:
            return known
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  sessionId read for {session_key[-12:]} failed: {ex!r}")
            return None
        for row in lst.get("sessions") or []:
            self.note_session_id(row.get("key") or "", row.get("sessionId"))
        return self._session_ids.get(session_key)

    def register_run_target(self, session_key: str, run_id: str,
                            chat_id: str | None, message_id: str | None,
                            thinking: str | None = None,
                            request_task_id: str | None = None) -> None:
        """Remember that this run streams into OWUI message `message_id` in
        `chat_id`, and start a shadow `_TurnRenderer` for it. No-op without both
        ids (e.g. a chat with no stable message id yet). `thinking`: the
        turn's level, which a writer's resume keeps. `request_task_id`: Open
        WebUI's task for the request, whose end a handover's write waits for."""
        if not (chat_id and message_id and run_id):
            return
        key = f"{session_key}:{run_id}"
        self._run_targets[key] = {"chat_id": chat_id, "message_id": message_id,
                                  "thinking": thinking, "request_task_id": request_task_id}
        self._run_renderers[key] = _TurnRenderer()
        # Bound memory: a run that never emits a terminal would otherwise leak
        # its target/renderer forever. Far above any real concurrency.
        if len(self._run_targets) > 100:
            for stale in list(self._run_targets)[:50]:
                self._run_targets.pop(stale, None)
                self._run_renderers.pop(stale, None)

    def handover_of(self, session_key: str, run_id: str, thinking: str | None = None) -> dict:
        """What a turn writer takes over from a run's request (DESIGN 2.6):
        its message, its shadow renderer, its thinking level, and `shown`,
        what earlier replies already showed of an adopted run."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets[key]
        return {"message_id": target["message_id"], "renderer": self._run_renderers.get(key),
                "thinking": thinking or target.get("thinking"), "shown": target.get("shown", ""),
                "request_task_id": target.get("request_task_id")}

    def unregister_run_target(self, session_key: str, run_id: str) -> None:
        key = f"{session_key}:{run_id}"
        self._run_targets.pop(key, None)
        self._run_renderers.pop(key, None)

    def note_reply_sent(self, session_key: str, message_id: str | None,
                        run_id: str, text: str) -> None:
        """Remember that OWUI reply `message_id` sent `text` as `run_id`, so
        a second call for the same reply follows that run instead of
        sending the message again (ELI-82)."""
        if not (message_id and run_id):
            return
        self._sent_replies[f"{session_key}:{message_id}"] = {"run_id": run_id, "text": text}
        if len(self._sent_replies) > 100:
            for stale in list(self._sent_replies)[:50]:
                self._sent_replies.pop(stale, None)

    def reply_sent(self, session_key: str, message_id: str | None) -> dict | None:
        """{run_id, text} that `note_reply_sent` recorded for this reply."""
        return self._sent_replies.get(f"{session_key}:{message_id}") if message_id else None

    def continue_run_target(self, session_key: str, run_id: str, next_run_id: str,
                            shown: bool = True) -> None:
        """The inline reply moved from `run_id` to `next_run_id` (an ask-user
        answer run): the target and its shadow renderer follow it, so a
        handover of the answer run continues the same reply (the writer finds
        the question run in the transcript as a pipe run of the same
        message). The question run was shown to its end: its late events open
        nothing. `shown=False` moves the target only: the answer is not sent
        yet, or its send failed and the target
        moves back."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets.pop(key, None)
        renderer = self._run_renderers.pop(key, None)
        if shown:
            self.mark_delivered_live(session_key, run_id)
        if target is None:
            return
        nkey = f"{session_key}:{next_run_id}"
        self._run_targets[nkey] = target
        self._run_renderers[nkey] = renderer if renderer is not None else _TurnRenderer()

    def note_turn_rewrite(self, chat_id: str | None, message_id: str | None,
                          raw: str, shown: str) -> None:
        """The inline reply showed `shown` where its run said `raw` (a resolved
        `MEDIA:` directive, an ask-user prompt's card). A writer that takes
        the message over shows the same."""
        if not (chat_id and message_id and raw) or raw == shown:
            return
        key = f"{chat_id}:{message_id}"
        rewrites = self._turn_rewrites.setdefault(key, [])
        if (raw, shown) not in rewrites:
            rewrites.append((raw, shown))
        if len(self._turn_rewrites) > 200:
            for stale in list(self._turn_rewrites)[:100]:
                self._turn_rewrites.pop(stale, None)

    def turn_rewrites(self, chat_id: str, message_id: str) -> list:
        return list(self._turn_rewrites.get(f"{chat_id}:{message_id}") or [])

    def _chat_write_lock(self, chat_id: str) -> asyncio.Lock:
        """Return the process-wide `asyncio.Lock` for serializing the
        read-modify-write paths into `chat_id` (stub reconcile),
        creating it on first use."""
        lock = self._chat_write_locks.get(chat_id)
        if lock is None:
            lock = asyncio.Lock()
            self._chat_write_locks[chat_id] = lock
        return lock

    # ── Public API ──────────────────────────────────────────────────

    @property
    def reconnecting(self) -> bool:
        """The socket dropped and the event loop is bringing it back: until
        then a request fails without reaching the Gateway (`send_request`).
        The reconnect renews the subscriptions and wakes every
        `session_change_event` waiter (`_subscribe_all`)."""
        return (self._ws is None and not self._stopped and self._event_loop_task is not None
                and not self._event_loop_task.done())

    async def ensure_connected(self):
        """Ensure the WS connection is up; connect/reconnect if needed."""
        if self._ws and self._event_loop_task and not self._event_loop_task.done():
            return
        if self._retired and not self._serving():
            # Reviving a retired connection is how orphans piled up: each one
            # kept writing every agent turn with its own (older) code.
            raise GatewayError(
                "gateway connection retired: a newer deploy of the pipe owns it now"
            )
        if self._event_loop_task and not self._event_loop_task.done() and not self._stopped:
            # The event loop is reconnecting. A socket connected here would not
            # be read until its backoff ends, and its next attempt would replace
            # it: the turn's first request then timed out (ELI-176). Have the
            # loop try now, and take that attempt's outcome.
            await self._await_reconnect()
            return
        async with self._init_lock:
            if self._ws and self._event_loop_task and not self._event_loop_task.done():
                return
            self._stopped = False
            await self._connect_once_started()
            if not self._event_loop_task or self._event_loop_task.done():
                self._event_loop_task = asyncio.create_task(self._event_loop())

    async def _await_reconnect(self):
        """Take the event loop's next reconnect outcome (ELI-176). A Gateway
        that refuses the connection is down or restarting, and this socket was
        up before, so it is not a wrong GATEWAY_URL: wait through the loop's
        later attempts, up to GATEWAY_DOWN_WAIT_S, rather than answer the
        message with the refusal. Any other failure is raised at once."""
        deadline = time.monotonic() + GATEWAY_DOWN_WAIT_S
        refusal = None
        self._turns_awaiting_gateway += 1
        try:
            self._reconnect_now.set()
            while True:
                waiter = asyncio.get_running_loop().create_future()
                self._reconnect_waiters.append(waiter)
                # The loop's first attempt is made at once; later ones at its first step.
                await asyncio.wait({waiter, self._event_loop_task},
                                   timeout=None if refusal is None else max(0, deadline - time.monotonic()),
                                   return_when=asyncio.FIRST_COMPLETED)
                if not waiter.done():
                    waiter.cancel()
                    if self._event_loop_task.done():
                        raise GatewayError("gateway connection stopped while reconnecting")
                    raise refusal
                error = waiter.result()
                if error is None:
                    return
                error = error if isinstance(error, GatewayError) else GatewayError(str(error))
                if not _gateway_refused(error) or time.monotonic() >= deadline:
                    raise error
                if refusal is None:
                    pipe_log("  the Gateway refuses connections (down or restarting); the message "
                             f"waits for the reconnect, up to {GATEWAY_DOWN_WAIT_S} s")
                refusal = error
        finally:
            self._turns_awaiting_gateway -= 1

    async def send_request(self, method: str, params: dict, timeout: float = 10) -> dict:
        """Send a request and wait for the response."""
        # `self._ws` is briefly None while the event loop is reconnecting
        # (see `_event_loop`/`_reconnect`). Without this guard the `.send`
        # below raises a bare `AttributeError: 'NoneType' object has no
        # attribute 'send'`, which surfaces to the user as a cryptic
        # "**Error sending message:** 'NoneType'...". A GatewayError with a
        # clear reason is caught by the same callers and reads sanely.
        if self._ws is None:
            raise GatewayError("gateway connection not ready (reconnecting)")
        req_id = str(self._next_req_id)
        self._next_req_id += 1
        fut = asyncio.get_running_loop().create_future()
        self._pending_reqs[req_id] = fut

        try:
            await self._ws.send(json.dumps(dict(
                type="req", id=req_id, method=method, params=params
            )))
            return await asyncio.wait_for(fut, timeout=timeout)
        finally:
            self._pending_reqs.pop(req_id, None)

    def session_send_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock serializing the queue-release -> chat.send -> run
        registration critical section (see `_session_send_locks`). Created
        lazily; asyncio.Lock is created on the running loop the first time it
        is awaited."""
        return self._session_send_locks.setdefault(session_key, asyncio.Lock())

    @contextlib.asynccontextmanager
    async def send_section(self, session_key: str):
        """`session_send_lock`, plus: this connection stays up until the
        section ends, even if a newer deploy retires it meanwhile. The wait
        for a running run to settle happens in here, and the settle is pushed
        to this socket only (ELI-172: a deploy mid-wait closed it with the
        run, and the queued message was never sent)."""
        self._open_send_sections += 1
        try:
            async with self.session_send_lock(session_key):
                yield
        finally:
            self._open_send_sections -= 1
            self._close_if_retired_and_idle()

    MODEL_PATCH_CACHE_TTL_S = 60.0

    def model_patch_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock so a burst of same-session messages issues one
        sessions.patch, not N concurrent ones (ELI-59). Lazily created, same
        pattern as session_send_lock."""
        return self._model_patch_locks.setdefault(session_key, asyncio.Lock())

    def model_patch_cached(self, session_key: str, model: str | None) -> bool:
        """True if `model` was successfully applied to this session within the
        cache TTL, so the idempotent sessions.patch can be skipped (ELI-59).
        The TTL bounds the wrong-model window if the session's model is changed
        externally (e.g. /model in the Control UI) between OWUI messages."""
        entry = self._model_patch_cache.get(session_key)
        if entry is None:
            return False
        cached_model, ts = entry
        return cached_model == model and (time.time() - ts) < self.MODEL_PATCH_CACHE_TTL_S

    def record_model_patched(self, session_key: str, model: str | None) -> None:
        """Record a successful sessions.patch for the cache (ELI-59)."""
        self._model_patch_cache[session_key] = (model, time.time())

    def should_announce_thinking_note(self, session_key: str, note: str) -> bool:
        """True the first time a given clamp note applies to a session.

        The level is picked in a filter dropdown and then stays picked, so a
        model that cannot honour it produces the identical note on every
        message. Told once it is useful; repeated above every answer it is
        noise the user has no way to dismiss, which is what it became in
        practice. Any CHANGE (different level, different model, a ladder
        learned from a rejection) is a new note and speaks up again.

        Per connection rather than persisted on purpose: after a redeploy or a
        reconnect the reminder is worth one repeat, and this must never be a
        file whose staleness could silence a genuinely new mismatch.
        """
        if not note:
            return False
        if self._thinking_note_shown.get(session_key) == note:
            return False
        self._thinking_note_shown[session_key] = note
        return True

    def invalidate_model_patch(self, session_key: str) -> None:
        """Drop the cached model for a session (ELI-59) -- called on patch
        failure so the next message retries the RPC from scratch."""
        self._model_patch_cache.pop(session_key, None)

    def register_consumer(self, session_key: str, run_id: str) -> asyncio.Queue:
        """Register an event consumer queue for a (session, run) pair.

        Returns a new queue attached to the consumer. Multiple queues per
        consumer are supported for broadcast (used by steering).
        """
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            consumer = _Consumer(session_key=session_key, run_id=run_id)
            self._consumers[key] = consumer
            pipe_log(f"  registered consumer: {key[:60]}...")
        q = _RunQueue(maxsize=500)
        consumer.queues.append(q)
        for ev in self._held_for_live.pop((session_key, run_id), []):
            q.put_nowait(_event_frame(ev))  # the run's first events, held for this reply
        return q

    def unregister_consumer(self, session_key: str, run_id: str, queue: asyncio.Queue | None = None):
        """Remove a consumer queue.

        If queue is given, only that queue is removed (broadcast mode).
        If queue is None, the entire consumer (all queues) is removed.
        """
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            return
        if queue:
            try:
                consumer.queues.remove(queue)
            except ValueError:
                pass
        if not consumer.queues or queue is None:
            del self._consumers[key]
            self._release_held(session_key)
        pipe_log(f"  unregistered consumer: {key[:60]}...")
        self._close_if_retired_and_idle()

    def _serving(self) -> bool:
        """Work a retired connection still owes: replies streaming here, and
        messages waiting here to send (ELI-172)."""
        return bool(self._consumers or self._open_send_sections)

    def _close_if_retired_and_idle(self) -> None:
        if self._retired and not self._serving():
            pipe_log("  retired gateway connection: last run finished, closing")
            spawn_background(self.disconnect())

    def live_reply_owns(self, session_key: str, run_id: str) -> bool:
        """True when `run_id` continues a message (an ask-user answer, a
        resume) that a live inline reply of another run still streams: its
        events wait for that reply (`register_consumer`) instead of opening a
        second writer on the message."""
        parsed = parse_pipe_run_id(run_id)
        waiting = self._awaiting_owner.get(session_key)
        if waiting and parsed is None and run_id != waiting:
            # A reply with no message waits for its run's owner: any
            # agent run here may be the Gateway's recovery of it. It waits
            # until the reply has read the transcript (rule E).
            return True
        if parsed is None or parsed["kind"] == "reply":
            return False
        for c in list(self._consumers.values()):
            other = parse_pipe_run_id(c.run_id) if c.session_key == session_key else None
            if (other and c.run_id != run_id and other["chat"] == parsed["chat"]
                    and other["message"] == parsed["message"]):
                return True
        return False

    def hold_for_live(self, session_key: str, run_id: str, payload: dict) -> None:
        held = self._held_for_live.setdefault((session_key, run_id), [])
        if len(held) < 500:
            held.append(payload)

    def _release_held(self, session_key: str) -> None:
        """A reply ended. The runs held for it stay held until they drain, in
        their order of arrival: into the run's own queue
        if a reply registers for it (`register_consumer`; the ask-user switch
        registers right after this release), before the run's next event
        (`_turn_route_now`), or here, in the background, for a run that sends
        no more."""
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return  # no loop, no events to route (a sync teardown)
        for (sess, run) in list(self._held_for_live):
            if sess == session_key:
                async def drain(sess=sess, run=run):
                    self.drain_held(sess, run)
                spawn_background(drain())

    def drain_held(self, session_key: str, run_id: str) -> None:
        """Route the held events of a run no live reply owns any more, in
        order and synchronously: the router never awaits, so nothing routed
        for the run can come between them."""
        if self.live_reply_owns(session_key, run_id):
            return
        held = self._held_for_live.pop((session_key, run_id), None)
        if not held:
            return
        consumer = self._consumers.get(f"{session_key}:{run_id}")
        if consumer is not None:
            # Unreachable: `register_consumer` takes a run's held events
            # before its queue exists. Counted and logged so a path that
            # breaks this shows; the events still reach the reply.
            self.unreachable_held_drains += 1
            pipe_log(f"  ERROR unreachable: {len(held)} held event(s) for an already-registered "
                     f"consumer of {run_id[:24]}... (count {self.unreachable_held_drains})")
            for q in consumer.queues:
                for ev in held:
                    q.put_control(_event_frame(ev))
            return
        pipe_log(f"  {len(held)} held event(s) of {run_id[:24]}... released to the turn writer")
        for ev in held:
            _TURNS.route_now(self, ev)  # only the turn writer holds events

    def mark_delivered_live(self, session_key: str, run_id: str):
        """Record that this run's final event was just dispatched to a live
        consumer queue -- i.e. genuinely shown to an open browser tab, which
        persists it itself via OWUI's own client-side flow. See
        `_delivered_live`'s docstring: a late event of such a run never
        reopens its message (`_turn_route_now`)."""
        key = f"{session_key}:{run_id}"
        self._delivered_live[key] = time.time()
        if len(self._delivered_live) > 500:
            oldest_first = sorted(self._delivered_live.items(), key=lambda kv: kv[1])
            for stale_key, _ in oldest_first[:250]:
                self._delivered_live.pop(stale_key, None)

    def was_delivered_live(self, session_key: str, run_id: str) -> bool:
        return f"{session_key}:{run_id}" in self._delivered_live

    def active_run_id_for_session(self, session_key: str) -> str | None:
        """Return the sole active run id for a session, if one is registered."""
        matches = [
            consumer.run_id for consumer in self._consumers.values()
            if consumer.session_key == session_key
        ]
        if len(matches) == 1:
            return matches[0]
        return None

    def parse_owui_session_key(self, session_key: str) -> tuple[str, str] | None:
        """Reverse `_owui_session_key`: extract (user_id, chat_id) from a
        session key this pipe built, e.g.
        "agent:main:openwebui-<user_id>-<chat_id>". Both ids are fixed-width
        36-char UUIDs, so a positional split resolves the ambiguity of a
        plain "-".split() (UUIDs themselves contain dashes). Returns None for
        session keys not owned by this pipe/agent (e.g. cross-channel bleed).
        """
        agent_id = getattr(self._valves(), "AGENT_ID", None)
        if not agent_id:
            return None
        prefix = f"agent:{agent_id}:openwebui-"
        if not session_key.startswith(prefix):
            return None
        after = session_key[len(prefix):]
        if len(after) < 73 or after[36] != "-":
            return None
        return after[0:36], after[37:73]

    async def dispatch_run_event(self, msg: dict) -> None:
        """One `agent` or `chat` event of a run: its shadow render, then its
        live reply, its turn writer, or nowhere. The receive loop's path for
        every run event, and the Pipe's for its own notes (ELI-197)."""
        payload = msg.get("payload", {})
        if payload.get("stream") == "tool" and not self._first_tool_event(payload):
            return
        spawned = self._spawn_seen(payload) if payload.get("stream") == "tool" else None
        if spawned:
            # The Status dialog's child index (state.py), off the loop.
            parent, child, task = spawned
            asyncio.get_running_loop().run_in_executor(None, functools.partial(
                _subagent_remember, parent, keys=[child], tasks={child: task} if task else None))

        # ── Shadow render ──
        # Feed every event of a run we're tracking into its shadow
        # `_TurnRenderer`, whether or not a live consumer is still
        # attached: the inline turn can end at any point, and the turn
        # writer it hands over to starts from this content.
        _evt_sess = payload.get("sessionKey", "")
        _evt_run = payload.get("runId", "")
        if _evt_sess and _evt_run:
            _renderer = self._run_renderers.get(f"{_evt_sess}:{_evt_run}")
            if _renderer is not None:
                try:
                    _renderer.feed(payload)
                except Exception as ex:
                    pipe_log(f"  shadow renderer feed failed: {ex}")

        consumers = self.consumers_for_event(payload)

        # ── ELI-100: a run no live request consumes is a turn ──
        if not consumers and _TURNS and _TURNS.route_now(self, payload):
            return

        if consumers:
            if not payload.get("runId"):
                pipe_log("  dispatched session-only event to sole consumer")
            if payload.get("state") == "final" and payload.get("sessionKey") and payload.get("runId"):
                # Genuinely shown to a live tab, which persists it via
                # OWUI's own client-side flow -- remember this so a
                # later duplicate/retried final event for the same
                # run_id never reopens its message.
                self.mark_delivered_live(payload["sessionKey"], payload["runId"])
                # The inline turn is alive and took the final itself, so
                # the parity shadow isn't needed for this run -- drop it.
                self.unregister_run_target(payload["sessionKey"], payload["runId"])
            for q in consumers[0].queues:
                await q.put(msg)
            return

        if payload.get("sessionKey") and not payload.get("runId"):
            pipe_log("  dropped ambiguous or unmatched session-only event")

        # If nothing matches at all, drop it.
        # This efficiently filters cross-session bleed.

    def consumers_for_event(self, payload: dict) -> list[_Consumer]:
        """Return consumers that should receive a Gateway event payload."""
        evt_session = payload.get("sessionKey", "")
        evt_run_id = payload.get("runId", "")
        if evt_session and evt_run_id:
            consumer = self._consumers.get(f"{evt_session}:{evt_run_id}")
            return [consumer] if consumer else []
        if evt_session and not evt_run_id:
            matches = [
                consumer for consumer in self._consumers.values()
                if consumer.session_key == evt_session
            ]
            return matches if len(matches) == 1 else []
        return []

    async def session_history(self, session_key: str,
                              limit: int = RECOVERY_HISTORY_LIMIT,
                              max_chars: int = RECOVERY_HISTORY_MAX_CHARS,
                              timeout: float = 10) -> dict:
        """Fetch the session's recent messages unclipped, with each turn in
        the role the transcript holds (`_transcript_roles`)."""
        hist = await self.send_request(
            "chat.history",
            dict(sessionKey=session_key, limit=limit, maxChars=max_chars),
            timeout=timeout
        )
        if isinstance(hist, dict) and isinstance(hist.get("messages"), list):
            hist["messages"] = _transcript_roles(hist["messages"])
        return hist

    async def abort(self, session_key: str, run_id: str):
        """Send chat.abort for an active run."""
        try:
            await _run_request(self, RUN_ABORT, dict(sessionKey=session_key, runId=run_id),
                               wait=False)
            pipe_log(f"  sent chat.abort for run {run_id[:20]}...")
        except Exception as e:
            pipe_log(f"  abort send failed: {e}")

    async def _abort_cancelled_run(self, session_key: str, run_id: str,
                                   send_stop: bool) -> None:
        await self.abort(session_key, run_id)
        if send_stop:
            pipe_log("Generator cancelled -- sending /stop fallback")
            await self.send_stop(session_key)

    def park_cancelled_turn(self, session_key: str, run_id: str | None,
                            queue: asyncio.Queue | None, carried: list[str],
                            grace_s: float, send_stop: bool,
                            run_text: dict | None = None, settle=None,
                            reply: dict | None = None,
                            waiting: list | None = None) -> None:
        """Hand a cancelled reply's unfinished business to the next message.

        OWUI cancels a response the same way for Stop and for Send now /
        interrupt (which then sends a new message): both call
        stopTasksByChatId, and the message queue lives only in the browser.
        So the cancelled turn is parked first and decided after:

        * `run_id` keeps running, and `queue` stays registered so every event
          the run emits (including ones queued but not yet shown) is buffered
          rather than dropped;
        * `carried` holds user messages the cancelled reply had accepted but
          not yet sent to the Gateway, oldest first;
        * `run_text` holds the run's text dedup baselines up to the cut
          ({"received", "stream", "item"}). The run's closing events repeat
          its WHOLE text; a claimer that starts from empty baselines takes all
          of it for new and appends the entire reply again.

        * `reply` is the cancelled reply's own state, {message_id, renderer}:
          the message it showed the run in, and what it showed there.
        * `waiting` are the replies whose messages are in `carried`
          (`_TurnState.waiting`): the claimer ends each with a note once it
          sent them; a release ends them as not sent (ELI-188).

        `settle` (a coroutine function) asks the browser which button was
        pressed and calls `settle_parked_turn`: Stop releases it now, Send now
        holds it for the follow-up message, whose claim keeps the run in its
        own message (`_keep_in_own_message`). It runs as a background task
        started here, so interrupting the cancelled reply cannot interrupt it
        (ELI-95), and the entry is `resolved` when it returns, which the
        intent query's own bound ensures. Without one, nobody can say (no page
        hook, API use): it is resolved now, and `grace_s` decides.
        `claim_cancelled_turn` takes all of it over; if nothing claims it, the
        run is aborted, the queue released and the carried messages dropped
        (the user stopped them).

        Synchronous on purpose: it runs on the generator's cancel/close path,
        where an await can itself be interrupted, so nothing here may depend
        on one. The Gateway calls and the settle go to background tasks.

        Open WebUI shutting down cancels every open reply too, and that is no
        Stop: the run keeps going, nothing is aborted, and the next process's
        startup reconcile finishes the reply (ELI-90 if the run is still
        active, ELI-94 if it ended while Open WebUI was down).
        """
        if owui_shutting_down():
            if queue is not None:
                self.unregister_consumer(session_key, run_id, queue=queue)
            pipe_log(f"  Open WebUI is shutting down: run {str(run_id)[:20]}... keeps going "
                     f"({len(carried)} unsent message(s) dropped)")
            return
        previous = self._pending_cancel_aborts.pop(session_key, None)
        if previous is not None:
            if previous["task"] is not None:
                previous["task"].cancel()
            previous["resolved"].set()
            carried = list(previous["carried"]) + list(carried)
            waiting = list(previous["waiting"]) + [
                r for r in (waiting or []) if r not in previous["waiting"]]
            if previous["queue"] is not None and previous["queue"] is not queue:
                self.unregister_consumer(
                    session_key, previous["run_id"], queue=previous["queue"])
            if previous["run_id"] and previous["run_id"] != run_id:
                spawn_background(self._abort_cancelled_run(
                    session_key, previous["run_id"], previous["send_stop"]))
        if run_id:
            # The cancelled message keeps what it showed (the caller's forced
            # snapshot). The run's tail belongs to whoever claims it: never
            # back-filled into the stopped message, never written as a turn of
            # its own.
            self.unregister_run_target(session_key, run_id)
            self.mark_delivered_live(session_key, run_id)

        entry = {"run_id": run_id, "queue": queue, "carried": list(carried),
                 "send_stop": send_stop, "task": None,
                 "resolved": asyncio.Event(), "run_text": run_text, "reply": reply,
                 "waiting": list(waiting or [])}

        def _release() -> None:
            # Read from the entry: a run kept in its own message is no longer
            # the entry's to stop.
            if entry["queue"] is not None:
                self.unregister_consumer(session_key, entry["run_id"], queue=entry["queue"])
            if entry["carried"]:
                pipe_log(f"  stopped: dropping {len(entry['carried'])} unsent "
                         "message(s)")
                if _TURNS is not None:
                    _TURNS.end_unsent_replies(self, entry["waiting"], sent=False)
            if entry["run_id"]:
                spawn_background(
                    self._abort_cancelled_run(session_key, entry["run_id"], send_stop))

        entry["release"] = _release
        if grace_s <= 0:
            _release()
            return
        self._pending_cancel_aborts[session_key] = entry
        self._arm_parked_timer(session_key, entry, grace_s)
        if settle is None:
            entry["resolved"].set()
            return

        async def _settle() -> None:
            try:
                await settle()
            finally:
                entry["resolved"].set()
        spawn_background(_settle())

    def _arm_parked_timer(self, session_key: str, entry: dict,
                          wait_s: float) -> None:
        if entry["task"] is not None:
            entry["task"].cancel()

        async def _fire():
            await asyncio.sleep(wait_s)
            if self._pending_cancel_aborts.get(session_key) is not entry:
                return
            if entry.get("claiming"):
                # A follow-up message is already here, waiting for the page's
                # answer: only an explicit Stop may release the run now.
                return
            self._pending_cancel_aborts.pop(session_key, None)
            entry["resolved"].set()
            pipe_log(f"  no new message within {wait_s:g}s of the cancel: "
                     f"stopping run {str(entry['run_id'])[:20]}...")
            entry["release"]()

        entry["task"] = spawn_background(_fire())

    def settle_parked_turn(self, session_key: str, run_id: str | None,
                           intent: str | None, hold_s: float) -> None:
        """Apply what the browser said about the cancel of `run_id`.

        "stop": the user pressed Stop (or Escape), so stop now. "send_now":
        a follow-up message is on its way, so hold the run for it; `hold_s`
        only bounds a browser that dies before sending it. Anything else
        (no hook, no answer) keeps the fallback timer. No-op if the turn was
        already claimed or released.
        """
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None or entry["run_id"] != run_id:
            return
        if intent == "stop":
            self._pending_cancel_aborts.pop(session_key, None)
            if entry["task"] is not None:
                entry["task"].cancel()
            pipe_log(f"  cancel was a Stop: stopping run {str(run_id)[:20]}... now")
            entry["release"]()
        elif intent == "send_now":
            # The follow-up message keeps the run (`claim_cancelled_turn`), not
            # this answer: Open WebUI tells the tab the reply was cancelled,
            # with its running tool cards drawn done, only after the cancel
            # handling returns, which this answer can beat. A writer opened
            # now would be overwritten. The page sends the follow-up only
            # after Open WebUI finished the cancel.
            pipe_log(f"  cancel was a Send now: holding run {str(run_id)[:20]}... "
                     f"for the follow-up message (up to {hold_s:g}s)")
            self._arm_parked_timer(session_key, entry, hold_s)
        else:
            pipe_log("  cancel intent unknown (no page hook or no answer): "
                     "keeping the fallback window")
        entry["resolved"].set()

    def _keep_in_own_message(self, session_key: str, entry: dict) -> bool:
        """Keep a parked run in the message it was cancelled in (ELI-158):
        the turn writer takes that message over with what the reply showed
        and the run's events buffered since the cancel, and finishes it when
        the run really ends. A running tool card stays running there instead
        of being shown done while the run goes on in the next reply. The
        entry keeps only the messages the reply had not sent. False when
        there is no message to keep it in (an API request) or no run."""
        reply, run_id, queue = entry.get("reply"), entry["run_id"], entry["queue"]
        if not reply or not run_id or not _TURNS:
            return False
        taken = queue.take_all() if queue is not None else []
        events = [m.get("payload") or {} for m in taken if m.get("type") == "event"]
        # Parking marked the run delivered so a late event reopens nothing;
        # its message is open again now, so its events must reach the writer.
        delivered = self._delivered_live.pop(f"{session_key}:{run_id}", None)
        if not _TURNS.hand_over(self, session_key, run_id,
                                reply={**reply, "events": events, "no_resume": True}):
            for m in taken:
                queue.put_control(m)
            if delivered is not None:
                self._delivered_live[f"{session_key}:{run_id}"] = delivered
            return False
        if queue is not None:
            self.unregister_consumer(session_key, run_id, queue=queue)
        entry.update(run_id=None, queue=None, reply=None, run_text=None)
        return True

    async def claim_cancelled_turn(self, session_key: str) -> dict | None:
        """Take over the turn `park_cancelled_turn` parked, if any.

        Waits for the page's answer about the cancel (`resolved`), so a Stop
        whose answer is still on its way is honored: OWUI follows a Stop with
        the next queued message, which must start fresh rather than continue
        the run the user just stopped. The answer's own query is bounded
        (`_INTENT_QUERY_TIMEOUT_S`), and it always runs to its end in the
        background, so this needs no bound of its own (ELI-95).

        Returns {"run_id", "queue", "carried", "waiting"}; the caller now
        owns the run, its buffered queue, the carried messages and the
        replies waiting for them.
        """
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None:
            return None
        if not entry["resolved"].is_set():
            entry["claiming"] = True
            await entry["resolved"].wait()
        entry = self._pending_cancel_aborts.pop(session_key, None)
        if entry is None:
            return None
        if entry["task"] is not None:
            entry["task"].cancel()
        # The follow-up message (after Send now, or inside the fallback
        # window) keeps the run in its own message; the new reply takes only
        # the messages.
        self._keep_in_own_message(session_key, entry)
        return {"run_id": entry["run_id"], "queue": entry["queue"],
                "carried": list(entry["carried"]),
                "waiting": list(entry["waiting"]),
                "run_text": entry.get("run_text")}

    def seed_run_renderer(self, session_key: str, run_id: str,
                          queue: asyncio.Queue,
                          run_text: dict | None = None) -> None:
        """Bring a freshly registered shadow renderer level with an adopted
        run: give it the run's dedup baselines (so the closing whole-text
        events are not appended again) and feed it the events still waiting
        in `queue`, which were dispatched before this reply registered its
        own target. Without this a handover to a turn writer would miss the
        buffered text and duplicate the rest."""
        key = f"{session_key}:{run_id}"
        renderer = self._run_renderers.get(key)
        if renderer is None:
            return
        renderer.seed(run_text)
        # What the earlier replies showed of the run is theirs: a writer that
        # takes this one over rebuilds from after it (ELI-147).
        self._run_targets[key]["shown"] = (run_text or {}).get("stream", "")
        for msg in list(getattr(queue, "_queue", ())):
            try:
                renderer.feed(msg.get("payload", {}))
            except Exception as ex:
                pipe_log(f"  shadow renderer seed failed: {ex}")

    async def send_stop(self, session_key: str):
        """Send the stronger /stop command for runtimes where chat.abort is incomplete."""
        try:
            resp = await _run_request(
                self, RUN_SEND,
                dict(
                    sessionKey=session_key,
                    message="/stop",
                    deliver=False,
                    idempotencyKey=f"stop-{uuid.uuid4()}",
                ),
                timeout=10,
            )
            pipe_log(f"  sent /stop fallback: {resp}")
        except asyncio.TimeoutError:
            pipe_log("  /stop fallback timed out")
        except Exception as e:
            pipe_log(f"  /stop fallback failed: {e}")

    async def retire(self):
        """Step down in favor of a newer deploy's connection.

        Runs that already have a consumer here keep being served until they
        unregister (cutting them would lose the reply), and so does a message
        waiting here to send (`send_section`, ELI-172); everything else stops
        now. Once the last consumer leaves, the connection closes itself and
        `ensure_connected` refuses to bring it back.
        """
        self._retired = True
        _retire_turn_writer(self.writer_id)
        for writer in list(self._turn_writers.values()):
            writer.release()
        for pump in list(self._turn_pumps.values()):
            pump.queue.put_nowait(("retired", None))
        if self._serving():
            pipe_log(
                f"  retired gateway connection: serving {len(self._consumers)} "
                f"in-flight run(s) and {self._open_send_sections} queued message(s) before closing"
            )
            return
        await self.disconnect()

    async def disconnect(self):
        """Gracefully close the connection."""
        self._stopped = True
        if self._event_loop_task:
            self._event_loop_task.cancel()
            try:
                await self._event_loop_task
            except asyncio.CancelledError:
                pass
            self._event_loop_task = None
        if self._ws:
            try:
                await self._ws.close()
            except Exception:
                pass
            self._ws = None

    # ── Internal ────────────────────────────────────────────────────

    def _mark_event_gap(self) -> None:
        """Put a gap marker into every run queue, in stream order.

        The Gateway has no event replay (sequence numbers are per connection),
        so whatever it sent while this socket was down is gone. The marker
        sits exactly between the last event before the drop and the first one
        after. A reply that reads it hands its message to the turn writer,
        whose transcript rebuild has what was lost (ELI-147).
        """
        n = 0
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _GAP_MARKER_TYPE})
                n += 1
        if n:
            pipe_log(f"  marked an event gap in {n} run queue(s)")
        self._wake_session_waiters()

    def _mark_gateway_restart(self) -> None:
        """Tell every live reply that its run's Gateway process is gone."""
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _RESTART_MARKER_TYPE})

    def _note_gateway_boot(self, boot_id: str | None) -> None:
        """Count a Gateway restart only when its boot id changes. Every
        supported Gateway sends one; below the minimum a restart goes
        uncounted."""
        first = self.connection_epoch <= 1
        if self.gateway_boot_id is not None and boot_id != self.gateway_boot_id:
            self.gateway_restarts += 1
            pipe_log(f"  Gateway restarted (bootId {self.gateway_boot_id[:8]} -> {str(boot_id)[:8]})")
            self._mark_gateway_restart()
        elif not first:
            pipe_log(f"  reconnected to the same Gateway (bootId {str(boot_id)[:8]}); runs continue")
        self.gateway_boot_id = boot_id

    async def _connect_and_start(self):
        """Connect, handshake, and start the event loop task."""
        valves = self._valves()
        host, port = _parse_gateway_url(valves.GATEWAY_URL)
        token = valves.GATEWAY_TOKEN

        if not token:
            raise GatewayError(
                "The GATEWAY_TOKEN valve is empty. Set it in Open WebUI under "
                "Admin Panel > Functions > OpenClaw Gateway > valves. The value "
                "is `gateway.auth.token` in your OpenClaw config."
            )

        # Device identity
        self._ensure_identity(valves)

        # Connect
        pipe_log(f"Connecting to ws://{host}:{port}")
        # Bounded, and every failure converted to GatewayError. The conversion
        # is the load-bearing part: pipe() only has an `except GatewayError`
        # around this, so anything else escapes the generator and OWUI renders
        # it as an unattributed error naming no valve.
        #
        # websockets already defaults to open_timeout=10 and that covers the TCP
        # connect, so this wait_for is a belt-and-braces bound rather than the
        # only one -- keep _GATEWAY_CONNECT_TIMEOUT_S and that default in step
        # if you tune either.
        try:
            ws = await asyncio.wait_for(
                websockets.connect(f"ws://{host}:{port}", ping_interval=None,
                                   max_size=GATEWAY_WS_MAX_SIZE),
                timeout=_GATEWAY_CONNECT_TIMEOUT_S,
            )
        except asyncio.TimeoutError:
            raise GatewayError(
                f"No response from the OpenClaw Gateway at {host}:{port} within "
                f"{_GATEWAY_CONNECT_TIMEOUT_S:.0f}s. Check the GATEWAY_URL valve, "
                "and that the Open WebUI backend can reach that host (Open WebUI "
                "resolves it, not your browser)."
            )
        except (OSError, ValueError, websockets.exceptions.WebSocketException) as ex:
            # WebSocketException is NOT an OSError subclass, so catching OSError
            # alone still let InvalidStatus/InvalidHandshake escape -- which is
            # exactly what happens when something answers but isn't a Gateway
            # (a reverse proxy returning 502 on the upgrade, an HTTP server on
            # the port). That is a configuration mistake, and it belongs in the
            # chat naming the valve, not as an unattributed traceback. A refused
            # connect is marked: a reconnecting turn waits through it.
            raise GatewayError(
                f"Could not connect to the OpenClaw Gateway at {host}:{port} "
                f"({type(ex).__name__}: {ex}). Is the Gateway running, and is "
                "the GATEWAY_URL valve pointing at it?",
                error={"code": GATEWAY_REFUSED_CODE} if _refused_connect(ex) else None,
            )

        # Handshake: receive challenge
        challenge = json.loads(await asyncio.wait_for(ws.recv(), 10))
        if challenge.get("event") != "connect.challenge":
            raise GatewayError("Bad handshake -- expected connect.challenge")

        c = challenge["payload"]
        signed = _sign_challenge(self._ident, c["nonce"], c["ts"], token_str=token,
                                 scopes=self.scopes)

        auth = dict(token=token)
        if self._device_token:
            auth["deviceToken"] = self._device_token

        await ws.send(json.dumps(dict(
            type="req", id="1", method="connect", params=dict(
                minProtocol=4, maxProtocol=4,
                client=dict(id="webchat", version="1",
                            platform="linux", mode="cli"),
                role="operator",
                scopes=self.scopes,
                auth=auth,
                device=signed,
                locale="en-US",
                userAgent="openclaw-owui-pipe/1.0",
                caps=["tool-events"]
            )
        )))

        resp = await _connect_response(ws, "1")
        if not resp.get("ok"):
            err = resp.get("error")
            pipe_log(f"  connect rejected: {json.dumps(err)[:500]}")
            raise GatewayError(
                _explain_connect_rejection(
                    str((err or {}).get("message", "connect failed")),
                    device_id=(self._ident or {}).get("id"),
                ),
                error=err if isinstance(err, dict) else None,
            )

        # Capture device token for future reconnects
        hello_ok = resp.get("payload", {})
        if hello_ok.get("auth", {}).get("deviceToken"):
            self._device_token = hello_ok["auth"]["deviceToken"]
            self._save_device_token(valves)
            pipe_log(f"Device token captured: {self._device_token[:20]}...")

        self._ws = ws
        self._frame_seq = None  # frame seq counts per socket
        tick_ms = (hello_ok.get("policy") or {}).get("tickIntervalMs")
        if isinstance(tick_ms, (int, float)) and tick_ms > 0:
            self._tick_interval_s = tick_ms / 1000
        self._reconnect_attempt = 0
        self.connection_epoch += 1
        self._thinking_note_shown.clear()
        self.gateway_version = (hello_ok.get("server") or {}).get("version")
        features = hello_ok.get("features") or {}
        self.gateway_methods = frozenset(features.get("methods") or ())
        self.gateway_events = frozenset(features.get("events") or ())
        self._note_gateway_boot((hello_ok.get("server") or {}).get("bootId"))
        pipe_log(
            f"Connected to Gateway (persistent) [epoch {self.connection_epoch}]"
        )
        # Subscriptions belong to the socket. Their requests resolve on the
        # event loop, which is not reading yet here, so it renews them. A
        # requests-only connection has none: the main connection renders.
        self._subscriptions_stale = not self.requests_only
        # NOTE: does not start/spawn the event-loop task -- that happens
        # exactly once, in `ensure_connected`. This method is also called
        # from inside `_reconnect`, which runs from within the event-loop
        # task itself; spawning another task here would duplicate it.

    def _identity_path(self, valves):
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"{self._identity_name}.json")

    def _device_token_path(self, valves):
        suffix = self._identity_name[len("identity"):]
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"device-token{suffix}.json")

    def _load_device_token(self, valves):
        if self._device_token:
            return
        data = _read_json_file(self._device_token_path(valves))
        if isinstance(data, dict) and data.get("deviceToken"):
            self._device_token = data["deviceToken"]
            pipe_log("Using persisted device token")

    def _save_device_token(self, valves):
        if not self._device_token:
            return
        _write_json_file(
            self._device_token_path(valves),
            {"deviceToken": self._device_token, "deviceId": self._ident.get("id")},
        )

    def _ensure_identity(self, valves):
        """Load or generate device identity from stable storage.

        Order matters for restart safety:
        1. state-dir identity file
        2. DEVICE_IDENTITY valve
        3. generate once and persist
        """
        if self._ident:
            return
        identity_path = self._identity_path(valves)
        ident = _read_json_file(identity_path)
        if ident and ident.get("id") and ident.get("privateKey"):
            self._ident = ident
            pipe_log(f"Using device identity from {identity_path}")
            self._load_device_token(valves)
            return

        # The DEVICE_IDENTITY valve names the main identity only; a restricted
        # connection always has its own.
        if self._identity_name == "identity" and getattr(valves, "DEVICE_IDENTITY", ""):
            ident = _parse_device_identity(valves.DEVICE_IDENTITY)
            if ident and ident.get("id") and ident.get("privateKey"):
                self._ident = ident
                _write_json_file(identity_path, ident)
                pipe_log("Using device identity from valve and persisted it to state dir")
                self._load_device_token(valves)
                return
            pipe_log("Failed to parse DEVICE_IDENTITY valve; generating new identity")

        self._ident = _generate_device_identity()
        _write_json_file(identity_path, self._ident)
        pipe_log(f"Generated new device identity and saved it to {identity_path}")
        if self._identity_name != "identity":
            return
        print(
            f"DEVICE_IDENTITY={json.dumps(self._ident, separators=(',',':'))}",
            flush=True
        )

    async def _event_loop(self):
        """Background task: reads WS messages and dispatches them.

        This is the ONLY task that ever calls `self._ws.recv()`. Reconnects
        happen in place (`self._ws = None`, then `_reconnect()` blocks until
        a new socket is ready) rather than by spawning a second event-loop
        task: two tasks would race on `self._ws.recv()`, each collision would
        raise, and each of *those* would spawn yet another task, a runaway
        reconnect storm.
        """
        while not self._stopped:
            try:
                if self._ws is None:
                    await self._reconnect()
                    continue
                if self._subscriptions_stale:
                    self._subscriptions_stale = False
                    spawn_background(self._subscribe_all())
                msg = json.loads(await asyncio.wait_for(self._ws.recv(),
                                                        timeout=2 * self._tick_interval_s))

                # ── Dropped frames ──
                # Event frames carry a per-socket `seq`; the Gateway advances it
                # without sending when this client is slow and the event is
                # dropIfSlow (server-start-BB-IxTAg.mjs:3205-3207), and says so
                # nowhere else. A dropped frame may be a run's text (repaired
                # like a reconnect gap) or a settle push (open writers re-read
                # their session rows).
                _seq = msg.get("seq")
                if msg.get("type") == "event" and isinstance(_seq, int):
                    if self._frame_seq is not None and _seq != self._frame_seq + 1:
                        pipe_log(f"  frame seq gap: expected {self._frame_seq + 1}, got {_seq}")
                        self._mark_event_gap()
                        if _TURNS:
                            spawn_background(_TURNS.resync(self))
                    self._frame_seq = _seq

                # ── Request-response matching ──
                if msg.get("type") == "res":
                    req_id = msg.get("id")
                    fut = self._pending_reqs.get(req_id)
                    if fut and not fut.done():
                        if msg.get("ok") is False:
                            err = msg.get("error", {})
                            fut.set_exception(
                                GatewayError(
                                    err.get("message")
                                    or err.get("code")
                                    or "request failed",
                                    error=err if isinstance(err, dict) else None,
                                )
                            )
                        else:
                            fut.set_result(msg.get("payload", {}))
                    continue

                # ── Tick keepalive (silently consume) ──
                if msg.get("event") == "tick" or msg.get("payload", {}).get("isHeartbeat"):
                    if _TURNS:
                        _TURNS.note_heartbeat(self, msg.get("payload") or {})
                    continue

                # ── Event dispatch ──
                # On tool events:
                #
                #   * The connection that STARTS a run gets its tool activity
                #     as `agent` events with payload.stream == "tool".
                #   * Any connection subscribed to the session with
                #     `sessions.messages.subscribe` gets the same payloads as
                #     `session.tool` events, whoever started the run (and no
                #     `agent` tool events). That covers this connection after a reconnect,
                #     and runs the Gateway starts itself (ELI-92).
                #
                # Both are folded into one path below, first copy wins.
                if msg.get("type") == "event" and msg.get("event") == "sessions.changed":
                    self._on_sessions_changed(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "shutdown":
                    self._on_shutdown(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") in ("question.requested",
                                                                     "question.resolved"):
                    if _QUESTION_HOOKS and self.writes_turns:
                        seen, resolved = _QUESTION_HOOKS
                        if msg["event"] == "question.requested":
                            seen(self, msg.get("payload") or {})
                        else:
                            resolved(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "session.message":
                    self._on_session_message(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "session.tool":
                    # Same payload as an `agent` tool event (stream "tool",
                    # data.phase/name/toolCallId/args/result), so it takes the
                    # same path: inline turn, shadow renderer, turn writer.
                    p = msg.get("payload") or {}
                    msg = {"type": "event", "event": "agent", "payload": {
                        k: p[k] for k in ("runId", "sessionKey", "sessionId", "stream",
                                          "data", "seq", "ts") if k in p}}
                if msg.get("type") == "event" and msg.get("event") == "cron":
                    self.note_cron_event(msg.get("payload") or {})
                    continue
                if msg.get("type") != "event" or \
                   msg.get("event") not in ("agent", "chat"):
                    continue

                await self.dispatch_run_event(msg)

            except asyncio.TimeoutError:
                # Not even a tick for two intervals: the socket is dead without
                # having closed (half-open), so every run on it would wait
                # forever. Tear it down and reconnect.
                pipe_log(f"  tick timeout: no frame for {2 * self._tick_interval_s:.0f}s, "
                         "reconnecting")
                transport = getattr(self._ws, "transport", None)
                if transport is not None:
                    transport.abort()
                self._ws = None
                self._mark_event_gap()
            except websockets.exceptions.ConnectionClosed as e:
                pipe_log(
                    "WS disconnected -- reconnecting... "
                    f"(code {getattr(e, 'code', None)}, reason {getattr(e, 'reason', '')!r})"
                )
                self._ws = None
                self._mark_event_gap()
            except asyncio.CancelledError:
                break
            except Exception as e:
                pipe_log(f"Event loop error: {e!r}")
                self._ws = None
                try:
                    self._mark_event_gap()
                except Exception as ex:  # the loop outlives any one failure
                    pipe_log(f"  event gap marking failed: {ex!r}")

    async def _connect_once_started(self):
        """`_connect_and_start`, connecting again while a Gateway that has
        just started refuses connections until its startup sidecars run
        ("gateway starting; retry shortly", details.reason "startup-sidecars"),
        after the wait it names, as OpenClaw's own clients do
        (startup-unavailable-D0-EeFjq.mjs, 2026.10.5). Any other failure, or
        one past STARTUP_REFUSAL_WAIT_S, is raised."""
        deadline = time.monotonic() + STARTUP_REFUSAL_WAIT_S
        told = False
        while True:
            try:
                return await self._connect_and_start()
            except GatewayError as ex:
                retry_ms = _gateway_starting_retry_ms(ex)
                if retry_ms is None or self._stopped or time.monotonic() + retry_ms / 1000 > deadline:
                    raise
                if not told:
                    told = True
                    pipe_log(f"  the Gateway is starting; connecting again as it asks (every {retry_ms} ms)")
                await asyncio.sleep(retry_ms / 1000)

    async def _reconnect(self):
        """Reconnect with exponential backoff.

        Blocks (looping in place, in the single `_event_loop` task) until a
        new connection is established or the connection is stopped. Must
        NEVER spawn a new `_event_loop` task -- see the docstring on
        `_event_loop` for why that caused a runaway task/connection storm.
        """
        while not self._stopped:
            self._reconnect_attempt += 1
            delay = 1 if self._turns_awaiting_gateway else min(2 ** (self._reconnect_attempt - 1),
                                                               self._max_backoff)
            pipe_log(f"  reconnect in {delay}s (attempt {self._reconnect_attempt})")
            try:
                # A turn waiting for the connection ends the wait (ensure_connected).
                await asyncio.wait_for(self._reconnect_now.wait(), delay)
                pipe_log("  reconnecting now: a message is waiting for the connection")
            except asyncio.TimeoutError:
                pass
            self._reconnect_now.clear()
            if self._stopped:
                self._answer_reconnect_waiters(GatewayError("gateway connection stopped"))
                return
            try:
                await self._connect_once_started()
                self._answer_reconnect_waiters(None)
                return
            except Exception as e:
                pipe_log(f"  reconnect failed: {e}")
                self._ws = None
                self._answer_reconnect_waiters(e)
                # loop and try again

    def _answer_reconnect_waiters(self, error) -> None:
        """Hand a reconnect attempt's outcome to the turns waiting on it."""
        waiters, self._reconnect_waiters = self._reconnect_waiters, []
        self._reconnect_now.clear()   # asked during this attempt: it is the answer
        for waiter in waiters:
            if not waiter.done():
                waiter.set_result(error)


# Protocol sentinels (docs/tools/subagents.md:470-431) that mean "no
# user-visible content was produced" -- never real assistant text to show a
# human. An announce-follow-up run can legitimately finish with exactly one
# of these as its only "assistant text", and writing it into a chat leaks
# internal plumbing.
_SILENT_SENTINELS = {"ANNOUNCE_SKIP", "NO_REPLY", "no_reply"}


# How far back a reply looks for its run's own closing message when the
# stream lost text: later runs may already have ended after it.
RUN_TEXT_HISTORY_LIMIT = 60
# Messages to read when rebuilding a whole run from `chat.history`: each tool
# call is a message of its own (measured: 119 calls = 154 messages).
RUN_HISTORY_LIMIT = 600


def _idempotency_keys(message) -> tuple[str, str]:
    """A transcript message's `idempotencyKey`, top level and under
    `__openclaw`, as strings ("" when absent)."""
    if not isinstance(message, dict):
        return "", ""
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    return str(message.get("idempotencyKey") or ""), str(meta.get("idempotencyKey") or "")


def _history_text_for_run(history: dict, run_id: str) -> tuple[bool, str | None]:
    """The closing assistant text one specific run saved, found by its id.

    The Gateway stamps a run's closing assistant message with
    `idempotencyKey = "cli-assistant:<runId>"` (claude-cli runner), so the
    run's own reply is found by identity, not by position. Returns
    (found, text); text is None when the run ended silent.
    """
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return False, None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for message in reversed(messages):
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        if not set(_idempotency_keys(message)) & wanted:
            continue
        text = ((_history_item(message) or {}).get("text") or "").strip()
        if not text:
            fallback = message.get("openclawStreamFallback")
            if isinstance(fallback, dict):
                text = str(fallback.get("replacementText") or "").strip()
        return True, (text if text and text not in _SILENT_SENTINELS else None)
    return False, None


def _usage_prompt_tokens(usage) -> int | None:
    """The context a model call filled, from its `usage`, as OpenClaw counts a
    session's `totalTokens` (`deriveContextPromptTokens`): the reported
    `contextUsage`, else input + cacheRead + cacheWrite, else total - output.
    None when the usage says nothing."""
    if not isinstance(usage, dict):
        return None
    context = usage.get("contextUsage") if isinstance(usage.get("contextUsage"), dict) else {}
    if context.get("state") == "unavailable":
        return None
    if context.get("state") == "available":
        prompt = context.get("promptTokens")
        return prompt if isinstance(prompt, (int, float)) and prompt > 0 else None
    nums = {k: usage.get(k) if isinstance(usage.get(k), (int, float)) else 0
            for k in ("input", "cacheRead", "cacheWrite", "output")}
    prompt = nums["input"] + nums["cacheRead"] + nums["cacheWrite"]
    if prompt > 0:
        return prompt
    total = usage.get("totalTokens", usage.get("total"))
    if isinstance(total, (int, float)) and total - nums["output"] > 0:
        return total - nums["output"]
    return None


def _history_usage_for_run(history: dict, run_id: str) -> dict | None:
    """The `usage` of one run's last model call, from its newest assistant
    message in `chat.history` that reports one. A run's messages carry its id
    under `__openclaw.runId`, or, for the claude-cli runner's closing message
    (whose usage is the run's last call), in `cli-assistant:<runId>`."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for message in reversed(messages):
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
        ids = {*_idempotency_keys(message), str(meta.get("runId") or ""), str(message.get("runId") or "")}
        if ids & wanted and _usage_prompt_tokens(message.get("usage")):
            return message["usage"]
    return None


def _history_renderer(messages: list) -> "_TurnRenderer":
    """A `_TurnRenderer` fed one run's `chat.history` messages instead of its
    live events, so a run whose events were lost still ends as the same
    `text` + `output` items (ELI-88/90/92)."""
    r = _TurnRenderer()
    for payload in _history_events(messages):
        r.feed(payload)
    r.flush()
    return r


def _history_events(messages: list):
    """`chat.history` messages as the live events that wrote them: the one
    transcript parser, for the chat's rebuild and the sub-agent drawer's run
    (ELI-147).

    claude-cli imports its transcript into the session as it goes: assistant
    messages whose blocks are `text`, `toolcall` {id, name, arguments} and
    `tool_result` {tool_use_id, name, content, is_error}, in order. The run's
    closing message (`cli-assistant:<runId>`) repeats all of its text, so it
    only counts when nothing in its own run carried text (a plain, tool-free
    reply, or imports that carry tool blocks only). It counts in place: an
    asked question's run closes before its answer run starts, so keeping
    only the last closer would lose the question.

    A run on the Gateway's own runtime (GPT, Gemini, DeepSeek) keeps
    OpenClaw's shape: `toolCall` blocks, and each result a `toolResult`
    message {toolCallId, toolName, content, isError} of its own (recorded,
    test_fixture_native_history.json).

    Text after a tool call is joined to the text before it with the separator
    the Gateway's live stream inserts there (`sawToolUseSinceText`), so the
    rebuild equals what streamed (it streams as "\n\n<text>"), and a
    preamble is not glued to the answer."""
    text = ""                 # what the events so far said
    run_text = False          # this run carried text before its closer
    tool_since_text = False   # the Gateway's `sawToolUseSinceText`
    for message in messages:
        if not isinstance(message, dict):
            continue
        role = message.get("role")
        if role == "toolResult" and message.get("toolCallId"):
            yield _history_tool_result(message["toolCallId"], message.get("toolName"),
                                       message.get("content"), message.get("isError"))
            continue
        if _is_closing_message(message):
            closing = ((_history_item(message) or {}).get("text") or "").strip()
            if not run_text and closing and closing not in _SILENT_SENTINELS:
                delta = _message_boundary_separator(text, closing) + closing
                text, tool_since_text = text + delta, False
                yield {"stream": "assistant", "data": {"delta": delta}}
            run_text = False
            continue
        content = message.get("content")
        if isinstance(content, str):
            content = [{"type": "text", "text": content}]
        for block in content if isinstance(content, list) else []:
            if not isinstance(block, dict):
                continue
            kind = block.get("type")
            if kind == "text" and block.get("text") and role == "assistant":
                lead = _message_boundary_separator(text, block["text"]) if tool_since_text else ""
                text, tool_since_text = text + lead + block["text"], False
                run_text = run_text or bool(block["text"].strip())
                yield {"stream": "assistant", "data": {"delta": lead + block["text"]}}
            elif kind in ("toolcall", "toolCall") and block.get("id") and role == "assistant":
                tool_since_text = True
                yield {"stream": "tool", "data": {
                    "phase": "start", "name": block.get("name", ""),
                    "toolCallId": block["id"], "args": block.get("arguments") or {}}}
            elif kind == "tool_result" and block.get("tool_use_id"):
                yield _history_tool_result(block["tool_use_id"], block.get("name"),
                                           block.get("content"), block.get("is_error"))


def _history_tool_result(tool_call_id: str, name, content, is_error) -> dict:
    return {"stream": "tool", "data": {
        "phase": "result", "name": name or "", "toolCallId": tool_call_id,
        "result": "" if content is None else content, "isError": is_error is True}}


def _message_boundary_separator(previous: str, nxt: str) -> str:
    """The newlines the Gateway inserts between two assistant messages of a
    claude-cli run (`missingMessageBoundarySeparator`,
    cli-live-session-registry-CS2DCATp.mjs:375 on 2026.9.3): enough for a
    blank line, counting the newlines both sides already have."""
    if not previous:
        return ""
    trailing = len(previous[-2:]) - len(previous[-2:].rstrip("\n"))
    leading = len(nxt[:2]) - len(nxt[:2].lstrip("\n"))
    return "\n" * max(0, 2 - trailing - leading)


def _is_closing_message(message) -> bool:
    """A run's closing assistant message (`cli-assistant:<runId>`)."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return False
    return any(k.startswith("cli-assistant:") for k in _idempotency_keys(message))


def _run_closed_by(message) -> str | None:
    """The run a `chat.history` message closes, or None. A claude-cli run
    closes with its `cli-assistant:<runId>` message. A run on the Gateway's
    own runtime has no such message: every message it writes carries
    `__openclaw.runId` (the `chat.send` run id), and
    its last is an assistant message that did not stop for a tool call."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return None
    key = next((k for k in _idempotency_keys(message) if k.startswith("cli-assistant:")), "")
    if key:
        return key[len("cli-assistant:"):]
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    if meta.get("runId") and message.get("stopReason") not in (None, "toolUse"):
        return str(meta["runId"])
    return None


def _deepest_leaf_id(messages: dict, start_id: str | None) -> str | None:
    """Walk down `childrenIds` from `start_id` to the deepest childless node.

    OWUI's `history.currentId` is only a *view* pointer: the frontend (or an
    interleaved live turn) can reset it back to an ancestor that already has
    children -- e.g. right after an agent turn was appended. Anchoring a
    new message directly on `currentId` in that state appends it as
    a *sibling* of the existing child, which OWUI renders as a 1/2·2/2 variant
    group instead of a linear message. Walking to the true leaf (following the most-recently-appended
    child at each branch) makes every turn writer chain off the real tail.
    Cycle-guarded and depth-capped for safety against malformed history.
    """
    node_id = start_id
    seen: set[str] = set()
    for _ in range(10_000):
        if not node_id or node_id in seen:
            break
        seen.add(node_id)
        node = messages.get(node_id) or {}
        children = node.get("childrenIds") or []
        if not children:
            break
        node_id = children[-1]
    return node_id


def _is_forwarded_turn(message) -> bool:
    """A forwarded user turn as `chat.history` shows it since OpenClaw
    2026.10.2: role "assistant", "Forwarded from ...", keyed as the admitted
    turn `<id>:user`, with the provenance the Gateway projects
    (chat-display-projection.helpers-pbUdgTgb.mjs `hasForwardedMessageProvenance`:
    a `sessions_send` message, or a cron run's prompt)."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return False
    key = next((k for k in _idempotency_keys(message) if k), "")
    prov = message.get("provenance") if isinstance(message.get("provenance"), dict) else {}
    forwarded = ((prov.get("kind"), prov.get("sourceTool")) == ("inter_session", "sessions_send")
                 or (prov.get("kind"), prov.get("sourceTool")) == ("internal_system", "cron"))
    return key.endswith(":user") and len(key) > 5 and forwarded


def _transcript_roles(messages: list) -> list:
    """`chat.history` messages with each forwarded user turn back in role
    "user", as the transcript holds it. Read as a reply, a cron wake's prompt
    and its scheduled-run preamble became the wake message's text when a
    claude-cli run was rebuilt from the transcript, and the run it started
    was not found (GH #24, OpenClaw 2026.10.2+). Other messages are kept."""
    return [{**m, "role": "user"} if _is_forwarded_turn(m) else m for m in messages]


def _history_user_run_id(message) -> str | None:
    """The run a transcript user message started: the Gateway keys the user
    message a `chat.send` adds as `<runId>:user` (the run id is the send's
    idempotencyKey). None for any other message, including the copy the
    runtime imports next to it."""
    if not isinstance(message, dict) or message.get("role") != "user":
        return None
    key = next((k for k in _idempotency_keys(message) if k), "")
    return key[:-len(":user")] if key.endswith(":user") and len(key) > 5 else None


# Read-only shim (ELI-100): bridge versions before ELI-100 embedded this in
# the message they wrote for a finished sub-agent task, invisible in rendered
# markdown (an HTML comment) but still present in the raw `content` OWUI
# hands the Action endpoint on click, so old messages keep opening -- the
# one piece of information a toolbar button click doesn't otherwise carry
# (OWUI sends chat_id/message_id/model/content, never a custom taskId).
# `_run_subagent_detail`-style consumers parse it back out with
# `_SUBAGENT_TASK_ID_MARKER_RE` to open straight into that task's drawer
# instead of the general status dialog.
_SUBAGENT_TASK_ID_MARKER_RE = re.compile(r"<!--\s*openclaw:taskId=([^\s>]+?)\s*-->")


# Module-level singleton
_gateway_connection: _GatewayConnection | None = None
_gateway_init_lock = asyncio.Lock()

# Anchor for finding a connection left behind by a *previous* deploy of this
# same function (OWUI's function loader (open_webui/utils/plugin.py)
# execs each redeploy into a brand-new module object with no teardown hook on
# the old one -- a module-level singleton alone resets every deploy and orphans
# the old module's WS/event-loop task forever). Stashing it as an attribute on
# `open_webui.socket.main` -- OWUI's own stable module, never reloaded by our
# function -- lets the next deploy find and `disconnect()` the previous one
# before opening a new connection, so redeploys self-heal without a container
# restart. Falls back to a no-op when not running inside OWUI (e.g. unit tests).
_STALE_CONN_ATTR = "_openclaw_gateway_connection_v1"


def _function_module_prefix(module_name: str) -> str:
    """`function_<id>_<hex>` -> `function_<id>`. OWUI 0.12 names every load of
    a Function this way (utils/plugin.py `load_function_module_by_id`), so the
    prefix tells "an older load of this same Function" apart from the Status
    Action, whose connection must be left alone."""
    head, sep, tail = module_name.rpartition("_")
    if sep and len(tail) == 32 and all(c in "0123456789abcdef" for c in tail):
        return head
    return module_name


def _orphaned_gateway_connections(current) -> list:
    """Live `_GatewayConnection`s created by OLDER loads of this Function.

    The single stashed attribute only ever named the previous deploy's
    connection; one that an in-flight run revived after being reaped dropped
    out of it and lived on. Scanning the heap is the only handle on those.
    """
    import gc
    prefix = _function_module_prefix(__name__)
    if not prefix.startswith("function_"):
        return []
    found = []
    for obj in gc.get_objects():
        cls = type(obj)
        if cls.__name__ != "_GatewayConnection" or obj is current:
            continue
        mod = getattr(cls, "__module__", "") or ""
        if mod == __name__ or _function_module_prefix(mod) != prefix:
            continue
        found.append(obj)
    return found


async def _retire_stale_connection(stale) -> None:
    retire = getattr(stale, "retire", None)
    if retire is not None:
        await asyncio.wait_for(retire(), timeout=5)
        return
    # Built before `retire()` existed: its own ensure_connected would revive
    # it, so pin both entry points shut on the instance before closing it.
    async def _refuse(*_a, **_k):
        raise GatewayError("gateway connection retired by a newer deploy")
    stale._stopped = True
    stale.ensure_connected = _refuse
    stale._connect_and_start = _refuse
    await asyncio.wait_for(stale.disconnect(), timeout=5)


# Earlier loads' connections this load retired. One may still stream a reply
# (`retire`); its run's events reach this load's connection too (ELI-150).
_retired_connections: list = []


def _served_by_retired(payload: dict) -> bool:
    _retired_connections[:] = [c for c in _retired_connections if getattr(c, "_consumers", None)]
    return any(c.consumers_for_event(payload) for c in _retired_connections)


async def _reap_stale_gateway_connection() -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    stale_conns = []
    stale = getattr(_owui_socket_main, _STALE_CONN_ATTR, None)
    if stale is not None and stale is not _gateway_connection:
        stale_conns.append(stale)
    try:
        for obj in _orphaned_gateway_connections(_gateway_connection):
            if not any(obj is s for s in stale_conns):
                stale_conns.append(obj)
    except Exception as ex:
        pipe_log(f"  orphan scan failed (non-fatal): {ex}")
    for conn in stale_conns:
        try:
            await _retire_stale_connection(conn)
            _retired_connections.append(conn)
            pipe_log(
                "  reaped stale gateway connection from a previous deploy "
                f"({type(conn).__module__})"
            )
        except Exception as ex:
            pipe_log(f"  failed to reap stale gateway connection (non-fatal): {ex}")


def _remember_gateway_connection(conn: _GatewayConnection) -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    setattr(_owui_socket_main, _STALE_CONN_ATTR, conn)


async def _get_gateway_connection(valves_getter) -> _GatewayConnection:
    """Get or create the singleton Gateway connection."""
    global _gateway_connection
    if _gateway_connection is not None:
        await _gateway_connection.ensure_connected()
        return _gateway_connection
    async with _gateway_init_lock:
        if _gateway_connection is not None:
            await _gateway_connection.ensure_connected()
            return _gateway_connection
        await _reap_stale_gateway_connection()
        conn = _GatewayConnection(valves_getter)
        await conn.ensure_connected()
        _gateway_connection = conn
        _remember_gateway_connection(conn)
        return conn


# ---------------------------------------------------------------------------
# Owner users (OWNER_USERS valve)
# ---------------------------------------------------------------------------
# The main connection holds operator.admin, so every turn it sends is the
# owner's and gets owner-only tools. For a chat whose user is not in
# OWNER_USERS, every request that starts, steers or ends a run goes over a
# second connection with RESTRICTED_SCOPES and its own device identity. Reading
# and rendering stay on the main connection: they do not make a turn the
# owner's, and the main connection remains the only one that writes into Open
# WebUI (ELI-100).

_restricted_connection: "_GatewayConnection | None" = None
_restricted_init_lock = asyncio.Lock()


async def _get_restricted_connection(valves_getter) -> "_GatewayConnection":
    """The connection for non-owner users' run requests: read + write scopes,
    identity `identity-restricted.json`, requests only."""
    global _restricted_connection
    async with _restricted_init_lock:
        if _restricted_connection is None:
            conn = _GatewayConnection(valves_getter, writes_turns=False, scopes=RESTRICTED_SCOPES,
                                      identity_name="identity-restricted", requests_only=True)
            await conn.ensure_connected()
            _restricted_connection = conn
            return conn
    await _restricted_connection.ensure_connected()
    return _restricted_connection


async def _owui_call(fn, *args):
    out = fn(*args)
    return await out if asyncio.iscoroutine(out) else out


async def _owner_users_setting(conn) -> "str | None":
    """OWNER_USERS as configured, or None when it cannot be read. The Pipe's
    connection carries the Pipe's valves; the Status Action's own connection
    does not, so the setting is read from the Pipe function's saved valves."""
    valves_getter = getattr(conn, "_valves", None)
    raw = getattr(valves_getter() if callable(valves_getter) else None, "OWNER_USERS", None)
    if isinstance(raw, str):
        return raw
    try:
        from open_webui.models.functions import Functions
    except ImportError:
        return ""  # not inside Open WebUI: there is no valve to set
    try:
        found = ""
        for fn in await _owui_call(Functions.get_functions_by_type, "pipe") or []:
            saved = await _owui_call(Functions.get_function_valves_by_id, fn.id) or {}
            if isinstance(saved, dict) and saved.get("OWNER_USERS"):
                found = ",".join(x for x in (found, saved["OWNER_USERS"]) if x)
        return found
    except Exception as ex:
        pipe_log(f"  owner users: could not read the Pipe's valves ({ex!r}); treating as not owner")
        return None


async def _user_email(user_id: str) -> "str | None":
    try:
        from open_webui.models.users import Users
        user = await _owui_call(Users.get_user_by_id, user_id)
        return getattr(user, "email", None) if user else None
    except Exception:
        return None


async def _sender_is_owner(conn, session_key: str) -> bool:
    """Whether a run request for `session_key` may go out as the owner's. An
    empty OWNER_USERS keeps the old behaviour (everyone is). Otherwise the
    chat's user (from the session key, with that user's email) must be on the
    list; anything that cannot be decided is not the owner's."""
    raw = await _owner_users_setting(conn)
    if raw is None:
        return False
    owners = _parse_owner_users(raw)
    if not owners:
        return True
    m = _OWUI_KEY_USER.match(session_key or "")
    if not m:
        return False
    user_id = m.group(1)
    if user_id.lower() in owners:
        return True
    return _is_owner_user(owners, user_id, await _user_email(user_id))


def _non_owner_send_params(params: dict) -> dict:
    """A chat.send the restricted connection may make: without the admin-only
    fields, and with the conversation metadata block at the head of the
    message text, which is how the Gateway hands a receipt to the agent
    (`receipt + "\\n\\n" + message`). The block keeps its "untrusted" label,
    and ownership never comes from it: the Gateway decides that from the
    sending connection. A command ("/stop") goes as typed, since the Gateway
    reads commands from the raw text."""
    dropped = [f for f in ADMIN_ONLY_SEND_FIELDS if f in params]
    if not dropped:
        return params
    out = {k: v for k, v in params.items() if k not in dropped}
    receipt = params.get("systemProvenanceReceipt")
    message = out.get("message") or ""
    moved = isinstance(receipt, str) and bool(receipt) and not message.lstrip().startswith("/")
    if moved:
        out["message"] = "\n\n".join(p for p in (receipt, message) if p)
    pipe_log(f"  non-owner chat.send: left out admin-only fields {dropped}"
             + ("; metadata block moved into the message" if moved else ""))
    return out


async def _run_request(conn, method: str, params: dict, *, timeout: float = 10,
                       owner: "bool | None" = None, wait: bool = True):
    """Send a request that starts, steers or ends a run (`RUN_SEND`,
    `RUN_ABORT`, `RUN_PATCH`) on the connection the chat's owner status calls
    for: `conn` for an owner, the restricted connection otherwise. `owner`
    overrides the decision from the session key (a title run, whose session
    is not the chat's). `wait=False` sends without waiting for the answer."""
    if owner is None:
        owner = await _sender_is_owner(conn, params.get("sessionKey") or params.get("key") or "")
    target = conn if owner else await _get_restricted_connection(conn._valves)
    if not owner and method == RUN_SEND:
        params = _non_owner_send_params(params)
    if not wait:
        await target._ws.send(json.dumps(dict(type="req", id="abort" if method == RUN_ABORT
                                              else f"run-{uuid.uuid4().hex[:8]}",
                                              method=method, params=params)))
        return None
    return await _send_when_prepared(target, method, params, timeout=timeout)


async def _send_when_prepared(conn, method: str, params: dict, *, timeout: float = 10):
    """`conn.send_request`, sent again while the Gateway refuses it only
    because it is still preparing the agent after its start, after the wait
    each refusal names, up to STARTUP_REFUSAL_WAIT_S. Any other refusal the
    Gateway calls retryable (UNAVAILABLE, `retryable`) is sent again too, up to
    RETRYABLE_REFUSAL_WAIT_S from the first: right after preparation, 2026.10.5
    refuses sessions.patch with "Session patch failed unexpectedly. Retry the
    request." while its session storage gets ready (a log line says so; the
    refusal itself names no reason and no wait)."""
    started = time.monotonic()
    deadline = started + STARTUP_REFUSAL_WAIT_S
    told = set()
    while True:
        try:
            return await conn.send_request(method, params, timeout=timeout)
        except GatewayError as ex:
            retry_ms, why = _startup_refusal_retry_ms(ex), "preparing"
            if retry_ms is None:
                retry_ms, why = _retryable_refusal_retry_ms(ex), "retryable"
                if retry_ms is not None and "retryable-since" not in told:
                    told.add("retryable-since")
                    retryable_deadline = time.monotonic() + RETRYABLE_REFUSAL_WAIT_S
            if retry_ms is None or time.monotonic() + retry_ms / 1000 > (
                    deadline if why == "preparing" else min(deadline, retryable_deadline)):
                raise
            if why not in told:
                told.add(why)
                pipe_log(f"  {method}: the Gateway is still preparing the agent after its start; "
                         f"sending again as it asks (every {retry_ms} ms, up to {STARTUP_REFUSAL_WAIT_S} s)"
                         if why == "preparing" else
                         f"  {method}: refused as retryable ({ex}); sending again in {retry_ms} ms, "
                         f"up to {RETRYABLE_REFUSAL_WAIT_S} s")
            await asyncio.sleep(retry_ms / 1000)


# A Gateway that has just started refuses runs until it has inspected and
# prepared the agent's database (2026.10.5 and later): `UNAVAILABLE`,
# `retryable`, `retryAfterMs`, details.code below. The refusal comes before
# the request's ack and is not kept in the idempotency cache ("client-retry",
# chat-send-handler-o4Nr7Ej0.mjs:340/428), so the same request, same key, is
# sent again after the time it names. No event marks the end of preparation.
STARTUP_REFUSAL_CODE = "agent-database-inspection-pending"
STARTUP_REFUSAL_WAIT_S = 300
RETRYABLE_REFUSAL_WAIT_S = 30
# How long a message waits for a Gateway that refuses connections after it was
# reached (a restart: the port is closed until the new process listens).
GATEWAY_DOWN_WAIT_S = 120
GATEWAY_REFUSED_CODE = "connection-refused"


async def _connect_response(ws, req_id: str, timeout: float = 10) -> dict:
    """The Gateway's response to our connect request: the first `res` frame
    with its id. Any other frame before it is skipped (and logged): taken as
    the response, it read as a rejection with no reason ("connect failed")."""
    deadline = time.monotonic() + timeout
    while True:
        frame = json.loads(await asyncio.wait_for(ws.recv(), max(0, deadline - time.monotonic())))
        if frame.get("type") == "res" and frame.get("id") == req_id:
            return frame
        pipe_log(f"  frame before the connect response, skipped: type={frame.get('type')!r} "
                 f"event={frame.get('event')!r} id={frame.get('id')!r}")


def _refused_connect(ex) -> bool:
    """Every address the host resolved to refused the TCP connect. asyncio
    raises one OSError for all of them ("Multiple exceptions: ...") when their
    messages differ, as for localhost's ::1 and 127.0.0.1."""
    if isinstance(ex, ConnectionRefusedError):
        return True
    text = str(ex)
    return (isinstance(ex, OSError) and text.startswith("Multiple exceptions:")
            and text.count("[Errno") == text.count(f"[Errno {errno.ECONNREFUSED}]"))


def _gateway_refused(ex) -> bool:
    """A connect the Gateway's host refused: nothing listens on the port."""
    return isinstance(ex, GatewayError) and ex.error.get("code") == GATEWAY_REFUSED_CODE


def _gateway_starting_retry_ms(ex: GatewayError) -> int | None:
    """The wait before connecting again to a Gateway that refused the connect
    only because it is still starting, bounded as its own clients bound it
    (resolveGatewayStartupRetryAfterMs: 100 to 2000 ms, 500 by default)."""
    err = getattr(ex, "error", None) or {}
    details = err.get("details") if isinstance(err.get("details"), dict) else {}
    if err.get("code") != "UNAVAILABLE" or err.get("retryable") is not True \
            or details.get("reason") != "startup-sidecars":
        return None
    retry = err.get("retryAfterMs")
    retry = int(retry) if isinstance(retry, (int, float)) else 500
    return min(max(retry, 100), 2000)


def _startup_refusal_retry_ms(ex: GatewayError) -> int | None:
    """The wait the Gateway asks for before sending a refused request again,
    when it refused it only because it is still preparing after its start."""
    err = getattr(ex, "error", None) or {}
    details = err.get("details") if isinstance(err.get("details"), dict) else {}
    if not err.get("retryable") or details.get("code") != STARTUP_REFUSAL_CODE:
        return None
    retry = err.get("retryAfterMs")
    return int(retry) if isinstance(retry, (int, float)) and retry > 0 else 250


def _retryable_refusal_retry_ms(ex: GatewayError) -> int | None:
    """The wait before sending again a request the Gateway refused as
    UNAVAILABLE and `retryable` for any other reason: the one it names, else
    the startup refusal's 250 ms."""
    err = getattr(ex, "error", None) or {}
    if err.get("code") != "UNAVAILABLE" or err.get("retryable") is not True:
        return None
    retry = err.get("retryAfterMs")
    return int(retry) if isinstance(retry, (int, float)) and retry > 0 else 250


# --- emit ------------------------------------------------------------------


async def _emit_status(__event_emitter__, description, *, done=False):
    """Send an OWUI status event when the current pipe call supports events."""
    if not __event_emitter__:
        return
    await __event_emitter__(
        {"type": "status", "data": {"description": description, "done": done}}
    )


# Claude Code's in-process sub-agent tool, and what its card's result says for
# one started in the background: its report comes later, and the run stays
# open until it is in (ELI-163).
_AGENT_TOOL_NAME = "Agent"
_AGENT_LAUNCHED_PREFIX = "Async agent launched"


def _is_agent_tool(name) -> bool:
    """Claude Code calls it `Agent`; in any case, as the Gateway lowercases
    the names of some tools. OpenClaw has no tool of its own by that name."""
    return (name or "").strip().lower() == _AGENT_TOOL_NAME.lower()


def _is_background_agent_launch(name, result_text, is_error=False) -> bool:
    return (not is_error and _is_agent_tool(name)
            and (result_text or "").strip().startswith(_AGENT_LAUNCHED_PREFIX))


def _background_agents_line(n: int) -> str:
    """The status row of a reply a background agent holds open."""
    return f"Waiting on {n} background agent{'' if n == 1 else 's'}"


# Live view of the agent's browser (LIVE_VIEW_URL): ids go into the URL as they
# are, so they must be plain ids.
_LIVE_VIEW_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")


def _live_view_url(valves, *, chat_id, message_id, user_id, email, tool_name, args_str):
    """The embed URL for a reply whose tool call looks like browser use, or None.
    None when the valve is off, the user is not in LIVE_VIEW_USERS, the tool does
    not match LIVE_VIEW_TOOLS, or the URL would not be an http(s) URL: Open WebUI
    renders any other embed string as HTML."""
    template = (getattr(valves, "LIVE_VIEW_URL", "") or "").strip()
    if not template or not re.match(r"^https?://", template, re.I):
        return None
    if not all(isinstance(v, str) and _LIVE_VIEW_ID.match(v) for v in (chat_id, message_id)):
        return None
    users = _parse_owner_users(getattr(valves, "LIVE_VIEW_USERS", "") or "")
    if users and not _is_owner_user(users, user_id, email):
        return None
    try:
        tools = re.compile(getattr(valves, "LIVE_VIEW_TOOLS", "") or r"(?!)", re.I)
    except re.error:
        return None
    if not tools.search(f"{tool_name or ''} {args_str or ''}"):
        return None
    return template.replace("{chat_id}", chat_id).replace("{message_id}", message_id)


def _fmt_tokens(n) -> str:
    """Compact token count: 115212 -> '115k', 1000000 -> '1.0m'."""
    try:
        n = int(n)
    except (TypeError, ValueError):
        return "?"
    if n >= 1_000_000:
        return f"{n / 1_000_000:.1f}m"
    if n >= 1_000:
        return f"{n // 1_000}k"
    return str(n)


def _format_goal_line(goal: dict) -> str:
    """Mirror the TUI footer's goal phrasing (see docs/tools/goal.md)."""
    status = goal.get("status")
    tokens_used = goal.get("tokensUsed")
    budget = goal.get("tokenBudget")
    used_fmt = _fmt_tokens(tokens_used) if tokens_used is not None else "?"
    if status == "active":
        if budget:
            return f"🎯 Pursuing goal ({used_fmt}/{_fmt_tokens(budget)})"
        objective = (goal.get("objective") or "").strip()
        if len(objective) > 40:
            objective = objective[:39] + "…"
        return f"🎯 Pursuing goal: {objective}" if objective else "🎯 Pursuing goal"
    if status == "paused":
        return "🎯 Goal paused (/goal resume)"
    if status == "blocked":
        return "🎯 Goal blocked (/goal resume)"
    if status == "usage_limited":
        return "🎯 Goal hit usage limits (/goal resume)"
    if status == "budget_limited":
        return f"🎯 Goal unmet ({used_fmt}/{_fmt_tokens(budget)})"
    if status == "complete":
        return f"🎯 Goal achieved ({used_fmt})"
    return ""


def _window_bit(w: dict) -> str | None:
    used = w.get("usedPercent")
    if used is None:
        return None
    return f"{w.get('label')} {round(100 - used)}% left"


def _relative_time(reset_at_ms) -> str | None:
    """Compact relative countdown: '22m', '4h07m', '3d07h'. None if unknown/past."""
    if not reset_at_ms:
        return None
    delta_s = int((reset_at_ms - time.time() * 1000) / 1000)
    if delta_s <= 0:
        return None
    days, rem = divmod(delta_s, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days:
        return f"{days}d{hours:02d}h"
    if hours:
        return f"{hours}h{minutes:02d}m"
    return f"{minutes}m"


def _window_reset_line(w: dict) -> str | None:
    """Full detail line for one rate-limit window, only when it has a known
    reset time -- e.g. '⏱ 5h 18% left (resets in 22m)'. Skipped for windows
    without a `resetAt` (e.g. Gemini's Pro/Flash aren't time-windows), since
    there'd be nothing new to say beyond what the thin combined line already
    shows.
    """
    bit = _window_bit(w)
    rel = _relative_time(w.get("resetAt"))
    if not bit or not rel:
        return None
    return f"⏱ {bit} (resets in {rel})"


async def _build_usage_status_lines(conn, session_key, timeout: float = 5,
                                    run_usage: dict | None = None) -> list[str]:
    """Best-effort final status lines: context window fill (combined with the
    provider's primary/nearest-term rate-limit window on the same line, kept
    deliberately thin -- no reset time), one full detail line per rate-limit
    window that has a known reset time (e.g. both '5h' and 'Week' for
    Anthropic/OpenAI), and the active session goal (if any) on its own line.
    Returned as separate short lines (rather than one combined line) because
    OWUI's status UI hard-clamps every line to a single row (`line-clamp-1`,
    no way to disable per-event) -- one line per fact keeps each row inside
    that clamp instead of getting cut off mid-number.

    OWUI shows only the *last* emitted status line by default (the rest
    only appear once the user expands that message's status history), so
    the thin context+primary-window line is placed last on purpose. Goal and
    the per-window reset-time detail lines still show up immediately on
    expand.

    Both RPCs are read-only and already used elsewhere by the pipe
    (`sessions.describe`) or are simple/cheap (`usage.status`); any failure
    here must not affect the actual reply, so every error is swallowed and
    just omits that line. They're fetched concurrently (not one after the
    other) so this adds at most one round trip's worth of latency, not two,
    to the moment the status line settles after the reply text is done.

    `run_usage`: the reply's own run's last-call usage. Its prompt tokens are
    the context fill, over the row's `totalTokens`: OpenClaw 2026.10 writes a
    session's first totals to its row just after the run ends, so a new
    chat's first reply found none there, and every later reply read the run
    before it (ELI-177). The window (`contextTokens`) still comes from the row.
    """
    describe_task = asyncio.ensure_future(
        conn.send_request("sessions.describe", dict(key=session_key), timeout=timeout)
    )
    usage_task = asyncio.ensure_future(conn.send_request("usage.status", {}, timeout=timeout))

    context_bit = None
    goal_line = None
    provider = None
    try:
        desc = await describe_task
        session_row = (desc or {}).get("session") or {}
        provider = session_row.get("modelProvider")
        context_tokens = session_row.get("contextTokens")
        total_tokens = _usage_prompt_tokens(run_usage) or session_row.get("totalTokens")
        if context_tokens and total_tokens is not None:
            pct = round(total_tokens / context_tokens * 100, 1)
            context_bit = f"🧠 {_fmt_tokens(total_tokens)}/{_fmt_tokens(context_tokens)} ({pct:g}%)"
        goal = session_row.get("goal")
        if goal:
            goal_line = _format_goal_line(goal) or None
    except Exception:
        pass

    primary_bit = None
    reset_lines = []
    try:
        usage = await usage_task
        if provider:
            for p in (usage or {}).get("providers", []):
                if p.get("provider") != provider:
                    continue
                windows = p.get("windows") or []
                bits = [b for b in (_window_bit(w) for w in windows) if b]
                if bits:
                    primary_bit = f"⏱ {bits[0]}"
                elif p.get("summary"):
                    primary_bit = f"⏱ {p['summary']}"
                # A full "(resets in ...)" line per window that actually has
                # a known reset time -- including the same window already
                # folded into `primary_bit`, since that one stays thin (no
                # reset time) on purpose.
                reset_lines = [
                    line for line in (_window_reset_line(w) for w in windows) if line
                ]
                break
    except Exception:
        pass

    context_and_primary = " · ".join(bit for bit in (context_bit, primary_bit) if bit) or None

    return [line for line in (goal_line, *reset_lines, context_and_primary) if line]


async def _emit_message_snapshot(__event_emitter__, content):
    """Write `content` to the reply's stored message with a `replace` event.

    Open WebUI 0.12 writes it even while the message is `done: false` (the
    message upsert has no done guard), and its end-of-reply save then sets
    `content` from `output`, over it. So it shows only when a reply never
    reaches that save. Probed on 0.12.0 (ELI-160 slice 8).
    """
    if not __event_emitter__ or not content:
        return
    await __event_emitter__(
        {"type": "replace", "data": {"content": content}}
    )



# ---------------------------------------------------------------------------
# A tab's input dialog and `execute` share one callback (ELI-195).
#
# Open WebUI 0.12's Chat.svelte keeps one callback slot for its `input` and
# `confirmation` dialogs and for `execute`: each of these events overwrites
# it on arrival, and the dialog's Confirm / Cancel answers whatever the slot
# holds then. An `execute` that reaches a tab while its dialog is open takes
# the dialog's answer, so the click is lost and the asker never hears back.
# While a dialog is open on a socket, the socket is recorded here (shared by
# the Pipe and the Action through `_shared_gateway_state`): an emitted
# `execute` skips it and is delivered once the dialog is answered, and a
# called one (a query) is not sent to it.
# ---------------------------------------------------------------------------

_SLOT_DIALOG_TYPES = ("input", "confirmation")
_local_dialog_holds: dict = {}


def _dialog_holds() -> dict:
    """sid -> {"user_id", "open": open dialogs, "held": event payloads}."""
    state = _shared_gateway_state()
    return _local_dialog_holds if state is None else state.setdefault("dialog_holds", {})


def _dialog_open_on(sid) -> bool:
    return bool(sid) and sid in _dialog_holds()


@contextlib.asynccontextmanager
async def _holding_executes(sid, user_id, kind):
    """Record `sid` as showing a dialog of `kind` for the block's duration,
    then deliver the `execute` events held for it meanwhile, in order."""
    if not sid or kind not in _SLOT_DIALOG_TYPES:
        yield
        return
    holds = _dialog_holds()
    entry = holds.get(sid)
    if entry is None:
        entry = holds[sid] = {"user_id": user_id, "open": 0, "held": []}
    entry["open"] += 1
    try:
        yield
    finally:
        entry["open"] -= 1
        if entry["open"] <= 0 and holds.get(sid) is entry:
            del holds[sid]
            if entry["held"]:
                pipe_log(f"  dialog on {str(sid)[:8]}... answered: delivering "
                         f"{len(entry['held'])} held execute event(s)")
            for payload in entry["held"]:
                try:
                    from open_webui.socket.main import sio
                    await sio.emit("events", payload, to=sid)
                except Exception as ex:
                    pipe_log(f"  held execute to {str(sid)[:8]}... failed: {ex!r}")


def _dialog_safe_emitter(emitter, user_id, chat_id, message_id):
    """`emitter`, except that an `execute` skips the user's sockets with an
    open dialog (OWUI's emitter sends to the whole `user:<id>` room) and is
    held for them."""
    if emitter is None or not user_id:
        return emitter

    async def emit(event):
        busy = []
        if isinstance(event, dict) and event.get("type") == "execute":
            holds = _dialog_holds()
            busy = [sid for sid, e in list(holds.items()) if e.get("user_id") == user_id]
        if not busy:
            return await emitter(event)
        payload = {"chat_id": chat_id, "message_id": message_id, "data": event}
        for sid in busy:
            holds[sid]["held"].append(payload)
        pipe_log(f"  execute held for {len(busy)} tab(s) with an open dialog")
        from open_webui.socket.main import sio
        await sio.emit("events", payload, room=f"user:{user_id}", skip_sid=busy)

    return emit


def _dialog_safe_event_call(event_call, sid, user_id):
    """`event_call` (bound to socket `sid`), recording its dialogs and never
    sending an `execute` while one is open there: that query answers None."""
    if event_call is None:
        return None

    async def call(payload):
        kind = (payload or {}).get("type")
        if kind == "execute" and _dialog_open_on(sid):
            pipe_log(f"  execute query not sent: {str(sid)[:8]}... shows a dialog")
            return None
        async with _holding_executes(sid, user_id, kind):
            return await event_call(payload)

    return call


# --- composer --------------------------------------------------------------

# ---------------------------------------------------------------------------
# Composer "Status" button (experiment).
#
# Open WebUI (0.12) has no hook for adding a button to the composer row:
# filter chips there only toggle a filter or open its valves. So the button is
# installed by an `execute` event, the same unsandboxed in-page JS channel the
# Status dialog already uses. Chat.svelte runs an `execute` event only when
# its chat_id is the chat the tab shows AND its message_id is already in that
# tab's history; anything else is silently dropped. The snippet:
#
#   * is idempotent: it records itself on `window.__openclawComposerBtn` with a
#     version, so a repeat delivery only refreshes its config, and a newer
#     version tears the old one down before installing itself;
#   * keeps the button present with one MutationObserver (debounced), across
#     re-renders and chat switches (OWUI is a SPA, the composer is rebuilt
#     freely), and gives up for good if it ever has to re-insert the button
#     in a tight loop;
#   * shows the button only on `/c/<id>` pages whose chat model is one of this
#     Pipe's models (one chat fetch per chat, cached for the page lifetime),
#     and removes it everywhere else;
#   * places it right after the "OpenClaw Thinking" filter chip, or at the end
#     of the composer's chip group when that chip is off; when neither anchor
#     exists it shows nothing;
#   * on click POSTs to the Status Action with the same body shape the dialog's
#     own Compact button uses, so the existing Action flow opens the real
#     dialog. The body is built from what the page already has: the chat's
#     model (each delivery names it) and the latest user message on screen,
#     so a click never downloads the chat;
#   * takes over the message toolbar's "OpenClaw Status" button the same way
#     when it knows the chat's model. Open WebUI's own handler uploads every
#     message of the branch before the Action runs and saves the whole chat
#     after it returns: on a 14 MB chat over a phone connection that is 8 s
#     before the dialog shows and a 14 MB upload after (perf/status_open.py).
#     Unknown model: Open WebUI's handler runs as before;
#   * never throws into the page: errors become one console warning each and,
#     for a failed click, a small toast.
#
# It is delivered three ways, all cheap and all idempotent:
#   (a) the Status Action emits it after every status run (one spark click
#       installs it);
#   (b) the Pipe emits it at the start of each turn;
#   (c) the Pipe's composer watcher pushes it to one socket as soon as that
#       socket opens a chat on one of this Pipe's models (Open WebUI 0.12
#       records each socket's open chat in SESSION_POOL[sid]["chat_ids"]).
#
# (a) and (b) target whatever message the emitter is bound to. (c) targets the
# chat's latest *user* message on purpose: OWUI's event handler writes back a
# shallow copy of the targeted message after running the code, and a user
# message is the one kind that never streams, so the push can never clobber a
# reply that is streaming into the same tab.
# ---------------------------------------------------------------------------

_COMPOSER_BUTTON_VERSION = "7"

# The Status Action's function id (install_action.py's FUNCTION_ID; the
# dialog's own JS calls the same fixed id) and the Pipe's default function id.
# A Pipe installed under another id still works: it adds its own id (from the
# module name OWUI gives it) and the prefix of every model it serves.
_COMPOSER_ACTION_ID = "openclaw_status_action"
_COMPOSER_DEFAULT_MODEL_PREFIX = "openclaw_gateway."

# Name of the Thinking filter's chip (install_filter.py registers the filter
# under this name, and OWUI renders it as the chip icon's alt text). The button
# goes right after that chip when it is on screen.
_COMPOSER_THINKING_CHIP_LABEL = "OpenClaw Thinking"

_COMPOSER_BUTTON_JS_TEMPLATE = r"""
(function () {
  const CFG = __OPENCLAW_COMPOSER_CONFIG__;
  const KEY = '__openclawComposerBtn';
  try {
    const prev = window[KEY];
    if (prev && prev.version === CFG.version) {
      if (typeof prev.configure === 'function') prev.configure(CFG);
      return;
    }
    if (prev && typeof prev.teardown === 'function') {
      try { prev.teardown(); } catch (e) { /* the old copy is going away anyway */ }
    }
  } catch (e) {
    console.warn('[openclaw-composer] guard failed', e);
    return;
  }

  const BTN_ID = 'openclaw-composer-status-button';
  // A chat that is not OpenClaw is looked at again after this long (its model
  // can be switched); an OpenClaw chat stays OpenClaw for the page lifetime.
  const NEGATIVE_TTL_MS = 600000;
  // Re-inserting the button more often than this means something keeps
  // removing it (a layout this snippet does not understand): give up.
  const LOOP_LIMIT = 20;
  const LOOP_WINDOW_MS = 10000;
  // A crab claw (ELI-231): an open pincer with a tooth on each finger and a
  // wrist, in Heroicons' outline style (24x24, round caps), for "Claw".
  const CLAW_PATH = 'M6.3 14.6C4.6 11.7 5.7 7.1 8.7 4.6C10.8 2.8 13.4 2.3 15.6 3.1C14.3 3.7 13.4 4.4 13 5.3L13.9 6.5L12 6.9C11.6 7.5 11.3 8.1 11.2 8.7C11.1 11 12.7 12.9 15.1 12.7C16.4 12.5 17.3 11.9 17.8 11.1L17.1 10L18.6 9.7C18.6 9.2 18.6 8.7 18.5 8.2C20.5 10.2 20.6 13.4 18.9 15.8C17.1 18.3 14.2 18.8 11.6 17.8C9.5 17 7.5 16.1 6.3 14.6ZM7.8 16L5.4 19.6L9.1 21.1L11 17.6';

  const state = {
    prefixes: [],
    // Informational only: the Action does not use it for the status path.
    sessionId: null,
    cache: {},
    // chat id -> its model, from the deliveries.
    models: {},
    inflight: {},
    observer: null,
    timer: null,
    busy: false,
    inserts: [],
    warned: {},
    dead: false,
  };

  function warnOnce(tag, err) {
    if (state.warned[tag]) return;
    state.warned[tag] = true;
    try { console.warn('[openclaw-composer] ' + tag, err); } catch (e) { /* no console */ }
  }

  function configure(cfg) {
    (cfg.modelPrefixes || []).forEach(function (p) {
      if (typeof p === 'string' && p && state.prefixes.indexOf(p) === -1) state.prefixes.push(p);
    });
    if (cfg.sessionId) state.sessionId = cfg.sessionId;
    // A delivery names the chat it was sent for, and is only ever sent for
    // an OpenClaw chat, so that chat needs no lookup.
    if (typeof cfg.chatId === 'string' && cfg.chatId) {
      state.cache[cfg.chatId] = { ok: true, vouched: true, at: Date.now() };
      if (typeof cfg.chatModel === 'string' && cfg.chatModel) state.models[cfg.chatId] = cfg.chatModel;
    }
    schedule();
  }

  function token() {
    try { return localStorage.getItem('token') || ''; } catch (e) { return ''; }
  }

  function currentChatId() {
    const m = /^\/c\/([^\/?#]+)\/?$/.exec(location.pathname);
    if (!m) return null;
    const id = decodeURIComponent(m[1]);
    // Temporary chats are never saved, so there is nothing to look up.
    if (id.indexOf('local:') === 0) return null;
    return id;
  }

  function isOpenclawModel(id) {
    return typeof id === 'string' && state.prefixes.some(function (p) { return id.indexOf(p) === 0; });
  }

  function chatModel(chat) {
    const c = (chat && chat.chat) || {};
    const candidates = Array.isArray(c.models) ? c.models.slice() : [];
    const h = c.history || {};
    const cur = h.messages && h.currentId ? h.messages[h.currentId] : null;
    if (cur && cur.model) candidates.push(cur.model);
    for (let i = 0; i < candidates.length; i++) {
      if (isOpenclawModel(candidates[i])) return candidates[i];
    }
    return null;
  }

  // Latest user message on the current branch, else the current leaf. The
  // Action's dialog events target this id, and a user message never streams,
  // so a dialog opened mid-reply cannot race the reply's own updates.
  function targetMessageId(chat) {
    const h = ((chat && chat.chat) || {}).history || {};
    const msgs = h.messages || {};
    let id = h.currentId;
    for (let i = 0; id && i < 500; i++) {
      const m = msgs[id];
      if (!m) break;
      if (m.role === 'user') return id;
      id = m.parentId;
    }
    return h.currentId || null;
  }

  // The message a toolbar button belongs to: Open WebUI renders each message
  // in a `message-<id>` element.
  function messageIdOf(el) {
    const m = el && el.closest('[id^="message-"]');
    return m ? m.id.slice('message-'.length) : null;
  }

  // The latest user message on screen: the current branch's, as rendered.
  function latestUserMessageId() {
    const users = document.querySelectorAll('.chat-user');
    return users.length ? messageIdOf(users[users.length - 1]) : null;
  }

  function postAction(body) {
    return fetch('/api/chat/actions/' + CFG.actionId, {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + token(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (r && !r.ok) {
        return r.json().catch(function () { return {}; }).then(function (j) {
          throw new Error((j && j.detail) || ('HTTP ' + r.status));
        });
      }
    });
  }

  // The model a reply was written by, from its avatar: Open WebUI renders it
  // as `/models/model/profile/image?id=<model id>` inside the message.
  function modelOfMessage(el) {
    const img = el && el.querySelector('img[src*="/models/model/profile/image?id="]');
    if (!img) return null;
    try {
      const id = new URL(img.getAttribute('src'), location.origin).searchParams.get('id');
      return isOpenclawModel(id) ? id : null;
    } catch (e) {
      return null;
    }
  }

  // The newest reply's model on screen.
  function latestReplyModel() {
    const replies = document.querySelectorAll('.chat-assistant');
    const el = replies.length ? replies[replies.length - 1].closest('[id^="message-"]') : null;
    return modelOfMessage(el);
  }

  // The body from what the page has, or null when it lacks the model or a
  // message (then the chat is read). `model`: the page's own reading of it,
  // for a chat no delivery has named yet.
  function bodyFromPage(chatId, messageId, model) {
    model = state.models[chatId] || model;
    if (!model || !messageId) return null;
    return { model: model, chat_id: chatId, id: messageId, session_id: state.sessionId || 'openclaw-composer' };
  }

  function fetchChat(chatId) {
    return fetch('/api/v1/chats/' + encodeURIComponent(chatId), {
      headers: { 'Authorization': 'Bearer ' + token() },
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  function classify(chatId) {
    if (state.inflight[chatId]) return;
    state.inflight[chatId] = true;
    fetchChat(chatId).then(function (chat) {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: !!chatModel(chat), at: Date.now() };
    }, function () {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: false, at: Date.now() };
    }).then(function () {
      delete state.inflight[chatId];
      schedule();
    });
  }

  function toast(text) {
    try {
      const dark = document.documentElement.classList.contains('dark');
      const el = document.createElement('div');
      el.setAttribute('role', 'status');
      el.textContent = text;
      el.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);'
        + 'z-index:10001;max-width:min(420px,90vw);padding:10px 14px;border-radius:12px;'
        + 'font-size:13px;line-height:1.4;box-shadow:0 4px 16px rgba(0,0,0,0.18);';
      el.style.background = dark ? '#1f2937' : '#ffffff';
      el.style.color = dark ? '#f3f4f6' : '#111827';
      el.style.border = '1px solid ' + (dark ? '#374151' : '#e5e7eb');
      document.body.appendChild(el);
      setTimeout(function () { el.remove(); }, 4000);
    } catch (e) {
      warnOnce('toast failed', text);
    }
  }

  // The POST body the Status Action receives. Same shape as the dialog's own
  // Compact button, minus `mode`, so the Action takes its normal status path.
  function actionBody(chatId, chat) {
    let model = chatModel(chat);
    const c = (chat && chat.chat) || {};
    const entry = state.cache[chatId];
    if (!model && entry && entry.vouched && Array.isArray(c.models) && typeof c.models[0] === 'string') {
      // A workspace model built on an OpenClaw model: its id has none of the
      // Pipe's prefixes, but the Pipe itself vouched for this chat.
      model = c.models[0];
    }
    const messageId = targetMessageId(chat);
    if (!model || !messageId) return null;
    return {
      model: model,
      chat_id: chatId,
      id: messageId,
      session_id: state.sessionId || 'openclaw-composer',
    };
  }

  function openStatus(btn) {
    if (state.busy) return;
    const chatId = currentChatId();
    if (!chatId) return;
    state.busy = true;
    btn.style.opacity = '0.6';
    const known = bodyFromPage(chatId, latestUserMessageId(), latestReplyModel());
    (known ? Promise.resolve(known) : fetchChat(chatId).then(function (chat) {
      return actionBody(chatId, chat);
    })).then(function (body) {
      if (!body) throw new Error('this chat has no OpenClaw message yet');
      return postAction(body);
    }).catch(function (err) {
      console.warn('[openclaw-composer] status failed', err);
      toast('OpenClaw status: ' + ((err && err.message) || err));
    }).then(function () {
      state.busy = false;
      btn.style.opacity = '';
    });
  }

  // Capture phase, so it runs before Open WebUI's own click handler on the
  // button and can stop it.
  function onToolbarClick(e) {
    const btn = e.target && e.target.closest && e.target.closest('button[aria-label="OpenClaw Status"]');
    const chatId = btn ? currentChatId() : null;
    const message = btn ? btn.closest('[id^="message-"]') : null;
    const body = chatId ? bodyFromPage(chatId, messageIdOf(btn), modelOfMessage(message)) : null;
    if (!body) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    postAction(body).catch(function (err) {
      console.warn('[openclaw-composer] status failed', err);
      toast('OpenClaw status: ' + ((err && err.message) || err));
    });
  }

  function makeButton() {
    const b = document.createElement('button');
    b.type = 'button';
    b.id = BTN_ID;
    // Shown as "Claw" (ELI-202); the aria-label keeps its old name, which the
    // page scripts and the tests find the button by.
    b.title = 'Claw';
    b.setAttribute('aria-label', 'OpenClaw status');
    b.dataset.openclawVersion = CFG.version;
    b.className = 'p-[0.375rem] flex gap-1 items-center text-sm rounded-full '
      + 'transition-colors duration-300 focus:outline-hidden shrink-0 '
      + 'bg-transparent text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800';
    b.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
      + 'stroke-width="1.75" stroke="currentColor" aria-hidden="true" class="size-4">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="' + CLAW_PATH + '"/></svg>'
      // Icon-only below `sm`, like Open WebUI's own composer chips: at phone
      // width the chip row's overflow cut the label to "Stat" (ELI-123). The
      // title and aria-label still name it. Both classes ship in Open WebUI's CSS.
      + '<span class="pr-0.5 hidden sm:inline">Claw</span>';
    b.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      openStatus(b);
    });
    return b;
  }

  // {parent, after}: insert right after `after` inside `parent`, or at the end
  // of `parent` when `after` is null. null when no known anchor is on screen.
  function findSlot() {
    const integ = document.getElementById('integration-menu-button');
    const form = integ ? integ.closest('form') : null;
    if (!form) return null;
    const imgs = form.querySelectorAll('img[alt]');
    for (let i = 0; i < imgs.length; i++) {
      if (imgs[i].getAttribute('alt') !== CFG.thinkingChipLabel) continue;
      const chip = imgs[i].closest('button');
      const wrap = chip ? chip.parentElement : null;
      if (wrap && wrap.parentElement && form.contains(wrap.parentElement)) {
        return { parent: wrap.parentElement, after: wrap };
      }
    }
    // The chip is only rendered while the filter is on. Fall back to the end
    // of the chip group the composer always renders next to it.
    const row = integ.closest('div.justify-between');
    if (!row || !form.contains(row)) return null;
    const chips = row.querySelector(':scope > div.flex-1');
    const groups = chips ? chips.querySelectorAll(':scope > div.shrink-0') : [];
    if (groups.length) return { parent: groups[groups.length - 1], after: null };
    return null;
  }

  function removeAll() {
    const all = document.querySelectorAll('#' + BTN_ID);
    for (let i = 0; i < all.length; i++) all[i].remove();
  }

  function ensure() {
    if (state.dead) return;
    const chatId = currentChatId();
    let show = false;
    if (chatId) {
      const c = state.cache[chatId];
      if (!c || (!c.ok && Date.now() - c.at > NEGATIVE_TTL_MS)) classify(chatId);
      show = !!(c && c.ok);
    }
    const slot = show ? findSlot() : null;
    if (!slot) {
      removeAll();
      return;
    }
    const all = document.querySelectorAll('#' + BTN_ID);
    let btn = all.length ? all[0] : null;
    for (let i = 1; i < all.length; i++) all[i].remove();
    if (btn && btn.dataset.openclawVersion !== CFG.version) {
      btn.remove();
      btn = null;
    }
    const placed = btn && (slot.after
      ? slot.after.nextElementSibling === btn
      : slot.parent.lastElementChild === btn);
    if (placed) return;
    const now = Date.now();
    state.inserts = state.inserts.filter(function (t) { return now - t < LOOP_WINDOW_MS; });
    state.inserts.push(now);
    if (state.inserts.length > LOOP_LIMIT) {
      warnOnce('the composer keeps removing the button; giving up until reload', null);
      teardown();
      state.dead = true;
      return;
    }
    if (!btn) btn = makeButton();
    if (slot.after) slot.after.insertAdjacentElement('afterend', btn);
    else slot.parent.appendChild(btn);
  }

  function schedule() {
    if (state.timer || state.dead) return;
    state.timer = setTimeout(function () {
      state.timer = null;
      try { ensure(); } catch (e) { warnOnce('ensure failed', e); }
    }, 150);
  }

  function teardown() {
    if (state.observer) state.observer.disconnect();
    state.observer = null;
    if (state.timer) clearTimeout(state.timer);
    state.timer = null;
    window.removeEventListener('popstate', schedule);
    document.removeEventListener('click', onToolbarClick, true);
    try { removeAll(); } catch (e) { /* page is going away */ }
  }

  try {
    window[KEY] = {
      version: CFG.version,
      configure: configure,
      teardown: teardown,
      ensure: ensure,
      // For live checks from the console; not used by the page.
      debug: function () {
        const chatId = currentChatId();
        return {
          version: CFG.version, chatId: chatId, prefixes: state.prefixes.slice(),
          cached: chatId ? state.cache[chatId] || null : null, dead: state.dead,
          slot: !!findSlot(), buttons: document.querySelectorAll('#' + BTN_ID).length,
          inserts: state.inserts.length,
        };
      },
      actionBody: actionBody,
      openStatus: openStatus,
    };
    state.observer = new MutationObserver(schedule);
    state.observer.observe(document.body, { childList: true, subtree: true });
    window.addEventListener('popstate', schedule);
    document.addEventListener('click', onToolbarClick, true);
    configure(CFG);
  } catch (e) {
    warnOnce('install failed', e);
  }
})();
"""


def _composer_own_function_id():
    """This artifact's Open WebUI function id, from the module name OWUI's
    loader gives it (`function_<id>_<32 hex>`, utils/plugin.py), or None
    outside Open WebUI."""
    m = re.match(r"^function_(.+)_[0-9a-f]{32}$", globals().get("__name__") or "")
    return m.group(1) if m else None


def _composer_model_prefixes(model_id=None, own_id=None) -> list:
    """The model-id prefixes the button treats as OpenClaw chats: the default
    Pipe id, the Pipe's own function id when known, and the function id of
    `model_id` (a model this Pipe actually served)."""
    prefixes = [_COMPOSER_DEFAULT_MODEL_PREFIX]
    extra = []
    if isinstance(own_id, str) and own_id:
        extra.append(own_id + ".")
    if isinstance(model_id, str) and "." in model_id:
        extra.append(model_id.split(".", 1)[0] + ".")
    for p in extra:
        if p not in prefixes:
            prefixes.append(p)
    return prefixes


def _render_composer_button_js(*, session_id=None, model_prefixes=None, chat_id=None,
                               chat_model=None) -> str:
    """The install snippet with its config embedded as one JSON literal (same
    no-interpolation rule as action.py's `_json_for_js`: `<` escaped so the
    payload can never close an enclosing script tag). `chat_model` is the
    vouched chat's model, carried only with `chat_id`."""
    config = {
        "version": _COMPOSER_BUTTON_VERSION,
        "actionId": _COMPOSER_ACTION_ID,
        "modelPrefixes": list(model_prefixes or [_COMPOSER_DEFAULT_MODEL_PREFIX]),
        "sessionId": session_id if isinstance(session_id, str) and session_id else None,
        "chatId": chat_id if isinstance(chat_id, str) and chat_id else None,
        "chatModel": chat_model if chat_id and isinstance(chat_model, str) and chat_model else None,
        "thinkingChipLabel": _COMPOSER_THINKING_CHIP_LABEL,
    }
    payload = json.dumps(config).replace("<", "\\u003c")
    return _COMPOSER_BUTTON_JS_TEMPLATE.replace("__OPENCLAW_COMPOSER_CONFIG__", payload)


async def _emit_composer_button(__event_emitter__, *, session_id=None, model_id=None,
                                chat_id=None, model_prefixes=None, chat_model=None) -> bool:
    """Emit the install snippet through an OWUI event emitter. Best effort:
    returns False instead of raising, because a cosmetic button must never
    fail the turn or the Action that carries it."""
    if not __event_emitter__:
        return False
    try:
        code = _render_composer_button_js(
            session_id=session_id,
            model_prefixes=model_prefixes or _composer_model_prefixes(model_id),
            chat_id=chat_id,
            chat_model=chat_model,
        )
        await __event_emitter__({"type": "execute", "data": {"code": code}})
        return True
    except Exception as ex:
        pipe_log(f"[composer] could not emit the status button: {ex}")
        return False


# --- action ----------------------------------------------------------------

# ---------------------------------------------------------------------------
# Milestone 1: prove a second OWUI Function can reach the OpenClaw gateway
# and read live session data, without disturbing the existing Pipe or its
# status-line code (emit.py / pipe.py are untouched by this fragment).
#
# Connection strategy, in order:
#   1. Reuse the Pipe's already-connected `_GatewayConnection` singleton.
#      The Pipe stashes it on `open_webui.socket.main` (a stable OWUI
#      module both Functions can import) purely so ITS OWN future redeploys
#      can find and clean up an orphaned previous connection -- see
#      `_STALE_CONN_ATTR` / `_remember_gateway_connection` in gateway.py.
#      This fragment only ever READS that attribute, never writes it: if we
#      also wrote there, whichever of {Pipe, Action} connected most
#      recently would silently "win" the slot, and the Pipe's own
#      `_reap_stale_gateway_connection()` could tear down a connection it
#      doesn't actually own on its next redeploy. Read-only avoids that
#      collision entirely.
#   2. If the Pipe hasn't connected yet in this process (e.g. right after a
#      container restart, before any chat turn happened -- in practice
#      unlikely, since this Action's button only appears above an existing
#      assistant message, which means the Pipe already ran at least once),
#      open our own connection. It still reuses the same STATE_DIR-persisted
#      device identity/token the Pipe already has, so this never triggers a
#      second `openclaw devices approve`. This fallback connection is owned
#      entirely by this module (its own singleton, never stashed on the
#      shared attribute) so it can never collide with the Pipe's bookkeeping
#      either.
#
# This fragment reuses gateway.py verbatim (see build.py's ACTION artifact),
# without the turn writer: its fallback connection only makes requests.

_action_fallback_connection: "_GatewayConnection | None" = None
_action_fallback_lock = asyncio.Lock()


async def _get_action_connection(valves_getter):
    """Return (connection, source) where source is "pipe" or "action-own"."""
    try:
        import open_webui.socket.main as _owui_socket_main
        pipe_conn = getattr(_owui_socket_main, _STALE_CONN_ATTR, None)
        if pipe_conn is not None:
            await pipe_conn.ensure_connected()
            return pipe_conn, "pipe"
    except Exception as ex:
        pipe_log(f"[status-action] could not reuse Pipe connection: {ex}")

    global _action_fallback_connection
    if _action_fallback_connection is None:
        async with _action_fallback_lock:
            if _action_fallback_connection is None:
                conn = _GatewayConnection(valves_getter)
                await conn.ensure_connected()
                _action_fallback_connection = conn
                return conn, "action-own"
    await _action_fallback_connection.ensure_connected()
    return _action_fallback_connection, "action-own"


# ---------------------------------------------------------------------------
# Milestone 2 (+ later, per-section independent loading): a real dialog
# instead of a toast, rendered via the "execute" event (runs unsandboxed in
# the actual OWUI page, not a sandboxed Rich UI iframe) so it can use
# OWUI's own live Tailwind classes and CSS custom properties directly --
# exact design-system match for free, no hand-tuned color palette, no
# guessing which of OWUI's several themes is active. The trade-off
# (unsandboxed JS) is acceptable here because the code is 100%
# admin-authored, not influenced by any untrusted input; the only dynamic
# values are our own gateway's numbers, passed in as a single JSON blob per
# section (never string-interpolated) so nothing can break out of the data
# payload.
#
# Each of Context, Rate Limits, and Subagents loads and fills independently:
# three separate skeleton placeholders open
# immediately, and each is replaced by its own `execute` fill event as soon
# as ITS OWN gateway call resolves, rather than one combined
# fetch-everything-then-render-once step where a slow call holds up
# everything else. Subagents is fully independent (sessions.list only, no
# dependency on the other two). Rate Limits genuinely needs the active
# provider's name, which only comes from sessions.describe -- rather than
# faking independence there, its fill waits on Context's own resolution of
# that RPC (shared Task, not a second request) before adding usage.status
# on top; it still has its own skeleton and fills in on its own schedule,
# separate from Context's.
#
# Shared JS helpers (bar rendering, color thresholds, section headers, the
# Compact button's click handler) are defined once in _MODAL_OPEN_JS_TEMPLATE and
# stashed on `window.__openclawStatus` rather than duplicated in each
# section's fill template -- each fill is its own separate `execute` call
# (a fresh top-level script, no shared scope with the others), so without
# this every section would need its own copy of ~30 lines of identical
# helper code.
# ---------------------------------------------------------------------------

_MODAL_OPEN_JS_TEMPLATE = r"""
(function() {
  const IDENTITY = __OPENCLAW_IDENTITY__;
  const existing = document.getElementById('openclaw-status-modal-root');
  if (existing) existing.remove();

  const isDark = document.documentElement.classList.contains('dark');

  // Used-percent -> color: green while healthy, amber approaching the
  // limit, red once it's mostly consumed. Same thresholds for every bar.
  //
  // Inline hex, not Tailwind utility classes: Tailwind only ships the
  // utility classes it finds referenced somewhere in ITS OWN build's
  // source, so a class this injected code invents (rather than one OWUI's
  // own frontend already uses) can silently have zero CSS behind it --
  // confirmed live: 'bg-rose-500' is never referenced anywhere in
  // open-webui/open-webui's own source, so that utility class was never
  // generated in OWUI's compiled stylesheet, and a bar using it rendered
  // as an invisible 0-color fill even at 86% width. Inline styles have no
  // dependency on the host page's Tailwind content scan at all.
  function barColor(usedPercent) {
    if (usedPercent >= 85) return '#f43f5e';
    if (usedPercent >= 60) return '#f59e0b';
    return '#10b981';
  }

  function makeBar(usedPercent) {
    const track = document.createElement('div');
    track.className = 'h-1.5 w-full rounded-full overflow-hidden';
    track.style.backgroundColor = isDark ? '#1f2937' : '#f3f4f6';
    const fill = document.createElement('div');
    const clamped = Math.max(0, Math.min(100, usedPercent));
    fill.className = 'h-full rounded-full';
    fill.style.backgroundColor = barColor(usedPercent);
    fill.style.width = clamped + '%';
    track.appendChild(fill);
    return track;
  }

  function sectionHeader(text) {
    const h = document.createElement('div');
    h.className = 'font-semibold tracking-wide uppercase '
      + 'text-gray-400 dark:text-gray-500 mb-1.5';
    h.style.fontSize = '10px';  // inline: see the panel's width below
    h.textContent = text;
    return h;
  }

  function errorEl(message) {
    const err = document.createElement('div');
    err.className = 'text-sm';
    err.style.color = isDark ? '#fb7185' : '#e11d48';
    err.textContent = message;
    return err;
  }

  // A section still loading: its title (when given) over a pulse.
  function skeletonSection(id, title) {
    const el = document.createElement('div');
    el.id = id;
    el.className = 'mb-4';
    if (title) el.appendChild(sectionHeader(title));
    // Marks the section as still loading until a fill replaces it.
    const pulse = document.createElement('div');
    pulse.dataset.openclawLoading = '1';
    pulse.innerHTML = '<div class="animate-pulse space-y-2">'
      + '<div class="h-3 w-2/3 bg-gray-200 dark:bg-gray-700 rounded"></div>'
      + '<div class="h-3 w-full bg-gray-200 dark:bg-gray-700 rounded"></div>'
      + '</div>';
    el.appendChild(pulse);
    return el;
  }

  // When the data was fetched (epoch ms), on the browser's clock like the
  // rate-limit resets: the Open WebUI server's timezone is not the reader's
  // (ELI-140).
  function clockTime(ms) {
    return new Date(ms).toLocaleTimeString([], {
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
  }

  // "Open in OpenClaw": this session's page in the Control UI, in a new tab
  // (CONTROL_UI_URL valve, ELI-141).
  function controlUiLink(url) {
    const a = document.createElement('a');
    a.href = url;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.className = 'text-xs text-blue-600 dark:text-blue-400 hover:underline whitespace-nowrap';
    a.textContent = 'Open in OpenClaw ↗';
    return a;
  }

  function touchFooter(fetchedAt, source) {
    const f = document.getElementById('openclaw-status-footer');
    if (f) f.textContent = 'Updated ' + clockTime(fetchedAt) + ' · via ' + source;
  }

  // Fetches back to this same Action (same-origin, unsandboxed execute
  // context -- no iframe/postMessage plumbing needed) with a synthetic
  // mode="compact" marker. Reads OWUI's own stored auth token directly
  // (confirmed against OWUI's frontend source: it keeps its bearer token
  // at localStorage['token']) rather than assuming cookie auth. The
  // chat/message/session identity is the *original* click's (captured at
  // open time, in IDENTITY -- these never change over the dialog's
  // lifetime and never need an RPC, unlike everything else here), so the
  // Python side's __event_emitter__ calls for this follow-up route back
  // to this same open tab. The fetch response itself is ignored -- all UI
  // updates arrive as separate execute events pushed from the Python side
  // as the compact operation progresses.
  function triggerCompact() {
    const token = localStorage.getItem('token');
    fetch('/api/chat/actions/openclaw_status_action', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + token,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: IDENTITY.owuiModel,
        chat_id: IDENTITY.chatId,
        id: IDENTITY.messageId,
        session_id: IDENTITY.sessionId,
        dialogId: IDENTITY.dialogId,
        mode: 'compact',
      }),
    }).catch(function(err) {
      const wrap = document.getElementById('openclaw-status-sections');
      if (!wrap) return;
      wrap.innerHTML = '';
      wrap.appendChild(errorEl('Could not start compact: ' + err));
    });
  }

  // TaskSummary timestamps can arrive as either an ISO string or an epoch-ms
  // integer (schema allows both) -- normalize once here rather than in every
  // caller. Elapsed time is computed client-side from raw ms (not a
  // server-formatted duration) for the same reason resetAtMs already is:
  // avoids clock-skew between whenever the RPC resolved and whenever the
  // user actually reads the row.
  function toMs(v) {
    if (v == null) return null;
    if (typeof v === 'number') return v;
    const parsed = new Date(v).getTime();
    return isNaN(parsed) ? null : parsed;
  }

  function elapsedTime(startedAt, endedAt) {
    const startMs = toMs(startedAt);
    if (startMs == null) return '';
    const endMs = toMs(endedAt) || Date.now();
    const deltaS = Math.max(0, Math.floor((endMs - startMs) / 1000));
    const days = Math.floor(deltaS / 86400);
    const hours = Math.floor((deltaS % 86400) / 3600);
    const minutes = Math.floor((deltaS % 3600) / 60);
    if (days) return days + 'd' + String(hours).padStart(2, '0') + 'h';
    if (hours) return hours + 'h' + String(minutes).padStart(2, '0') + 'm';
    if (minutes) return minutes + 'm';
    return deltaS + 's';
  }

  // The dialog's own requests back to this same Action, the way
  // triggerCompact() makes one: same-origin, OWUI's stored token, and the
  // opening click's identity, so the Action's pushed fills reach this tab.
  function askAction(extra) {
    return fetch('/api/chat/actions/openclaw_status_action', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + localStorage.getItem('token'),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(Object.assign({
        model: IDENTITY.owuiModel,
        chat_id: IDENTITY.chatId,
        id: IDENTITY.messageId,
        session_id: IDENTITY.sessionId,
        dialogId: IDENTITY.dialogId,
      }, extra)),
    });
  }

  // A sub-agent's status as a coloured chip (ELI-155): the run statuses of
  // a child session, and the states an in-process agent's card tells.
  const CHIP = {
    queued: ['Queued', '#9ca3af'], running: ['Running', '#3b82f6'], completed: ['Done', '#10b981'],
    failed: ['Failed', '#f43f5e'], cancelled: ['Cancelled', '#f59e0b'], timed_out: ['Timed out', '#f59e0b'],
    ended: ['Ended', '#9ca3af'], launched: ['Background', '#9ca3af'], returned: ['Returned', '#10b981'],
    'cut off': ['Cut off', '#f59e0b'], scheduled: ['Scheduled', '#9ca3af'], skipped: ['Skipped', '#f59e0b'],
  };
  function setChip(chip, status) {
    const c = CHIP[status] || [String(status || 'unknown'), '#9ca3af'];
    chip.textContent = c[0];
    chip.style.color = c[1];
    chip.style.backgroundColor = c[1] + '22';
    return chip;
  }
  function statusChip(status) {
    const chip = document.createElement('span');
    chip.dataset.openclawChip = '1';
    chip.className = 'shrink-0 rounded-full font-semibold whitespace-nowrap';
    chip.style.fontSize = '11px';
    chip.style.padding = '1px 7px';
    return setChip(chip, status);
  }

  // Inline, for the same reason as barColor(): a class OWUI's build never
  // scanned can carry no CSS.
  function oneLine(el) {
    el.style.whiteSpace = 'nowrap';
    el.style.overflow = 'hidden';
    el.style.textOverflow = 'ellipsis';
    el.style.minWidth = '0';
    return el;
  }

  function clampLines(el, lines) {
    el.style.display = '-webkit-box';
    el.style.webkitBoxOrient = 'vertical';
    el.style.webkitLineClamp = String(lines);
    el.style.overflow = 'hidden';
    return el;
  }

  // A text clamped to `lines`, with "Show all". Whether it is open is kept
  // in `state[name]`, so a refill does not close it again.
  function textBlock(name, text, lines, state) {
    const wrap = document.createElement('div');
    wrap.dataset.openclawBlock = name;
    const body = document.createElement('div');
    body.dataset.openclawBlockText = '1';
    body.className = 'text-sm text-gray-700 dark:text-gray-200 whitespace-pre-wrap break-words';
    body.textContent = text;
    clampLines(body, lines);
    wrap.appendChild(body);
    const more = document.createElement('button');
    more.type = 'button';
    more.dataset.openclawMore = name;
    more.className = 'text-xs text-blue-600 dark:text-blue-400 mt-1';
    // Shown whole, the text scrolls in a box of at most 40% of the screen:
    // uncapped, a long task pushed the header, "Show less" and the whole run
    // below the bottom of the drawer, with nothing to scroll (ELI-201).
    function show(open) {
      body.style.webkitLineClamp = open ? 'unset' : String(lines);
      body.style.maxHeight = open ? '40vh' : '';
      body.style.overflowY = open ? 'auto' : 'hidden';
      body.style.overscrollBehavior = open ? 'contain' : '';
      more.textContent = open ? 'Show less' : 'Show all';
    }
    more.onclick = function() {
      state[name] = !state[name];
      show(state[name]);
      if (state[name]) return;
      // Clamped again, the preview is the text's first lines: a box left
      // scrolled showed two lines from wherever it was (ELI-236). And if
      // whatever holds the block scrolled past its top, bring it back.
      body.scrollTop = 0;
      wrap.scrollIntoView({ block: 'nearest' });
    };
    show(!!state[name]);
    wrap.appendChild(more);
    return wrap;
  }

  // The sub-agent drawer: a compact header, then the run as a read-only chat,
  // as the Pipe's history renderer draws it for the chat.

  // Open WebUI's tool card (ToolCallDisplay.svelte): its markup, classes and
  // icons, so a card here looks like one in the chat.
  const ICON = {
    done: '<svg class="size-4" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" aria-hidden="true">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="M9 12.75 11.25 15 15 9.75M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z"/></svg>',
    none: '<svg class="size-3.5" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'
      + '<path fill-rule="evenodd" d="M12 6.75a5.25 5.25 0 0 1 6.775-5.025.75.75 0 0 1 .313 1.248l-3.32 3.319c.063.475.276.934.641 1.299.365.365.824.578 1.3.64l3.318-3.319a.75.75 0 0 1 1.248.313 5.25 5.25 0 0 1-5.472 6.756c-1.018-.086-1.87.1-2.309.634L7.344 21.3A3.298 3.298 0 1 1 2.7 16.657l8.684-7.151c.533-.44.72-1.291.634-2.309A5.342 5.342 0 0 1 12 6.75ZM4.117 19.125a.75.75 0 0 1 .75-.75h.008a.75.75 0 0 1 .75.75v.008a.75.75 0 0 1-.75.75h-.008a.75.75 0 0 1-.75-.75v-.008Z" clip-rule="evenodd"/></svg>',
    down: '<svg class="size-3" fill="none" viewBox="0 0 24 24" stroke-width="3.5" stroke="currentColor" aria-hidden="true">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/></svg>',
    up: '<svg class="size-3" fill="none" viewBox="0 0 24 24" stroke-width="3.5" stroke="currentColor" aria-hidden="true">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="m4.5 15.75 7.5-7.5 7.5 7.5"/></svg>',
  };

  function parseJson(text) {
    let value = text;
    while (typeof value === 'string') {
      try { value = JSON.parse(value); } catch (e) { break; }
    }
    return value;
  }

  function cardLabel(text) {
    const el = document.createElement('div');
    el.className = 'text-[0.625rem] uppercase tracking-wider font-normal text-gray-400 dark:text-gray-500 mb-1.5 px-1';
    el.textContent = text;
    return el;
  }

  function cardPre(text, json) {
    const pre = document.createElement('pre');
    pre.className = json
      ? 'text-xs text-gray-600 dark:text-gray-300 whitespace-pre font-mono bg-gray-50 dark:bg-gray-900 rounded-lg p-2 overflow-x-auto'
      : 'text-xs text-gray-600 dark:text-gray-300 whitespace-pre-wrap break-words font-mono';
    pre.textContent = text;
    return pre;
  }

  // One tool call: collapsed, its name and a done mark; open, its input and
  // output. `opened[id]` keeps it open across refills, keyed by the call.
  function toolCard(c, opened) {
    const card = document.createElement('div');
    card.dataset.openclawCard = c.id || '';
    const btn = document.createElement('div');
    btn.dataset.openclawCardButton = '1';
    btn.setAttribute('role', 'button');
    btn.className = 'py-1 text-[0.9375rem] text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 transition '
      + 'w-full min-w-0 cursor-pointer';
    const row = document.createElement('div');
    row.className = 'w-full min-w-0 max-w-full font-normal flex items-center gap-1.5';
    const mark = document.createElement('div');
    mark.className = c.result == null ? 'text-gray-400 dark:text-gray-500' : 'text-emerald-500 dark:text-emerald-400';
    mark.innerHTML = c.result == null ? ICON.none : ICON.done;
    row.appendChild(mark);
    const label = document.createElement('div');
    label.className = 'flex-1 min-w-0 line-clamp-1';
    const name = document.createElement('span');
    name.dataset.openclawCardName = '1';
    name.className = 'text-black dark:text-white';
    name.textContent = c.name;
    label.appendChild(name);
    row.appendChild(label);
    const chevron = document.createElement('div');
    chevron.className = 'flex shrink-0 self-center translate-y-[1px]';
    row.appendChild(chevron);
    btn.appendChild(row);
    card.appendChild(btn);

    const body = document.createElement('div');
    body.className = 'border border-gray-50 dark:border-gray-850/30 rounded-2xl my-1.5 p-2.5 space-y-2';
    const input = document.createElement('div');
    input.appendChild(cardLabel('Input'));
    const args = parseJson(c.args || '');
    if (args && typeof args === 'object' && !Array.isArray(args)) {
      const list = document.createElement('div');
      list.className = 'px-1 space-y-0.5';
      Object.keys(args).forEach(function(key) {
        const line = document.createElement('div');
        line.className = 'flex gap-2 text-xs py-0.5';
        const k = document.createElement('span');
        k.className = 'font-normal text-gray-600 dark:text-gray-400 shrink-0';
        k.textContent = key;
        const v = document.createElement('span');
        v.className = 'text-gray-800 dark:text-gray-200 break-all';
        v.textContent = typeof args[key] === 'object' ? JSON.stringify(args[key]) : String(args[key]);
        line.appendChild(k);
        line.appendChild(v);
        list.appendChild(line);
      });
      input.appendChild(list);
    } else if (c.args) {
      input.appendChild(cardPre(String(c.args), false));
    }
    body.appendChild(input);
    const output = document.createElement('div');
    output.dataset.openclawCardOutput = '1';
    output.appendChild(cardLabel('Output'));
    if (c.result == null) {
      const none = document.createElement('div');
      none.className = 'text-xs text-gray-400 dark:text-gray-500 px-1';
      none.textContent = 'No result.';
      output.appendChild(none);
    } else {
      const parsed = parseJson(c.result);
      output.appendChild(parsed !== null && typeof parsed === 'object'
        ? cardPre(JSON.stringify(parsed, null, 2), true) : cardPre(c.result, false));
    }
    body.appendChild(output);
    card.appendChild(body);

    function show(open) {
      body.style.display = open ? 'block' : 'none';
      chevron.innerHTML = open ? ICON.up : ICON.down;
      card.dataset.open = open ? 'true' : 'false';
    }
    btn.onclick = function() { opened[c.id] = !opened[c.id]; show(opened[c.id]); };
    show(!!opened[c.id]);
    return card;
  }

  // A message's text, with a safe subset of Markdown: paragraphs, lists,
  // code blocks, **bold**, `code` and http(s) links. Built with textContent,
  // so nothing in the text is ever HTML.
  function inline(parent, text) {
    text.split(/(\*\*[^*\n]+\*\*|`[^`\n]+`|\[[^\]\n]+\]\(https?:\/\/[^)\s]+\))/).forEach(function(part) {
      if (!part) return;
      let el;
      if (/^\*\*[^*]+\*\*$/.test(part)) {
        el = document.createElement('strong');
        el.textContent = part.slice(2, -2);
      } else if (/^`[^`]+`$/.test(part)) {
        el = document.createElement('code');
        el.className = 'rounded px-1.5 bg-gray-100 dark:bg-gray-800 font-mono text-xs';
        el.textContent = part.slice(1, -1);
      } else if (/^\[[^\]]+\]\(https?:\/\//.test(part)) {
        el = document.createElement('a');
        el.textContent = part.slice(1, part.indexOf(']('));
        el.href = part.slice(part.indexOf('](') + 2, -1);
        el.target = '_blank';
        el.rel = 'noopener noreferrer';
        el.className = 'text-blue-600 dark:text-blue-400 underline';
      } else {
        el = document.createTextNode(part);
      }
      parent.appendChild(el);
    });
  }

  function prose(text) {
    const wrap = document.createElement('div');
    wrap.dataset.openclawText = '1';
    wrap.className = 'text-gray-800 dark:text-gray-200 break-words mb-2';
    wrap.style.fontSize = '15px';
    wrap.style.lineHeight = '1.6';
    String(text).split(/(```[\s\S]*?(?:```|$))/).forEach(function(chunk) {
      if (!chunk.trim()) return;
      if (chunk.indexOf('```') === 0) {
        const code = chunk.replace(/^```[^\n]*\n?/, '').replace(/```$/, '');
        const pre = cardPre(code.replace(/\n$/, ''), true);
        pre.className += ' mb-2';
        wrap.appendChild(pre);
        return;
      }
      chunk.split(/\n\s*\n/).forEach(function(block) {
        const lines = block.split('\n').filter(function(l) { return l.trim(); });
        if (!lines.length) return;
        const bullets = lines.every(function(l) { return /^\s*[-*] /.test(l); });
        const numbers = lines.every(function(l) { return /^\s*\d+[.)] /.test(l); });
        if (bullets || numbers) {
          const list = document.createElement(bullets ? 'ul' : 'ol');
          list.className = (bullets ? 'list-disc ' : '') + 'pl-5 mb-2';
          if (numbers) list.style.listStyleType = 'decimal';
          lines.forEach(function(l) {
            const li = document.createElement('li');
            inline(li, l.replace(/^\s*(?:[-*]|\d+[.)]) /, ''));
            list.appendChild(li);
          });
          wrap.appendChild(list);
          return;
        }
        const p = document.createElement('p');
        p.className = 'mb-2 whitespace-pre-wrap';
        if (/^#{1,6} /.test(lines[0])) {
          p.className += ' font-semibold';
          lines[0] = lines[0].replace(/^#{1,6} /, '');
        }
        inline(p, lines.join('\n'));
        wrap.appendChild(p);
      });
    });
    return wrap;
  }

  // A turn someone sent the sub-agent after its task, as a chat shows a
  // user message: a bubble on the right.
  function userTurn(text) {
    const row = document.createElement('div');
    row.dataset.openclawUser = '1';
    row.className = 'flex justify-end mb-3';
    const bubble = document.createElement('div');
    bubble.className = 'rounded-3xl bg-gray-50 dark:bg-gray-850 px-4 py-2 text-gray-800 dark:text-gray-200 '
      + 'whitespace-pre-wrap break-words';
    bubble.style.maxWidth = '85%';
    bubble.style.fontSize = '15px';
    bubble.textContent = text;
    row.appendChild(bubble);
    return row;
  }

  function note(kind, text, sub) {
    const el = document.createElement('div');
    el.dataset.openclawNote = kind;
    el.className = 'text-sm text-gray-500 dark:text-gray-400 mt-2 mb-2';
    const line = document.createElement('div');
    line.className = 'flex items-center gap-2';
    if (kind === 'working') {
      const dot = document.createElement('span');
      dot.className = 'inline-block rounded-full bg-blue-500 animate-pulse shrink-0';
      dot.style.width = '8px';
      dot.style.height = '8px';
      line.appendChild(dot);
    }
    const t = document.createElement('span');
    t.textContent = text;
    line.appendChild(t);
    el.appendChild(line);
    if (sub) {
      const s = document.createElement('div');
      s.dataset.openclawLatest = '1';
      s.className = 'text-xs text-gray-400 dark:text-gray-500 mt-1 whitespace-pre-wrap break-words';
      s.textContent = sub;
      clampLines(s, 3);
      el.appendChild(s);
    }
    return el;
  }

  // The header from what is known: the row at open, then each refill.
  function paintDrawer(root, task) {
    if (task.status) {
      const chip = document.getElementById('openclaw-drawer-chip');
      if (chip) setChip(chip, task.status);
      root.dataset.live = (task.status === 'running' || task.status === 'queued') ? 'true' : 'false';
    }
    const time = document.getElementById('openclaw-drawer-time');
    if (time) time.textContent = elapsedTime(task.startedAt, task.endedAt);
    if (task.task) root.__texts.task = task.task;
    if (task.model) root.__texts.model = task.model;
    const head = document.getElementById('openclaw-drawer-task');
    if (head && root.__texts.task && root.dataset.kind !== 'agent') {
      head.innerHTML = '';
      head.appendChild(textBlock('task', root.__texts.task, 2, root.__open));
      // "Show all" only where the clamp hid something (laid out by now).
      const body = head.children[0].children[0], more = head.children[0].children[1];
      if (!root.__open.task && body.scrollHeight <= body.clientHeight) more.style.display = 'none';
    }
    const meta = document.getElementById('openclaw-drawer-meta');
    if (meta) {
      meta.innerHTML = '';
      if (root.__texts.model) meta.appendChild(document.createTextNode(root.__texts.model));
      const parent = root.__parent;
      if (parent && parent.title) {
        meta.appendChild(document.createTextNode((root.__texts.model ? ' · ' : '') + 'from '));
        let link;
        if (parent.chatId) {
          link = document.createElement('a');
          link.href = '/c/' + parent.chatId;
        } else {
          link = document.createElement('button');
          link.type = 'button';
          link.onclick = function() {
            openSubagentDrawer({ id: parent.childKey, childSessionKey: parent.childKey, title: parent.title });
          };
        }
        link.dataset.openclawParent = '1';
        link.className = 'underline';
        link.textContent = parent.title;
        meta.appendChild(link);
      }
      if (root.__controlUiUrl) {
        const link = controlUiLink(root.__controlUiUrl);
        link.style.marginLeft = '8px';
        meta.appendChild(link);
      }
    }
  }

  // The run: every item, then where it stands. Keeps the reader's place: at
  // the bottom it follows the run, scrolled up it stays put.
  function fillDrawer(DATA) {
    const root = document.getElementById('openclaw-drawer-root');
    const stream = document.getElementById('openclaw-drawer-stream');
    if (!root || !stream || root.dataset.taskId !== DATA.childSessionKey) return;
    if (DATA.parent) root.__parent = DATA.parent;
    if (DATA.task) paintDrawer(root, DATA.task);
    const scroller = stream.parentElement;
    const first = !root.__filled;
    const atBottom = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 40;
    const top = scroller.scrollTop;
    root.__filled = true;

    stream.innerHTML = '';
    if (DATA.error) {
      stream.appendChild(errorEl(DATA.error));
      return;
    }
    const earlier = DATA.earlier;
    if (earlier) {
      const box = document.createElement('div');
      box.dataset.openclawEarlier = '1';
      box.className = 'text-xs text-gray-400 dark:text-gray-500 mb-3';
      const t = document.createElement('span');
      t.textContent = earlier.count
        ? earlier.count + ' earlier step' + (earlier.count === 1 ? '' : 's') + ' not shown' + (earlier.more ? ', and more' : '')
        : 'Earlier steps not shown';
      box.appendChild(t);
      if (!root.__earlier) {
        const more = document.createElement('button');
        more.type = 'button';
        more.dataset.openclawShowEarlier = '1';
        more.className = 'text-blue-600 dark:text-blue-400 ml-2';
        more.textContent = 'Show earlier steps';
        more.onclick = function() {
          root.__earlier = true;
          if (root.__ask) root.__ask();
        };
        box.appendChild(more);
      }
      stream.appendChild(box);
    }
    const items = DATA.items || [];
    items.forEach(function(it) {
      if (it.kind === 'user') stream.appendChild(userTurn(it.text));
      else if (it.kind === 'text') stream.appendChild(prose(it.text));
      else if (it.kind === 'tool') stream.appendChild(toolCard(it, root.__cards));
    });
    const status = DATA.task && DATA.task.status;
    if (DATA.task && DATA.task.error) {
      const err = errorEl(DATA.task.error);
      err.dataset.openclawRunError = '1';
      stream.appendChild(err);
    }
    if (DATA.note === 'cli-running') {
      stream.appendChild(note('working', 'Working… tool calls appear when this run ends', DATA.latest));
    } else if (DATA.note === 'cli-stopped') {
      stream.appendChild(note('stopped', 'Stopped: its tool calls were not saved.'
        + ' A claude-cli run saves them when it ends.'));
    } else if (status === 'running' || status === 'queued') {
      const steps = items.filter(function(it) { return it.kind === 'tool'; }).length;
      stream.appendChild(note('working', 'Working… (step ' + (steps + 1) + ')'));
    } else if (DATA.noteText) {
      stream.appendChild(note(DATA.note, DATA.noteText));
    }
    if (!stream.children.length) {
      const empty = document.createElement('div');
      empty.className = 'text-gray-400 dark:text-gray-500 text-xs';
      empty.textContent = 'No messages.';
      stream.appendChild(empty);
    }
    scroller.scrollTop = (first || atBottom) ? scroller.scrollHeight : top;
    const footer = document.getElementById('openclaw-drawer-footer');
    if (footer && DATA.fetchedAt) footer.textContent = 'Updated ' + clockTime(DATA.fetchedAt) + ' · via ' + DATA.source;
  }

  // A full-screen sheet with a ‹ Back button on a phone, a side panel on a
  // wide screen. `task.kind` "child" is a Gateway child session: it fills
  // from the Action, and while it runs the drawer asks again every few
  // seconds until it ends or the drawer closes. "agent" is an in-process
  // Agent call: its task and result, from its card, nothing to fetch.
  function openDrawer(task) {
    const old = document.getElementById('openclaw-drawer-root');
    if (old) (old.__close || function() { old.remove(); })();
    const child = task.kind !== 'agent';
    const phone = (window.innerWidth || 1024) < 768;

    const root = document.createElement('div');
    root.id = 'openclaw-drawer-root';
    root.className = 'fixed inset-0';
    // Inline: Open WebUI's CSS has no `z-[10000]` rule, so with the class the
    // drawer had no z-index at all and opened behind the Status dialog
    // (z-[9999]), which then swallowed every click on it (ELI-118).
    root.style.zIndex = '10000';
    root.dataset.taskId = task.childSessionKey || task.id;
    root.dataset.kind = child ? 'child' : 'agent';
    root.__texts = {};
    root.__open = {};
    root.__cards = {};
    root.__controlUiUrl = task.controlUiUrl || null;
    const onKey = function(e) { if (e.key === 'Escape') close(); };
    function close() {
      if (root.__poll) clearInterval(root.__poll);
      root.__poll = null;
      root.remove();
      document.removeEventListener('keydown', onKey);
    }
    root.__close = close;

    const backdrop = document.createElement('div');
    backdrop.className = 'absolute inset-0';
    backdrop.style.background = 'rgba(0,0,0,0.25)';
    backdrop.onclick = close;
    root.appendChild(backdrop);

    const panel = document.createElement('div');
    panel.className = 'absolute right-0 top-0 bottom-0 '
      + 'bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 flex flex-col';
    if (phone) {
      panel.style.width = '100%';
      panel.style.left = '0';
    } else {
      // A wide viewport keeps the sub-agent list glanceable beside it.
      panel.className += ' shadow-xl border-l border-gray-100 dark:border-gray-800';
      panel.style.width = 'min(480px, 92vw)';
    }
    panel.addEventListener('click', function(e) { e.stopPropagation(); });
    root.appendChild(panel);

    // The header: name, status and time; model and where it came from; the
    // head of its task.
    const header = document.createElement('div');
    header.className = 'px-4 pt-3 pb-3 border-b border-gray-100 dark:border-gray-800';
    const top = document.createElement('div');
    top.className = 'flex items-center gap-2';
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.onclick = close;
    if (phone) {
      closeBtn.textContent = '‹ Back';
      closeBtn.className = 'text-sm text-blue-600 dark:text-blue-400 shrink-0 pr-1';
      top.appendChild(closeBtn);
    }
    const titleEl = document.createElement('div');
    titleEl.dataset.openclawTitle = '1';
    titleEl.className = 'text-sm font-semibold flex-1';
    titleEl.textContent = task.title || task.id;
    oneLine(titleEl);
    top.appendChild(titleEl);
    const chip = statusChip(task.status);
    chip.id = 'openclaw-drawer-chip';
    top.appendChild(chip);
    const time = document.createElement('span');
    time.id = 'openclaw-drawer-time';
    time.className = 'text-xs text-gray-500 dark:text-gray-400 shrink-0';
    top.appendChild(time);
    if (!phone) {
      closeBtn.textContent = '×';
      closeBtn.className = 'text-xl leading-none text-gray-400 hover:text-gray-700 '
        + 'dark:hover:text-gray-200 px-1 shrink-0';
      top.appendChild(closeBtn);
    }
    header.appendChild(top);
    const meta = document.createElement('div');
    meta.id = 'openclaw-drawer-meta';
    meta.className = 'text-xs text-gray-500 dark:text-gray-400 mt-1';
    oneLine(meta);
    header.appendChild(meta);
    const taskHead = document.createElement('div');
    taskHead.id = 'openclaw-drawer-task';
    taskHead.className = 'mt-2';
    header.appendChild(taskHead);
    panel.appendChild(header);

    // The one scroller: the run.
    const content = document.createElement('div');
    content.className = 'flex-1 px-4 py-3';
    content.style.overflowY = 'auto';
    content.style.minHeight = '0';
    const stream = document.createElement('div');
    stream.id = 'openclaw-drawer-stream';
    content.appendChild(stream);
    panel.appendChild(content);
    if (child) stream.appendChild(skeletonSection('openclaw-drawer-loading'));

    if (child) {
      const footer = document.createElement('div');
      footer.id = 'openclaw-drawer-footer';
      footer.className = 'text-[11px] text-gray-400 dark:text-gray-600 px-4 py-2 '
        + 'border-t border-gray-100 dark:border-gray-800';
      footer.textContent = ' ';
      panel.appendChild(footer);
    }

    document.addEventListener('keydown', onKey);
    document.body.appendChild(root);
    paintDrawer(root, task);
    if (!child) {
      // Its task as the turn that started it, its result as the reply.
      const items = [];
      if (task.task) items.push({ kind: 'user', text: task.task });
      if (task.result) items.push({ kind: 'text', text: task.result });
      fillDrawer({ childSessionKey: root.dataset.taskId, items: items,
                   note: task.status === 'running' ? 'working' : 'agent', noteText: {
        launched: 'Running in the background: its report comes as a message of its own.',
        'cut off': 'Cut off: the run ended before it returned.', running: 'Working…' }[task.status] });
      return;
    }

    // Each refresh is one Action request that fills the drawer once; the
    // next waits for it to come back. A fill that ends the run stops it.
    let inflight = false;
    let firstAsk = true;
    function ask() {
      if (inflight) return;
      inflight = true;
      const done = function() { inflight = false; };
      askAction({ mode: 'subagent-detail', opened: true, taskId: root.dataset.taskId,
                  first: firstAsk, earlier: !!root.__earlier }).then(done, done);
      firstAsk = false;
    }
    root.__ask = ask;
    function refresh() {
      if (!root.isConnected || root.dataset.live === 'false') {
        if (root.__poll) clearInterval(root.__poll);
        root.__poll = null;
        return;
      }
      ask();
    }
    if (task.server) firstAsk = false;
    else ask();
    if (root.dataset.live === 'true') root.__poll = setInterval(refresh, IDENTITY.subagentPollMs || 2500);
  }

  function openSubagentDrawer(task) {
    openDrawer(Object.assign({}, task, { kind: 'child' }));
  }

  function openAgentDetail(agent) {
    openDrawer({ kind: 'agent', id: agent.id, title: agent.title, status: agent.state,
                 task: agent.task, result: agent.result, startedAt: agent.startedAt });
  }

  // "Subagents (3)", or "(20 of 31)" when the list is capped.
  function countLabel(name, shown, total) {
    return name + ' (' + (total > shown ? shown + ' of ' + total : shown) + ')';
  }

  // A section that folds (ELI-163): its title with its count, and a chevron.
  // It opens when something in it runs at its first fill and is closed
  // otherwise; a tap wins after that, so a refill leaves it as it is.
  // `onOpen`: what to fetch the first time it is open (once per dialog).
  const folds = {};
  const foldFetched = {};
  function collapsible(name, label, live, onOpen) {
    if (!(name in folds)) folds[name] = !!live;
    const wrap = document.createElement('div');
    wrap.dataset.openclawFold = name;
    const head = document.createElement('button');
    head.type = 'button';
    head.dataset.openclawFoldHead = name;
    head.className = 'w-full flex items-center gap-2 text-left mb-1.5 '
      + 'text-gray-400 dark:text-gray-500 hover:text-gray-700 dark:hover:text-gray-200';
    // Divs, not spans: a 10 px span in a list is its time cell.
    const text = document.createElement('div');
    text.className = 'flex-1 font-semibold tracking-wide uppercase';
    text.style.fontSize = '10px';  // inline: see sectionHeader()
    text.textContent = label;
    head.appendChild(text);
    const chevron = document.createElement('div');
    chevron.className = 'flex shrink-0';
    head.appendChild(chevron);
    wrap.appendChild(head);
    const body = document.createElement('div');
    body.dataset.openclawFoldBody = name;
    wrap.appendChild(body);
    function show(open) {
      body.style.display = open ? 'block' : 'none';
      chevron.innerHTML = open ? ICON.up : ICON.down;
      head.setAttribute('aria-expanded', open ? 'true' : 'false');
      wrap.dataset.open = open ? 'true' : 'false';
      if (open && onOpen && !foldFetched[name]) {
        foldFetched[name] = true;
        onOpen();
      }
    }
    head.onclick = function() { folds[name] = !folds[name]; show(folds[name]); };
    show(folds[name]);
    return { wrap: wrap, body: body };
  }

  // A section's error, under its own title, in its own place.
  function sectionError(name, message) {
    const section = document.getElementById('openclaw-status-section-' + name);
    if (!section) return;
    section.innerHTML = '';
    section.className = 'mb-4';
    const title = SECTIONS.find(function(s) { return s[0] === name; });
    if (title) section.appendChild(sectionHeader(title[1]));
    section.appendChild(errorEl(message));
  }

  // The dialog's sections, drawn at open with their titles: each fills on
  // its own (ELI-163), so the dialog never waits for its slowest source.
  const SECTIONS = __OPENCLAW_SECTIONS__;
  function skeletons(wrap) {
    SECTIONS.forEach(function(s) {
      wrap.appendChild(skeletonSection('openclaw-status-section-' + s[0], s[1]));
    });
  }

  // One list row (ELI-155): a one-line title, a status chip and the time,
  // then at most two lines of preview. A row with `open` is a button that
  // opens its detail.
  function listRow(o) {
    const el = document.createElement(o.open ? 'button' : 'div');
    if (o.open) {
      el.type = 'button';
      el.onclick = o.open;
    }
    el.dataset[o.kind] = '1';
    el.className = 'w-full block text-left py-1.5 px-1.5 -mx-1.5 rounded-lg'
      + (o.open ? ' hover:bg-gray-50 dark:hover:bg-gray-800/60' : '');
    const top = document.createElement('div');
    top.className = 'flex items-center gap-2';
    const titleEl = document.createElement('div');
    titleEl.dataset.openclawTitle = '1';
    titleEl.className = 'text-sm text-gray-700 dark:text-gray-200 flex-1';
    titleEl.textContent = o.title;
    top.appendChild(oneLine(titleEl));
    top.appendChild(statusChip(o.status));
    if (o.time) top.appendChild(o.time);
    el.appendChild(top);
    if (o.preview) {
      const preview = document.createElement('div');
      preview.dataset.openclawPreview = '1';
      preview.className = 'text-xs text-gray-400 dark:text-gray-500 break-words mt-0.5';
      preview.textContent = o.preview;
      el.appendChild(clampLines(preview, 2));
    }
    return el;
  }

  function timeCell(text) {
    const cell = document.createElement('span');
    cell.className = 'text-gray-400 dark:text-gray-500 shrink-0';
    cell.style.fontSize = '10px';
    cell.textContent = text;
    return cell;
  }

  // A run's time: counting up while it runs (the dialog's ticker rewrites a
  // cell marked with its start), its duration once it ended.
  function elapsedCell(startedAt, endedAt, running) {
    const cell = timeCell(elapsedTime(startedAt, endedAt));
    const startMs = toMs(startedAt);
    if (running && !endedAt && startMs != null) cell.dataset.openclawStartedMs = String(startMs);
    return cell;
  }

  function noteEl(text) {
    const el = document.createElement('div');
    el.className = 'text-xs text-gray-400 dark:text-gray-500 mb-1';
    el.textContent = text;
    return el;
  }

  window.__openclawStatus = {
    identity: IDENTITY, isDark: isDark, barColor: barColor, makeBar: makeBar,
    sectionHeader: sectionHeader, errorEl: errorEl,
    skeletonSection: skeletonSection, touchFooter: touchFooter, clockTime: clockTime, controlUiLink: controlUiLink,
    triggerCompact: triggerCompact, elapsedTime: elapsedTime, toMs: toMs,
    openSubagentDrawer: openSubagentDrawer, openAgentDetail: openAgentDetail, openDrawer: openDrawer,
    fillDrawer: fillDrawer, statusChip: statusChip, oneLine: oneLine, clampLines: clampLines,
    countLabel: countLabel, collapsible: collapsible, listRow: listRow, timeCell: timeCell,
    elapsedCell: elapsedCell, noteEl: noteEl, sectionError: sectionError, skeletons: skeletons,
    askAction: askAction,
  };

  const root = document.createElement('div');
  root.id = 'openclaw-status-modal-root';
  root.className = 'fixed inset-0 z-[9999] flex items-center justify-center';
  root.style.background = 'rgba(0,0,0,0.4)';

  const panel = document.createElement('div');
  panel.className = 'bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 '
    + 'rounded-2xl shadow-xl border border-gray-100 dark:border-gray-800 p-5';
  // Inline, not a `w-[380px] max-w-[90vw]` utility class: same reasoning as
  // barColor() below -- an arbitrary-value class OWUI's own Tailwind build
  // never scanned out of its own source can silently carry zero CSS.
  // min() keeps this mobile-first: a narrow viewport wins the 88vw side (a
  // visible margin, not edge-to-edge), a wide one wins the 380px cap.
  panel.style.width = 'min(380px, 88vw)';
  // Up to 20 sub-agents of each kind (ELI-152) outgrow a phone screen: the
  // panel is capped to the screen and its sections scroll between the title
  // bar and the footer, which stay in view (ELI-163).
  panel.style.maxHeight = '88vh';
  panel.style.display = 'flex';
  panel.style.flexDirection = 'column';
  panel.addEventListener('click', function(e) { e.stopPropagation(); });

  // Dismissed: tell the Action, so its open request stops reading for a
  // dialog nobody sees (ELI-163). Best effort; its follow is bounded anyway.
  function closeDialog() {
    if (!root.isConnected) return;
    root.remove();
    document.removeEventListener('keydown', onKey);
    if (IDENTITY.dialogId) askAction({ mode: 'status-closed' }).catch(function() {});
  }

  const header = document.createElement('div');
  header.className = 'flex items-center justify-between mb-3';
  header.style.flexShrink = '0';
  const title = document.createElement('div');
  title.className = 'text-sm font-semibold';
  title.textContent = 'Claw';
  header.appendChild(title);
  const headerEnd = document.createElement('div');
  headerEnd.className = 'flex items-center gap-3';
  if (IDENTITY.controlUiUrl) headerEnd.appendChild(controlUiLink(IDENTITY.controlUiUrl));
  header.appendChild(headerEnd);
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.textContent = '×';
  closeBtn.className = 'text-xl leading-none text-gray-400 hover:text-gray-700 '
    + 'dark:hover:text-gray-200 px-1';
  closeBtn.onclick = closeDialog;
  headerEnd.appendChild(closeBtn);
  panel.appendChild(header);

  const sections = document.createElement('div');
  sections.id = 'openclaw-status-sections';
  sections.style.overflowY = 'auto';
  sections.style.minHeight = '0';
  sections.style.flex = '1 1 auto';
  skeletons(sections);
  panel.appendChild(sections);

  const footer = document.createElement('div');
  footer.id = 'openclaw-status-footer';
  footer.className = 'text-[11px] text-gray-400 dark:text-gray-600 pt-3 '
    + 'border-t border-gray-100 dark:border-gray-800';
  footer.textContent = ' ';
  footer.style.flexShrink = '0';
  panel.appendChild(footer);

  root.appendChild(panel);
  root.addEventListener('click', closeDialog);
  const onKey = function(e) {
    if (e.key === 'Escape') closeDialog();
  };
  document.addEventListener('keydown', onKey);

  // A running sub-agent's elapsed time counts up while the dialog is open
  // (ELI-120): the Subagents fill writes it once, so a child spawned a
  // second before the dialog opened kept saying "1s". The fill marks those
  // cells with data-openclaw-started-ms; one ticker per dialog rewrites
  // them every second and stops itself once the dialog is gone. Reopening
  // replaces the previous dialog, so its ticker is cleared first.
  if (window.__openclawStatusTicker) clearInterval(window.__openclawStatusTicker);
  const ticker = setInterval(function() {
    if (!root.isConnected) {
      clearInterval(ticker);
      return;
    }
    root.querySelectorAll('[data-openclaw-started-ms]').forEach(function(el) {
      el.textContent = elapsedTime(Number(el.dataset.openclawStartedMs), null);
    });
  }, 1000);
  window.__openclawStatusTicker = ticker;

  document.body.appendChild(root);
})();
"""

# Fired only on a post-compact refresh (_run_status(show_loading=False)),
# never on the initial open. _MODAL_COMPACTING_JS (below) replaces
# #openclaw-status-sections' entire contents with its spinner, which
# destroys the three individual section ids each fill function targets --
# this recreates fresh skeletons in their place before the refreshed RPCs
# are fired, without touching the overlay/header/window.__openclawStatus
# (already correctly set up from the original open).
_RESET_SECTIONS_JS = r"""
(function() {
  const wrap = document.getElementById('openclaw-status-sections');
  const S = window.__openclawStatus;
  if (!wrap || !S) return;
  // The refresh's reads are a new dialog's: the page's later requests name it.
  S.identity.dialogId = __OPENCLAW_DIALOG_ID__;
  wrap.innerHTML = '';
  S.skeletons(wrap);
})();
"""

# Static (no data), fired the moment a compact is triggered -- see
# Action._run_compact. Deliberately a distinct, prominent "Compacting..."
# state rather than reusing the generic loading skeleton: compaction is an
# LLM call that can take a while, so the dialog should look like it's
# doing something specific and ongoing, not like a normal fetch that's
# about to finish in a second. Replaces the whole sections wrapper (not a
# specific section) since this is a dialog-wide state, not a per-query one.
_MODAL_COMPACTING_JS = r"""
(function() {
  const wrap = document.getElementById('openclaw-status-sections');
  if (!wrap) return;
  wrap.innerHTML = '';

  const isDark = document.documentElement.classList.contains('dark');

  const box = document.createElement('div');
  box.className = 'flex flex-col items-center justify-center py-6 text-center';

  const spinner = document.createElement('div');
  spinner.className = 'animate-spin rounded-full h-6 w-6 border-2 mb-3';
  spinner.style.borderColor = isDark ? '#4b5563' : '#d1d5db';
  spinner.style.borderTopColor = 'transparent';
  box.appendChild(spinner);

  const title = document.createElement('div');
  title.className = 'text-sm font-medium text-gray-700 dark:text-gray-200';
  title.textContent = 'Compacting…';
  box.appendChild(title);

  const sub = document.createElement('div');
  sub.className = 'text-xs text-gray-400 dark:text-gray-500 mt-1';
  sub.textContent = 'This can take a moment for long conversations.';
  box.appendChild(sub);

  wrap.appendChild(box);
})();
"""

# Dialog-wide error (connection failures, "busy" guard, compact timeout) --
# also replaces the whole sections wrapper rather than one section, same
# reasoning as _MODAL_COMPACTING_JS.
_SECTIONS_ERROR_JS_TEMPLATE = r"""
(function() {
  const MESSAGE = __OPENCLAW_ERROR_MESSAGE__;
  const wrap = document.getElementById('openclaw-status-sections');
  if (!wrap) return;
  wrap.innerHTML = '';
  const S = window.__openclawStatus;
  if (S) {
    wrap.appendChild(S.errorEl(MESSAGE));
  } else {
    wrap.textContent = MESSAGE;
  }
})();
"""

_CONTEXT_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const section = document.getElementById('openclaw-status-section-context');
  const S = window.__openclawStatus;
  if (!section || !S) return;
  if (DATA.error) {
    S.sectionError('context', DATA.error);
    return;
  }
  section.innerHTML = '';
  section.className = 'mb-4';

  const sub = document.createElement('div');
  sub.className = 'text-xs text-gray-500 dark:text-gray-400 mb-3';
  sub.textContent = DATA.provider + (DATA.model ? (' · ' + DATA.model) : '');
  section.appendChild(sub);

  // A compaction the Gateway refused, in its own words (ELI-209).
  function addNotice() {
    if (!DATA.notice) return;
    const notice = S.errorEl(DATA.notice);
    notice.className += ' mt-2';
    section.appendChild(notice);
  }

  if (!DATA.context) {
    const empty = document.createElement('div');
    empty.className = 'text-gray-400 dark:text-gray-500 text-xs';
    empty.textContent = 'No context data available for this session yet.';
    section.appendChild(empty);
    addNotice();
    return;
  }

  const headerRow = document.createElement('div');
  headerRow.className = 'flex items-center justify-between mb-1.5';
  const headerLabel = document.createElement('div');
  headerLabel.className = 'font-semibold tracking-wide uppercase '
    + 'text-gray-400 dark:text-gray-500';
  headerLabel.style.fontSize = '10px';
  headerLabel.textContent = 'Context';
  headerRow.appendChild(headerLabel);
  if (S.identity.chatId && S.identity.messageId && S.identity.sessionId) {
    const compactBtn = document.createElement('button');
    compactBtn.type = 'button';
    compactBtn.textContent = 'Compact';
    compactBtn.className = 'font-medium px-2 py-0.5 rounded-full '
      + 'border border-gray-200 dark:border-gray-700 text-gray-500 dark:text-gray-400 '
      + 'hover:text-gray-800 dark:hover:text-gray-100';
    compactBtn.style.fontSize = '10px';
    compactBtn.onclick = S.triggerCompact;
    headerRow.appendChild(compactBtn);
  }
  section.appendChild(headerRow);

  section.appendChild(S.makeBar(DATA.context.pct));
  const label = document.createElement('div');
  label.className = 'text-xs text-gray-500 dark:text-gray-400 mt-1.5';
  label.textContent = DATA.context.usedTokens + ' / ' + DATA.context.totalTokens
    + ' tokens · ' + DATA.context.pct + '%';
  section.appendChild(label);
  addNotice();

  if (DATA.goal) {
    const goalWrap = document.createElement('div');
    goalWrap.className = 'mt-3 pt-3 border-t border-gray-100 dark:border-gray-800';
    goalWrap.appendChild(S.sectionHeader('Goal'));
    const line = document.createElement('div');
    line.className = 'text-sm text-gray-700 dark:text-gray-200';
    line.textContent = DATA.goal.line;
    goalWrap.appendChild(line);
    if (DATA.goal.pct !== null) {
      const barWrap = document.createElement('div');
      barWrap.className = 'mt-1.5';
      barWrap.appendChild(S.makeBar(DATA.goal.pct));
      goalWrap.appendChild(barWrap);
    }
    section.appendChild(goalWrap);
  }

  S.touchFooter(DATA.fetchedAt, DATA.source);
})();
"""

# Always gets its own section when we have a real provider to report on --
# not gated on windows.length > 0. The gateway's usage.status can
# transiently report zero windows for the active provider while a run is
# in flight (its rate-limit cache is most likely refreshed from that run's
# own API response headers, so there's a real gap while one is active) --
# silently omitting the section in that case looked exactly like a missing
# feature rather than a temporary data gap. Showing an explicit note instead turns that into an
# understood, expected state.
_LIMITS_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const section = document.getElementById('openclaw-status-section-limits');
  const S = window.__openclawStatus;
  if (!section || !S) return;
  section.innerHTML = '';

  section.className = 'mb-4';
  section.appendChild(S.sectionHeader('Rate limits'));
  if (DATA.error) {
    section.appendChild(S.errorEl(DATA.error));
    return;
  }

  if (!DATA.provider || DATA.provider === '?') {
    section.appendChild(S.noteEl('This session has no provider yet.'));
    return;
  }

  if (DATA.windows.length === 0) {
    const note = document.createElement('div');
    note.className = 'text-xs text-gray-400 dark:text-gray-500';
    note.textContent = 'No rate-limit data available right now'
      + (DATA.sessionActive ? ' (a response is in progress).' : '.');
    section.appendChild(note);
  }
  DATA.windows.forEach(function(w, i) {
    const row = document.createElement('div');
    row.className = i > 0 ? 'mt-3' : '';
    const top = document.createElement('div');
    top.className = 'flex items-center justify-between text-xs '
      + 'text-gray-600 dark:text-gray-300 mb-1';
    const labelEl = document.createElement('span');
    labelEl.textContent = w.label;
    const pctEl = document.createElement('span');
    pctEl.textContent = Math.round(w.usedPercent) + '% used';
    top.appendChild(labelEl);
    top.appendChild(pctEl);
    row.appendChild(top);
    row.appendChild(S.makeBar(w.usedPercent));
    if (w.resetIn) {
      const reset = document.createElement('div');
      reset.className = 'text-[11px] text-gray-400 dark:text-gray-500 mt-1';
      let text = 'resets in ' + w.resetIn;
      if (w.resetAtMs) {
        // Formatted in the browser's own local timezone, not computed
        // server-side -- the gateway/OWUI container's system timezone and
        // the person actually looking at this dialog aren't guaranteed to
        // be the same, so doing this client-side is the only way to get
        // it right regardless of where either runs.
        const abs = new Date(w.resetAtMs).toLocaleTimeString([], {
          hour: '2-digit', minute: '2-digit'
        });
        text += ' · ' + abs;
      }
      reset.textContent = text;
      row.appendChild(reset);
    }
    section.appendChild(row);
  });

  S.touchFooter(DATA.fetchedAt, DATA.source);
})();
"""

# The Subagents section (ELI-152/155/163): a fold titled with its count, open
# at its first fill when a child runs. A fold opened for the first time with
# its rows still `pending` (the open read no transcripts for a section
# nobody had opened) asks the Action for them (mode "subagent-rows"). Each
# row opens the per-subagent drawer (S.openSubagentDrawer) with the fields it
# already knows, so the drawer paints its header before any RPC resolves.
_SUBAGENTS_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const S = window.__openclawStatus;
  const section = document.getElementById('openclaw-status-section-subagents');
  if (!section || !S) return;
  if (DATA.error) {
    S.sectionError('subagents', DATA.error);
    return;
  }
  section.innerHTML = '';
  section.className = 'mb-4';
  const tasks = DATA.tasks || [];
  const live = tasks.some(function(t) { return t.status === 'running' || t.status === 'queued'; });
  // A failed ask (a dropped phone connection, a proxy's error page) says so
  // in the fold with a Retry; a good one is answered by the Action's fill.
  function loadRows() {
    S.askAction({ mode: 'subagent-rows' }).then(function(r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
    }).catch(function(err) {
      fold.body.innerHTML = '';
      fold.body.appendChild(S.errorEl('Could not load the sub-agents: ' + ((err && err.message) || err)));
      const retry = document.createElement('button');
      retry.type = 'button';
      retry.className = 'mt-1 text-xs underline text-gray-500 dark:text-gray-400';
      retry.textContent = 'Retry';
      retry.onclick = function() {
        fold.body.innerHTML = '';
        fold.body.appendChild(S.skeletonSection('openclaw-status-subagents-loading'));
        loadRows();
      };
      fold.body.appendChild(retry);
    });
  }
  const fold = S.collapsible('subagents', S.countLabel('Subagents', tasks.length, DATA.total || 0), live,
    DATA.pending ? loadRows : null);
  section.appendChild(fold.wrap);
  if (!tasks.length) {
    fold.body.appendChild(S.noteEl('No sub-agents in this chat.'));
  } else if (DATA.pending) {
    fold.body.appendChild(S.skeletonSection('openclaw-status-subagents-loading'));
  }
  if (!DATA.pending) tasks.forEach(function(t) {
    const running = t.status === 'running';
    fold.body.appendChild(S.listRow({
      kind: 'openclawRow', title: t.title || t.id, status: t.status,
      time: S.elapsedCell(t.startedAt, t.endedAt, running),
      preview: running ? t.progressSummary : (t.terminalSummary || t.error),
      open: function() { S.openSubagentDrawer(t); },
    }));
  });
  S.touchFooter(DATA.fetchedAt, DATA.source);
})();
"""

# Claude Code's in-process Agent calls (ELI-152): not Gateway sessions, so
# no duration, only what the chat's tool cards tell; a tap shows its task and
# result (ELI-155). Read from Open WebUI's copy of the chat alone, so this
# section fills even when the Gateway does not answer.
_AGENTS_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const S = window.__openclawStatus;
  const section = document.getElementById('openclaw-status-section-agents');
  if (!section || !S) return;
  if (DATA.error) {
    S.sectionError('agents', DATA.error);
    return;
  }
  section.innerHTML = '';
  section.className = 'mb-4';
  const agents = DATA.agents || [];
  const live = agents.some(function(a) { return a.state === 'running'; });
  const fold = S.collapsible('agents', S.countLabel('In-process agents', agents.length, DATA.total || 0), live);
  section.appendChild(fold.wrap);
  // A long chat is read from its recent messages only (DATA.recent of them).
  const where = DATA.recent ? 'in this chat\'s last ' + DATA.recent + ' messages' : 'in this chat';
  fold.body.appendChild(S.noteEl(agents.length
    ? 'Claude Code Agent calls ' + where + ', as their tool cards show them.'
    : 'No Claude Code Agent calls ' + where + '.'));
  agents.forEach(function(a) {
    // When its reply started, on the reader's clock.
    const started = S.toMs(a.startedAt);
    let when = null;
    if (started != null) {
      when = S.timeCell(new Date(started).toLocaleString([], {
        month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'
      }));
      when.title = 'Started';
    }
    fold.body.appendChild(S.listRow({
      kind: 'openclawAgentRow', title: a.title, status: a.state, time: when, preview: a.result,
      open: function() { S.openAgentDetail(a); },
    }));
  });
})();
"""

# The Background section (ELI-163): this chat's background commands, media
# jobs, automation runs and background agents, and the automations bound to
# it. A fold like Subagents. A source this Gateway
# lacks says so in a note; one that failed says so too, and the rest shows.
_BACKGROUND_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const S = window.__openclawStatus;
  const section = document.getElementById('openclaw-status-section-background');
  if (!section || !S) return;
  if (DATA.error) {
    S.sectionError('background', DATA.error);
    return;
  }
  section.innerHTML = '';
  section.className = 'mb-4';
  const rows = DATA.rows || [];
  const isLive = function(r) { return r.status === 'running' || r.status === 'queued'; };
  const live = rows.some(isLive);
  const fold = S.collapsible('background', S.countLabel('Background', rows.length, DATA.total || 0), live);
  section.appendChild(fold.wrap);

  // The row's second line: what it is, then what it says. The title keeps
  // the whole first line.
  function line(kind, detail) {
    return [kind, detail].filter(Boolean).join(' · ') || null;
  }
  // An automation: its error when it failed, else when it runs next.
  function automationDetail(r) {
    if (r.status === 'failed') {
      return (r.failedInARow > 1 ? 'failed ' + r.failedInARow + ' times in a row: ' : '') + (r.error || '');
    }
    if (r.status === 'running' || !r.nextRunAtMs) return null;
    return 'next run ' + new Date(r.nextRunAtMs).toLocaleString([], {
      month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'
    });
  }
  function row(r) {
    if (r.job) {
      return S.listRow({ kind: 'openclawBgRow', title: r.title, status: r.status,
                         time: r.status === 'running' ? S.elapsedCell(r.startedAt, null, true) : null,
                         preview: line(r.kind, automationDetail(r)) });
    }
    return S.listRow({
      kind: 'openclawBgRow', title: r.title, status: r.status,
      time: S.elapsedCell(r.startedAt, r.endedAt, isLive(r)), preview: line(r.kind, r.preview),
      open: r.agent ? function() { S.openAgentDetail(r.agent); } : null,
    });
  }

  (DATA.errors || []).forEach(function(e) { fold.body.appendChild(S.errorEl(e)); });
  if (!DATA.tasksAvailable) {
    fold.body.appendChild(S.noteEl('Background commands and media jobs are not available on this Gateway.'));
  }
  if (!rows.length) fold.body.appendChild(S.noteEl('Nothing in the background for this chat.'));
  rows.forEach(function(r) { fold.body.appendChild(row(r)); });
  S.touchFooter(DATA.fetchedAt, DATA.source);
})();
"""

# One section's error in its place (S.sectionError): a failed source
# leaves every other section as it is.
_SECTION_ERROR_JS_TEMPLATE = r"""
(function() {
  const S = window.__openclawStatus;
  if (S && S.sectionError) S.sectionError(__OPENCLAW_SECTION__, __OPENCLAW_ERROR_MESSAGE__);
})();
"""


# The drawer opened from here rather than by a row tap: an old sub-agent
# message's toolbar click. `S.openDrawer` (_MODAL_OPEN_JS_TEMPLATE) builds it;
# `server` because this request fills it next.
_DRAWER_OPEN_JS_TEMPLATE = r"""
(function() {
  const S = window.__openclawStatus;
  if (S && S.openDrawer) S.openDrawer(Object.assign({ kind: 'child', server: true }, __OPENCLAW_TASK__));
})();
"""

# Whole-drawer error (task not found, connect failure): the run's place
# says what went wrong. `KEY`: only the drawer showing that sub-agent.
_DRAWER_ERROR_JS_TEMPLATE = r"""
(function() {
  const MESSAGE = __OPENCLAW_ERROR_MESSAGE__;
  const KEY = __OPENCLAW_TASK_KEY__;
  const S = window.__openclawStatus;
  const root = document.getElementById('openclaw-drawer-root');
  const stream = document.getElementById('openclaw-drawer-stream');
  if (!stream || (KEY && (!root || root.dataset.taskId !== KEY))) return;
  stream.innerHTML = '';
  stream.appendChild(S ? S.errorEl(MESSAGE) : document.createTextNode(MESSAGE));
})();
"""

# One read of the sub-agent: its header and its run (S.fillDrawer). A fill
# for a drawer since closed, or another sub-agent's, is dropped there.
_DRAWER_FILL_JS_TEMPLATE = r"""
(function() {
  const DATA = __OPENCLAW_STATUS_DATA__;
  const S = window.__openclawStatus;
  if (S && S.fillDrawer && document.getElementById('openclaw-drawer-stream')) S.fillDrawer(DATA);
})();
"""


def _json_for_js(data) -> str:
    """Never string-interpolate individual fields directly into JS source.
    json.dumps always produces a syntactically valid JS expression, so this
    is the one substitution point that needs to be safe against whatever
    the gateway's numbers/text happen to contain (e.g. a goal description
    with quotes or backslashes).

    json.dumps does NOT escape "<" by default, so a value containing a
    literal "</script>" would terminate an enclosing <script> tag early if
    this code ever ends up placed into HTML rather than passed straight to
    a JS execution call -- escaping "<" to the equivalent \\u003c unicode
    escape is a no-op for JSON.parse but closes that off regardless of how
    the execute event happens to deliver this string."""
    return json.dumps(data).replace("<", "\\u003c")


def _render_modal_open_js(identity: dict) -> str:
    return (_MODAL_OPEN_JS_TEMPLATE.replace("__OPENCLAW_IDENTITY__", _json_for_js(identity))
            .replace("__OPENCLAW_SECTIONS__", _json_for_js([list(s) for s in _DIALOG_SECTIONS])))


def _render_sections_error_js(message: str) -> str:
    return _SECTIONS_ERROR_JS_TEMPLATE.replace("__OPENCLAW_ERROR_MESSAGE__", _json_for_js(message))


def _render_context_fill_js(data: dict) -> str:
    return _CONTEXT_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


def _render_limits_fill_js(data: dict) -> str:
    return _LIMITS_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


def _limits_windows_for(usage, provider) -> list:
    """The active provider's rate-limit windows from a `usage.status`-shaped
    payload, reshaped for the Rate Limits section. Windows with no known
    usedPercent are dropped."""
    windows_data = []
    for p in (usage or {}).get("providers", []):
        if p.get("provider") != provider:
            continue
        for w in p.get("windows") or []:
            used = w.get("usedPercent")
            if used is None:
                continue
            windows_data.append({
                "label": w.get("label"),
                "usedPercent": used,
                "resetIn": _relative_time(w.get("resetAt")),
                # Raw ms timestamp, not a server-formatted clock
                # time -- the absolute time is rendered client-side
                # so it shows in the browser's own local timezone
                # rather than whatever timezone this container is in.
                "resetAtMs": w.get("resetAt"),
            })
        break
    return windows_data


async def _claude_cli_usage_windows(conn) -> list:
    """Fallback for Claude-CLI-only setups. Since OpenClaw 2026.9.1
    (openclaw#129052) `usage.status` never resolves the claude-cli login, so
    with no other Anthropic credential it has no `anthropic` entry at all.
    The companion gateway plugin (gateway-plugins/claude-cli-usage) serves
    the same windows read-only over `claudeCliUsage.status`. A gateway
    without that plugin answers "unknown method"; that is logged and the
    section keeps its empty-windows note."""
    try:
        snapshot = await conn.send_request("claudeCliUsage.status", {}, timeout=10)
    except Exception as ex:
        pipe_log(f"[status-action] claudeCliUsage.status unavailable: {ex}")
        return []
    if (snapshot or {}).get("error"):
        pipe_log(f"[status-action] claudeCliUsage.status: {snapshot['error']}")
    return _limits_windows_for({"providers": [snapshot or {}]}, "anthropic")


# A child session's run status, in the words the Subagents section and drawer
# colour and print (they were written against the removed Tasks API).
_SUBAGENT_STATUS_WORDS = {"done": "completed", "killed": "cancelled", "timeout": "timed_out"}
_RUNTIME_CONTEXT_MARKER_RE = re.compile(r"^<<<(?:BEGIN|END)_OPENCLAW_INTERNAL_CONTEXT>>>$", re.M)
# The header on a line of its own; 2026.10 also names it inside the context sentence.
_SUBAGENT_TASK_HEADER_RE = re.compile(r"^\[Subagent Task\][ \t]*$", re.M)


def _subagent_status(status):
    return _SUBAGENT_STATUS_WORDS.get(status, status)


def _subagent_task_text(text):
    """The task out of a spawn's first message, which the Gateway wraps as
    "[Subagent Context] ... [Subagent Task] <task> Begin. Execute ...".
    2026.10 adds internal-context marker lines around the wrapper. None if
    the text is not a spawn message."""
    parts = _SUBAGENT_TASK_HEADER_RE.split(text) if isinstance(text, str) else []
    if len(parts) < 2:
        return None
    task = _RUNTIME_CONTEXT_MARKER_RE.sub("", parts[-1])
    task = task.split("Begin. Execute the assigned task", 1)[0].strip()
    return task or None


# A spawn's first message in any whitespace form: lastMessagePreview flattens
# it to one line, so the header-on-its-own-line test above does not apply.
_SUBAGENT_SPAWN_RE = re.compile(
    r"^\s*(?:<<<BEGIN_OPENCLAW_INTERNAL_CONTEXT>>>\s*)?\[Subagent Context\].*\[Subagent Task\]", re.S)


def _is_spawn_message(text):
    return isinstance(text, str) and bool(_SUBAGENT_SPAWN_RE.match(text))


def _subagent_task_texts(previews_resp):
    """{child key: task text} from a sessions.preview answer. The preview
    holds a session's newest items, so a long-running child's first message
    may be gone; that child has no entry."""
    out = {}
    for p in (previews_resp or {}).get("previews") or []:
        for item in p.get("items") or []:
            text = _subagent_task_text(item.get("text")) if item.get("role") == "user" else None
            if text and p.get("key"):
                out[p["key"]] = text
                break
    return out


def _subagent_row(row, task_text=None, latest=None):
    """One Subagents row out of a child session row. The title is the spawn
    label, else the task's first sentence, else the key; the whole task is
    the drawer's to show (ELI-155). The preview is the row's own last
    message when the list read carried it, else `latest` (sessions.preview)."""
    status = _subagent_status(row.get("status"))
    if status is None and row.get("endedAt"):
        status = "ended"    # a visible spawn's session carries no run status
    live = status in _LIVE_SUBAGENT_STATUSES
    preview = row.get("lastMessagePreview") or latest
    if _is_spawn_message(preview):
        # Just spawned: the newest message is still the task (ELI-119).
        preview = None
    return {
        "id": row["key"],
        "title": (row.get("label") or "").strip() or (_short_title(task_text) if task_text else row["key"]),
        "task": task_text,
        "status": status,
        "progressSummary": preview if live else None,
        "terminalSummary": preview if not live else None,
        "error": row.get("lastRunError"),
        "childSessionKey": row["key"],
        "startedAt": row.get("startedAt"),
        # An ended child's duration stops at its last update when the
        # Gateway kept no end time.
        "endedAt": row.get("endedAt") or (None if live else row.get("updatedAt")),
    }


_LIVE_SUBAGENT_STATUSES = ("running", "queued")
# How many sub-agents of each kind the section lists, newest first (ELI-152).
_SUBAGENT_LIST_CAP = 20


def _is_child_of(row, parent_key):
    """A session the parent spawned. `sessions.list {spawnedBy}` keeps an
    ended child for 30 minutes only, so the dialog's open reads the whole
    list and picks the children itself (ELI-152)."""
    return row.get("key") not in (None, parent_key) and parent_key in (
        row.get("spawnedBy"), row.get("parentSessionKey"))


def _subagent_final(row):
    """A child row that will not change: its run ended."""
    if not row:
        return False
    status = _subagent_status(row.get("status"))
    return status not in _LIVE_SUBAGENT_STATUSES and bool(status or row.get("endedAt"))


async def _lookup_child(conn, key):
    """One child session's row, by its key."""
    try:
        resp = await conn.send_request("sessions.list", dict(search=key.rsplit(":", 1)[-1], limit=10), timeout=5)
    except Exception as ex:
        pipe_log(f"[status-action] sessions.list (child {key}) failed: {ex}")
        return None
    return next((r for r in (resp or {}).get("sessions") or [] if r.get("key") == key), None)


async def _resolved(value):
    return value


def _subagent_started(row):
    return row.get("startedAt") or row.get("createdAt") or row.get("updatedAt") or 0


# How much of an Agent call's task and result its detail shows.
_AGENT_TEXT_MAX = 4000


def _owui_branch(chat):
    """The messages of a stored chat's current branch, oldest first."""
    history = (chat or {}).get("history") or {}
    messages = history.get("messages") or {}
    branch, seen, mid = [], set(), history.get("currentId")
    while mid and mid not in seen and mid in messages:
        seen.add(mid)
        branch.append(messages[mid])
        mid = messages[mid].get("parentId")
    return branch[::-1]


def _card_text(item):
    out = (item or {}).get("output")
    if isinstance(out, list):
        return "".join(p.get("text") or "" for p in out if isinstance(p, dict))
    return out if isinstance(out, str) else ""


def _agent_call_rows(chat):
    """The chat's in-process Agent calls (Claude Code sub-agents), newest
    first, out of its replies' own tool cards (ELI-152). The Gateway never
    lists them as child sessions, so a card is all there is: the call's
    description, its reply's start time, and a state its result tells.
    "launched" is a background agent whose report comes later on its own."""
    rows = []
    for msg in _owui_branch(chat):
        output = msg.get("output") or []
        results = {o.get("call_id"): o for o in output if o.get("type") == "function_call_output"}
        for item in output:
            name = item.get("name") or ""
            if item.get("type") != "function_call" or not _is_agent_tool(name.replace(TOOL_ERROR_MARK, "")):
                continue
            try:
                args = json.loads(item.get("arguments") or "{}")
            except ValueError:
                args = {}
            args = args if isinstance(args, dict) else {}
            result = results.get(item.get("call_id") or item.get("id"))
            text = _card_text(result).strip()
            if TOOL_ERROR_MARK in name:
                state = "failed"
            elif result is None:
                state = "cut off" if msg.get("done") else "running"
            elif text.startswith(TOOL_NO_RESULT_NOTE):
                state = "cut off"
            elif text.startswith(_AGENT_LAUNCHED_PREFIX):
                state = "launched"
            else:
                state = "returned"
            ts = msg.get("timestamp")
            prompt = args.get("prompt")
            rows.append({
                "id": item.get("call_id") or item.get("id"),
                "title": str(args.get("description") or args.get("subagent_type") or _AGENT_TOOL_NAME),
                "subagentType": args.get("subagent_type"),
                "state": state,
                "startedAt": int(ts * 1000) if isinstance(ts, (int, float)) else None,
                # What its detail shows (ELI-155), capped like a card's text.
                "task": prompt[:_AGENT_TEXT_MAX] if isinstance(prompt, str) and prompt.strip() else None,
                "result": text[:_AGENT_TEXT_MAX] if result is not None and text else None,
                # A background agent holds its reply open until its report is in.
                "replyDone": bool(msg.get("done")),
            })
    return rows[::-1]


# How many of the chat's newest messages (its current branch) In-process
# agents and Background read: their time must not grow with the chat.
_RECENT_MESSAGES = 40


async def _recent_branch(current_id, links, read_rows, read_blob_message, limit=_RECENT_MESSAGES,
                         chat_id=None):
    """The last `limit` messages of a chat's current branch, chat-shaped
    ({"history": {"currentId", "messages"}, "truncated"}) for the section
    builders. `links` maps each message that has a row to its parent;
    `read_rows(ids)` reads those messages ({id: message}) in one go;
    `read_blob_message(id)` reads one message the chat's own copy holds but
    no row does yet (Open WebUI writes some straight into the chat). A reply
    of `chat_id` that this process's Pipe is streaming lists what it shows
    so far."""
    order, blob, seen, mid = [], {}, set(), current_id
    while mid and mid not in seen and len(order) < limit:
        seen.add(mid)
        if mid in links:
            parent = links[mid]
        else:
            msg = await read_blob_message(mid)
            if not isinstance(msg, dict):
                break
            blob[mid] = msg
            parent = msg.get("parentId")
        order.append(mid)
        mid = parent
    with_rows = [m for m in order if m not in blob]
    rows = await read_rows(with_rows) if with_rows else {}
    # Open WebUI saves a reply's calls only when it ends, in its row and in
    # the chat alike (ELI-186): a running reply's are with the Pipe.
    for m in order:
        msg = blob.get(m) or rows.get(m)
        if isinstance(msg, dict) and msg.get("role") == "assistant" and not msg.get("done"):
            live = _live_reply_output(chat_id, m)
            if live is not None:
                blob[m] = {**msg, "output": live}
    messages = {m: {**(blob.get(m) or rows.get(m)), "id": m} for m in order if blob.get(m) or rows.get(m)}
    return {"history": {"currentId": current_id, "messages": messages},
            "truncated": bool(mid) and mid not in seen}


async def _recent_of_chat(chat, limit=_RECENT_MESSAGES, chat_id=None):
    """`_recent_branch` of a chat already read whole."""
    if not isinstance(chat, dict):
        return chat
    history = chat.get("history") or {}
    msgs = history.get("messages") or {}

    async def read_rows(ids):
        return {i: msgs[i] for i in ids if isinstance(msgs.get(i), dict)}

    async def no_blob(_mid):
        return None
    links = {k: v.get("parentId") for k, v in msgs.items() if isinstance(v, dict)}
    return {**chat, **await _recent_branch(history.get("currentId"), links, read_rows, no_blob, limit, chat_id)}


async def _load_owui_recent(chat_id, user_id, limit=_RECENT_MESSAGES):
    """The chat's last `limit` messages when it is this user's, read from
    Open WebUI's message rows: the chat row's head, every row's parent link
    (two short columns), then those messages' rows. Building the whole chat
    costs about 14x its JSON in Python (ELI-115) and grows with the chat.
    None on any failure (the sections then list no Agent calls); the whole
    chat, cut the same way, where the rows cannot be read at all."""
    try:
        from sqlalchemy import select
        from open_webui.internal.db import get_async_db_context
        from open_webui.models.chats import Chat
        from open_webui.models.chat_messages import ChatMessage
    except Exception:
        return await _recent_of_chat(await _load_owui_chat(chat_id, user_id), limit, chat_id)
    prefix = f"{chat_id}-"
    try:
        async with get_async_db_context() as db:
            head = (await db.execute(select(Chat.user_id, Chat.current_message_id)
                                     .where(Chat.id == chat_id))).first()
            if head is None or head[0] != user_id:
                return None
            current = head[1] or (await db.execute(
                select(Chat.chat[("history", "currentId")]).where(Chat.id == chat_id))).scalar()
            links = {rid[len(prefix):]: parent for rid, parent in (await db.execute(
                select(ChatMessage.id, ChatMessage.parent_id).where(ChatMessage.chat_id == chat_id))).all()
                if isinstance(rid, str) and rid.startswith(prefix)}

            async def read_rows(ids):
                result = await db.execute(
                    select(ChatMessage.id, ChatMessage.parent_id, ChatMessage.role, ChatMessage.output,
                           ChatMessage.done, ChatMessage.created_at)
                    .where(ChatMessage.id.in_([prefix + i for i in ids])))
                return {rid[len(prefix):]: {"parentId": parent, "role": role, "output": output or [],
                                            "done": done, "timestamp": created}
                        for rid, parent, role, output, done, created in result.all()}

            async def read_blob_message(mid):
                return (await db.execute(select(Chat.chat[("history", "messages", mid)])
                                         .where(Chat.id == chat_id))).scalar()
            return await _recent_branch(current, links, read_rows, read_blob_message, limit, chat_id)
    except Exception as ex:
        pipe_log(f"[status-action] could not read the chat's recent messages: {ex}")
        return None


async def _owui_chat_title(chat_id, user_id):
    """The chat's title when it is this user's: one row, two columns."""
    try:
        from sqlalchemy import select
        from open_webui.internal.db import get_async_db_context
        from open_webui.models.chats import Chat
    except Exception:
        chat = await _load_owui_chat(chat_id, user_id)
        return chat.get("title") if isinstance(chat, dict) else None
    try:
        async with get_async_db_context() as db:
            row = (await db.execute(select(Chat.title, Chat.user_id).where(Chat.id == chat_id))).first()
    except Exception as ex:
        pipe_log(f"[status-action] could not read the chat's title: {ex}")
        return None
    return row[0] if row is not None and row[1] == user_id else None


async def _load_owui_chat(chat_id, user_id):
    """The chat as Open WebUI stores it, when it is this user's; None outside
    Open WebUI or on any failure (the section then lists no Agent calls)."""
    try:
        from open_webui.models.chats import Chats
        row = Chats.get_chat_by_id(chat_id)
        if asyncio.iscoroutine(row):
            row = await row
    except Exception as ex:
        pipe_log(f"[status-action] could not read the chat for its Agent calls: {ex}")
        return None
    if row is None or getattr(row, "user_id", None) != user_id:
        return None
    return getattr(row, "chat", None)


def _render_subagents_fill_js(data: dict) -> str:
    return _SUBAGENTS_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


def _render_background_fill_js(data: dict) -> str:
    return _BACKGROUND_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


def _render_agents_fill_js(data: dict) -> str:
    return _AGENTS_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


def _render_section_error_js(section: str, message: str) -> str:
    """One section's error in its place, under its own title; the others
    keep what they show."""
    return (_SECTION_ERROR_JS_TEMPLATE.replace("__OPENCLAW_SECTION__", _json_for_js(section))
            .replace("__OPENCLAW_ERROR_MESSAGE__", _json_for_js(message)))


# The dialog's sections in their order: id suffix and title. The page draws
# them all at open (_MODAL_OPEN_JS_TEMPLATE), each fills on its own.
_DIALOG_SECTIONS = (
    ("context", "Context"),
    ("limits", "Rate limits"),
    ("background", "Background"),
    ("subagents", "Subagents"),
    ("agents", "In-process agents"),
)
# The sections the Gateway fills; In-process agents reads Open WebUI only.
_GATEWAY_SECTIONS = ("context", "limits", "background", "subagents")


# ---------------------------------------------------------------------------
# Open Status dialogs (ELI-163), by the id the open hands the page: whose it
# is, its session, the Subagents rows a folded section has yet to detail,
# and a `closed` flag the page sets when it is dismissed, so nothing is read
# for a dialog nobody looks at. In this process only; an entry lasts the
# dialog's follow bound at most.

_open_dialogs: dict = {}


def _dialog_open(user_id: str, session_key: str) -> tuple:
    now = time.time()
    for k in [k for k, d in _open_dialogs.items() if d["expires"] < now]:
        _open_dialogs.pop(k, None)
    dialog_id = uuid.uuid4().hex
    dialog = {"user": user_id, "session": session_key, "closed": asyncio.Event(),
              "expires": now + _DIALOG_FOLLOW_MAX_S, "rows": [], "total": 0}
    _open_dialogs[dialog_id] = dialog
    return dialog_id, dialog


def _dialog_of(body: dict, user_id: str):
    """The caller's own open dialog the request names, else None."""
    dialog = _open_dialogs.get(body.get("dialogId") or "")
    return dialog if dialog and dialog["user"] == user_id else None


def _subagent_previews(previews_resp) -> tuple:
    """({key: task text}, {key: newest message}) from a sessions.preview
    answer: the spawn's task when the preview still reaches it, and what the
    child said last (none while its newest message is still the spawn)."""
    latest = {}
    for p in (previews_resp or {}).get("previews") or []:
        texts = [i.get("text") for i in p.get("items") or [] if isinstance(i.get("text"), str) and i["text"].strip()]
        if p.get("key") and texts and not _subagent_task_text(texts[-1]):
            latest[p["key"]] = texts[-1].strip()
    return _subagent_task_texts(previews_resp), latest


async def _read_automations(conn) -> "list | None":
    """Every enabled automation, or None on a Gateway without `cron.list`."""
    try:
        resp = await conn.send_request("cron.list", dict(limit=200), timeout=5)
    except Exception as ex:
        if _is_unknown_method(ex):
            return None
        raise
    return (resp or {}).get("jobs") or []


# ---------------------------------------------------------------------------
# The Background section (ELI-163): what runs for this chat outside a reply.
# Read once when the dialog opens, never polled.

# The Gateway's task kinds the section lists, as the row's kind label. Its
# other kinds are listed elsewhere (a sub-agent or ACP child is the
# Subagents section's) or are its own upkeep (context maintenance).
_BACKGROUND_KINDS = {
    "exec": "Command",
    "image_generation": "Image",
    "music_generation": "Music",
    "video_generation": "Video",
    "automation_run": "Automation",
}
# How many finished items of this chat the section keeps, newest first; a
# running one is always listed.
_BACKGROUND_FINISHED_CAP = 5
_LIVE_TASK_STATUSES = ("running", "queued")
# The exec tool's answer for a command left running: "Command still running
# (session good-lagoon, pid 2816)". The session is the task's sourceId.
_EXEC_SESSION_RE = re.compile(r"\(session ([\w.-]+)")


def _is_unknown_method(ex: Exception) -> bool:
    return "unknown method" in str(ex).lower()


async def _read_background_tasks(conn, session_key: str) -> "list | None":
    """The adapter between the section and the Gateway's background work for
    one session, as task rows. OpenClaw 2026.9 lists it with `tasks.list`;
    2026.10 removed that method, and a session's background commands are
    `sessions.processes.list` (media jobs have no per-session list there). A
    Gateway with neither gives None: the section then says it is not
    available here instead of failing."""
    try:
        resp = await conn.send_request("tasks.list", dict(sessionKey=session_key, limit=100), timeout=5)
        return (resp or {}).get("tasks") or []
    except Exception as ex:
        if not _is_unknown_method(ex):
            raise
    try:
        resp = await conn.send_request("sessions.processes.list", dict(key=session_key), timeout=5)
    except Exception as ex:
        if _is_unknown_method(ex):
            return None
        raise
    return [_process_task(p, session_key) for p in (resp or {}).get("processes") or []]


# A 2026.10 process's status as a task's.
_PROCESS_STATUSES = {"running": "running", "completed": "completed", "failed": "failed", "killed": "cancelled"}


def _process_task(process: dict, session_key: str) -> dict:
    """One `sessions.processes.list` row as the task row `_task_row` reads: an
    exec task whose sourceId is the process (the session its tool card
    names), titled by the Gateway's short name until a card gives the
    command, and a finished one's last line of output as its summary."""
    lines = [ln for ln in (process.get("tail") or "").splitlines() if ln.strip()]
    return {
        "id": process.get("processId"), "kind": "exec", "sourceId": process.get("processId"),
        "sessionKey": session_key, "title": process.get("name") or "",
        "status": _PROCESS_STATUSES.get(process.get("status"), process.get("status")),
        "startedAt": process.get("startedAt"), "endedAt": process.get("endedAt"),
        "terminalSummary": lines[-1][:200] if lines else None,
    }


def _exec_commands(chat) -> dict:
    """{exec session id: command} from the chat's own exec tool cards. The
    Gateway's task for a background command is titled "CLI command"; its
    sourceId is the session the card's result names."""
    out = {}
    for msg in _owui_branch(chat):
        output = msg.get("output") or []
        calls = {o.get("id"): o for o in output if o.get("type") == "function_call"}
        for o in output:
            if o.get("type") != "function_call_output":
                continue
            call = calls.get(o.get("call_id")) or {}
            if (call.get("name") or "").replace(TOOL_ERROR_MARK, "").strip() != "exec":
                continue
            m = _EXEC_SESSION_RE.search(_card_text(o))
            try:
                args = json.loads(call.get("arguments") or "{}")
            except ValueError:
                args = {}
            command = args.get("command") if isinstance(args, dict) else None
            if m and isinstance(command, str) and command.strip():
                out[m.group(1)] = command.strip()
    return out


def _belongs_to(task: dict, session_key: str) -> bool:
    """A task this chat started (its requester), or one run in it (an
    automation run's target session)."""
    return session_key in (task.get("sessionKey"), task.get("childSessionKey"), task.get("ownerKey"))


def _task_row(task: dict, commands: dict) -> dict:
    kind = task.get("kind") or ""
    title = (task.get("title") or "").strip()
    if kind == "exec":
        # 2026.9 titles every one "CLI command"; a 2026.10 process has a
        # short name ("make build"). The card's whole command wins.
        own = "" if title == "CLI command" else title
        title = commands.get(task.get("sourceId") or "") or own or "Shell command"
    status = task.get("status")
    live = status in _LIVE_TASK_STATUSES
    return {
        "id": task.get("id") or task.get("taskId"),
        "kind": _BACKGROUND_KINDS.get(kind, "Task"),
        "title": title or _BACKGROUND_KINDS.get(kind, "Task"),
        "status": status,
        "startedAt": task.get("startedAt") or task.get("createdAt"),
        "endedAt": None if live else (task.get("endedAt") or task.get("updatedAt")),
        # A running command's progress is always "Command running": its chip says so.
        "preview": (None if live and kind == "exec" else task.get("progressSummary") if live
                    else (task.get("error") or task.get("terminalSummary"))),
    }


def _job_bound_to(job: dict, session_key: str) -> bool:
    """An automation that runs in this chat: `session:<key>`, or "current"
    with the session it was made in."""
    target = job.get("sessionTarget") or ""
    return target == f"session:{session_key}" or (target == "current" and job.get("sessionKey") == session_key)


def _job_status(job: dict) -> str:
    state = job.get("state") or {}
    if state.get("runningAtMs"):
        return "running"
    last = state.get("lastRunStatus") or state.get("lastStatus")
    return {"ok": "completed", "error": "failed", "skipped": "skipped"}.get(last, "scheduled")


def _automation_row(job: dict) -> dict:
    state = job.get("state") or {}
    status = _job_status(job)
    return {
        "id": job.get("id"),
        "kind": "Automation",
        "job": True,    # a schedule, not one run: its time is its next run
        "title": (job.get("displayName") or job.get("name") or "").strip() or "Automation",
        "status": status,
        "startedAt": state.get("runningAtMs") if status == "running" else None,
        "endedAt": None,
        "error": state.get("lastError") if status == "failed" else None,
        "failedInARow": state.get("consecutiveErrors") or 0,
        "nextRunAtMs": job.get("nextRunAtMs") or state.get("nextRunAtMs"),
        "lastRunAtMs": state.get("lastRunAtMs"),
    }


def _background_rows(tasks, jobs, agents, session_key: str, *, commands: dict) -> dict:
    """The Background section's data. `tasks`: the Gateway's tasks for this
    session (None: the Gateway has no task list). `jobs`: every automation
    (None: not readable). `agents`: this chat's Agent call rows. Only what
    belongs to this chat is listed, whoever asks (ELI-175)."""
    automations_available = jobs is not None
    jobs = [j for j in jobs or [] if j.get("enabled", True)]
    mine = [j for j in jobs if _job_bound_to(j, session_key)]
    job_ids = {j.get("id") for j in mine}
    rows = [_automation_row(j) for j in mine]
    for t in tasks or []:
        if not _belongs_to(t, session_key) or (t.get("kind") or t.get("runtime")) not in _BACKGROUND_KINDS:
            continue
        if t.get("kind") == "automation_run" and t.get("sourceId") in job_ids:
            continue    # its automation's own row says how it went
        rows.append(_task_row(t, commands))
    for a in agents or []:
        if a.get("state") != "launched":
            continue
        rows.append({
            "id": a["id"], "kind": "Agent", "title": a["title"],
            # Its reply stays open until its report is in.
            "status": "completed" if a.get("replyDone") else "running",
            "startedAt": a.get("startedAt"), "endedAt": None, "preview": None,
            "agent": a,
        })
    live = [r for r in rows if r["status"] in _LIVE_TASK_STATUSES]
    rest = sorted((r for r in rows if r["status"] not in _LIVE_TASK_STATUSES),
                  key=lambda r: r.get("startedAt") or r.get("lastRunAtMs") or 0, reverse=True)
    live.sort(key=lambda r: r.get("startedAt") or 0, reverse=True)
    return {
        "rows": live + rest[:_BACKGROUND_FINISHED_CAP],
        "total": len(rows),
        "tasksAvailable": tasks is not None,
        "automationsAvailable": automations_available,
    }


_TRAILING_UUID_RE = re.compile(
    r"([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$", re.IGNORECASE)


def _control_ui_session_url(base: str, session_key: str) -> str | None:
    """The session's page in the OpenClaw Control UI (ELI-141).

    The UI's short-id route, `<base>/chat/<agentId>/<id>`, where `<id>` is the
    hex of the UUID the session key ends in (OpenClaw docs/web/urls.md; the UI
    resolves it with `sessions.resolve {shortId}`). Every key the dialog shows
    ends in one: `agent:<id>:openwebui-<user>-<chat>` and `agent:<id>:subagent:<uuid>`.
    None without an http(s) base or for any other key."""
    base = (base or "").strip().rstrip("/")
    parts = (session_key or "").split(":", 2)
    if not base.lower().startswith(("http://", "https://")) or len(parts) != 3 or parts[0] != "agent":
        return None
    m = _TRAILING_UUID_RE.search(parts[2])
    if not m or not parts[1]:
        return None
    return f"{base}/chat/{parts[1]}/{m.group(1).lower().replace('-', '')}"


def _render_drawer_open_js(task: dict) -> str:
    return _DRAWER_OPEN_JS_TEMPLATE.replace("__OPENCLAW_TASK__", _json_for_js(task))


def _render_drawer_error_js(message: str, task_key: str | None = None) -> str:
    """`task_key`: only the drawer showing that sub-agent takes it."""
    return (_DRAWER_ERROR_JS_TEMPLATE.replace("__OPENCLAW_ERROR_MESSAGE__", _json_for_js(message))
            .replace("__OPENCLAW_TASK_KEY__", _json_for_js(task_key)))


def _render_drawer_fill_js(data: dict) -> str:
    return _DRAWER_FILL_JS_TEMPLATE.replace("__OPENCLAW_STATUS_DATA__", _json_for_js(data))


# How long the open Status dialog follows its running sub-agents' pushed
# changes (a request held open), so a forgotten dialog cannot pin it forever.
_DIALOG_FOLLOW_MAX_S = 900
# How often an open drawer refreshes a running sub-agent. The page polls,
# not a held request, so the poll lives exactly as long as the drawer is open
# and the sub-agent runs (ELI-155).
_SUBAGENT_POLL_INTERVAL_S = 2.5


def _message_text_blocks(message: dict) -> list:
    content = message.get("content")
    if isinstance(content, str):
        return [content.strip()] if content.strip() else []
    return [b["text"].strip() for b in content or []
            if isinstance(b, dict) and b.get("type") == "text" and (b.get("text") or "").strip()]


def _spawn_message_text(message: dict) -> str | None:
    """A child's spawn message as the wrapped prompt its model got, or None
    when the message is not one. Up to OpenClaw 2026.9 `chat.history` shows
    the wrapped prompt; from 2026.10.10 it shows the bare task and keeps the
    prompt in `__openclaw.modelPromptProjection.text` (ELI-164)."""
    if message.get("role") != "user":
        return None
    text = "\n".join(_message_text_blocks(message))
    if _is_spawn_message(text):
        return text
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    projection = meta.get("modelPromptProjection") if isinstance(meta.get("modelPromptProjection"), dict) else {}
    prompt = projection.get("text")
    return prompt if _is_spawn_message(prompt) else None


def _spawn_task_of(messages: list) -> str | None:
    """The task out of the child's spawn message, when the history read
    still holds it."""
    for m in messages or []:
        wrapped = _spawn_message_text(m)
        if wrapped:
            return _subagent_task_text(wrapped)
    return None


# A /compact run always ends "done": whether it compacted is only in its
# reply, the Gateway's "⚙️ Compaction ..." line. These lead a refusal.
_COMPACT_REFUSALS = ("Compaction failed", "Compaction unavailable")


def _compact_reply(messages: list, idempotency_key: str) -> str | None:
    """The text of the compact run's own reply: the assistant message that
    carries the run's idempotency key, else the first one after the
    `/compact` turn (whose key is the run's plus ":user")."""
    def key_of(m):
        meta = m.get("__openclaw") if isinstance(m.get("__openclaw"), dict) else {}
        return m.get("idempotencyKey") or meta.get("idempotencyKey")

    after_ours = None
    for m in messages or []:
        if key_of(m) == f"{idempotency_key}:user":
            after_ours = True
        elif m.get("role") == "assistant" and (key_of(m) == idempotency_key or after_ours):
            return "\n".join(_message_text_blocks(m))
    return None


def _compact_refusal(reply: str | None) -> str | None:
    """The Gateway's reason when its reply says it did not compact, without
    the leading gear and the trailing context figures."""
    text = (reply or "").strip().removeprefix("⚙️").strip()
    head = text.split(" • ")[0].strip().rstrip(".")
    return head if head.startswith(_COMPACT_REFUSALS) else None


# How the drawer reads a sub-agent's run: the Gateway's largest page
# (CHAT_HISTORY_MAX_ENTRIES), text blocks up to 50000 characters, and a byte
# budget per read: the newest steps that fit, the rest behind "Show earlier
# steps", which reads with the larger budget.
_DRAWER_HISTORY_PAGE = 1000
_DRAWER_TEXT_MAX_CHARS = 50000
_DRAWER_RUN_BYTES = 512 * 1024
_DRAWER_RUN_BYTES_EARLIER = 4 * 1024 * 1024


async def _read_child_history(conn, child_key: str, budget: int, *, all_pages: bool) -> tuple[list, bool]:
    """The child's transcript, oldest first, and whether it is whole. One
    page by default; with `all_pages`, older pages too while the Gateway has
    more and the budget lasts."""
    messages: list = []
    offset, size = 0, 0
    while True:
        params = dict(sessionKey=child_key, limit=_DRAWER_HISTORY_PAGE, maxChars=_DRAWER_TEXT_MAX_CHARS)
        if offset:
            params["offset"] = offset
        resp = await conn.send_request("chat.history", params, timeout=8) or {}
        page = resp.get("messages") or []
        messages = page + messages
        size += len(json.dumps(page))
        more = bool(resp.get("hasMore"))
        nxt = resp.get("nextOffset")
        if not (all_pages and more and page and size < budget and isinstance(nxt, int) and nxt > offset):
            return messages, not more
        offset = nxt


def _drawer_run_items(messages: list) -> list:
    """The child's run as the drawer's read-only chat, oldest first: the
    turns it was sent after its task, and each stretch of its replies as
    the chat's own rebuild draws it (`_history_renderer`): text, and a card
    per tool call with its result."""
    items: list = []
    stretch: list = []

    def flush():
        if not stretch:
            return
        out = _history_renderer(stretch).output
        results = {o.get("call_id"): _card_text(o) for o in out if o.get("type") == "function_call_output"}
        for o in out:
            if o.get("type") == "message":
                text = "".join(c.get("text") or "" for c in o.get("content") or []).strip()
                if text:
                    items.append({"kind": "text", "text": text})
            elif o.get("type") == "function_call":
                # A call item's own id is its call id; only its output carries `call_id`.
                items.append({"kind": "tool", "id": o.get("id"), "name": o.get("name") or "tool",
                              "args": o.get("arguments") or "", "result": results.get(o.get("id"))})
        stretch.clear()

    for m in messages or []:
        text = "\n".join(_message_text_blocks(m)) if m.get("role") == "user" else ""
        if not text:
            stretch.append(m)
            continue
        flush()
        if not _spawn_message_text(m):      # the task itself is the header's
            items.append({"kind": "user", "text": text})
    flush()
    return items


def _cap_run_items(items: list, budget: int) -> tuple[list, int]:
    """The newest items that fit `budget` bytes, and how many older ones
    did not. The last item always stays; when it alone is over, the end of
    its text does (a reply's end is its conclusion)."""
    sizes = [len(json.dumps(i)) for i in items]
    total, dropped = sum(sizes), 0
    while total > budget and dropped < len(items) - 1:
        total -= sizes[dropped]
        dropped += 1
    kept = items[dropped:]
    if total > budget and kept:
        last = dict(kept[-1])
        field = "result" if last.get("kind") == "tool" else "text"
        text = last.get(field) or ""
        room = max(0, len(text) - (total - budget) - 64)
        last[field] = "…" + text[len(text) - room:] if room else "…"
        kept = kept[:-1] + [last]
    return kept, dropped


_OWUI_SESSION_KEY_RE = re.compile(
    r"^agent:[^:]+:openwebui-([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})-"
    r"([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$", re.IGNORECASE)


async def _drawer_parent(conn, session_row: dict, user_id) -> dict | None:
    """Where the sub-agent came from, for the header's "from" link: an Open
    WebUI chat by its title, or the sub-agent that spawned it by its label."""
    key = session_row.get("spawnedBy") or session_row.get("parentSessionKey")
    if not isinstance(key, str) or not key:
        return None
    m = _OWUI_SESSION_KEY_RE.match(key)
    if m:
        title = await _owui_chat_title(m.group(2), user_id) if user_id else None
        return {"title": title or "its chat", "chatId": m.group(2)}
    try:
        desc = await conn.send_request("sessions.describe", dict(key=key), timeout=5)
    except Exception as ex:
        pipe_log(f"[status-action] parent describe failed: {ex}")
        return None
    row = (desc or {}).get("session") or {}
    return {"title": (row.get("label") or row.get("displayName") or "").strip() or key, "childKey": key}


async def _previewed_task(conn, child_key: str) -> str | None:
    """The child's task out of `sessions.preview`, which keeps the spawn
    message as the model got it. 2026.10.5's `chat.history` shows the bare
    task with nothing that marks it as the spawn (its display projection
    strips the envelope), so the history read alone does not find it."""
    try:
        resp = await conn.send_request("sessions.preview", dict(keys=[child_key], limit=20, maxChars=2000),
                                       timeout=5)
    except Exception as ex:
        pipe_log(f"[status-action] sessions.preview (drawer task) failed: {ex}")
        return None
    return _subagent_task_texts(resp).get(child_key)


def _without_bare_task(items: list, task: str | None) -> list:
    """The drawer's items without a first user turn that is the task the
    header shows: the spawn message as 2026.10.5's history shows it."""
    if task and items and items[0].get("kind") == "user" and items[0].get("text", "").strip() == task.strip():
        return items[1:]
    return items


async def _latest_preview(conn, child_key: str) -> str | None:
    """A running child's newest message as the session list previews it:
    what a claude-cli child has said so far, while its transcript is still
    empty."""
    try:
        resp = await conn.send_request(
            "sessions.list", dict(search=child_key.rsplit(":", 1)[-1], limit=10, includeLastMessage=True), timeout=5)
    except Exception as ex:
        pipe_log(f"[status-action] latest preview failed: {ex}")
        return None
    row = next((r for r in (resp or {}).get("sessions") or [] if r.get("key") == child_key), {})
    preview = row.get("lastMessagePreview")
    return preview if isinstance(preview, str) and preview.strip() and not _is_spawn_message(preview) else None


# The toolbar button's icon, the composer chip's crab claw (ELI-231); without
# one Open WebUI draws its default sparkle. A fixed gray stroke on purpose: Open
# WebUI draws it as an <img>, so currentColor never resolves, and inverts it
# 80% in dark mode; this gray stays a mid gray in both, like its own icons.
ICON_URL = (
    "data:image/svg+xml;charset=utf-8,"
    "%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20"
    "stroke='%236b7280'%20stroke-width='1.6'%20stroke-linecap='round'%20stroke-linejoin='round'"
    "%3E%3Cpath%20d='M6.3%2014.6C4.6%2011.7%205.7%207.1%208.7%204.6C10.8%202.8%2013.4%202.3%2"
    "015.6%203.1C14.3%203.7%2013.4%204.4%2013%205.3L13.9%206.5L12%206.9C11.6%207.5%2011.3%208"
    ".1%2011.2%208.7C11.1%2011%2012.7%2012.9%2015.1%2012.7C16.4%2012.5%2017.3%2011.9%2017.8%2"
    "011.1L17.1%2010L18.6%209.7C18.6%209.2%2018.6%208.7%2018.5%208.2C20.5%2010.2%2020.6%2013."
    "4%2018.9%2015.8C17.1%2018.3%2014.2%2018.8%2011.6%2017.8C9.5%2017%207.5%2016.1%206.3%2014"
    ".6ZM7.8%2016L5.4%2019.6L9.1%2021.1L11%2017.6'/%3E%3C/svg%3E"
)


class Action:
    class Valves(BaseModel):
        GATEWAY_URL: str = Field(
            default="localhost:18789",
            description="Copy this exactly from the Pipe's valves. Gateway as "
                        "host:port, no http:// or ws:// prefix, e.g. "
                        "192.168.1.10:18789. Used only when this Action has to "
                        "open its own connection instead of reusing the Pipe's."
        )
        GATEWAY_TOKEN: str = Field(
            default="",
            description="Copy this exactly from the Pipe's valves. The value of "
                        "`gateway.auth.token` in your OpenClaw config. Used only "
                        "for the fallback connection."
        )
        DEVICE_IDENTITY: str = Field(
            default="",
            description="Copy this exactly from the Pipe's valves -- do not leave "
                        "it empty if the Pipe has one. It is what lets a fallback "
                        "connection be recognised as the same already-approved "
                        "device instead of raising a second pairing request."
        )
        STATE_DIR: str = Field(
            default="/data/openclaw-bridge",
            description="Copy this exactly from the Pipe's valves. It is how a "
                        "fallback connection finds the Pipe's persisted device "
                        "token on disk without re-pairing."
        )
        AGENT_ID: str = Field(
            default="main",
            description="Copy this exactly from the Pipe's valves -- the same "
                        "OpenClaw agent the Pipe routes chats to."
        )
        CONTROL_UI_URL: str = Field(
            default="",
            description="The address you open the OpenClaw Control UI at, e.g. "
                        "https://openclaw.example.com. When set, the Status "
                        "dialog and the sub-agent drawer link to the session in "
                        "it. Empty: no link."
        )

    def __init__(self):
        self.valves = self.Valves()
        self.icon_url = ICON_URL

    async def action(self, body: dict, __user__=None, __event_emitter__=None):
        """Dispatches on body["mode"]: the default ("status", or absent --
        this is what OWUI sends for the actual message-toolbar click) opens
        the dialog and shows live usage; "compact" and "subagent-detail" are
        never sent by OWUI itself -- both are synthetic markers the dialog's
        own in-page buttons fetch back with (see triggerCompact() and
        openSubagentDrawer() in _MODAL_OPEN_JS_TEMPLATE), reusing this same
        endpoint rather than registering a second Action.

        A real toolbar click on an old sub-agent-finished message (written
        by bridge versions before ELI-100) is also mode-less (OWUI itself
        never sends a "mode"), but carries a hidden
        `<!-- openclaw:taskId=... -->` marker in `body["content"]` -- there's deliberately no separate Action/button for
        this: a second OWUI Function, plus flipping the existing one off
        "global", was more infra and config risk than the payoff of a
        visually distinct icon. Detected here and redirected
        straight into the same subagent-detail drawer instead of the
        general status dialog, keyed off content rather than mode."""
        # No `execute` reaches a tab while it shows an input dialog (ELI-195).
        __event_emitter__ = _dialog_safe_emitter(
            __event_emitter__, (__user__ or {}).get("id"), body.get("chat_id"), body.get("id"))
        mode = body.get("mode")
        if mode == "compact":
            return await self._run_compact(body, __user__, __event_emitter__)
        if mode == "subagent-detail":
            return await self._run_subagent_detail(body, __user__, __event_emitter__)
        if mode == "status-closed":
            # The page's dialog was dismissed: its open request stops following.
            dialog = _dialog_of(body, (__user__ or {}).get("id") or "unknown")
            if dialog:
                _open_dialogs.pop(body["dialogId"], None)
                dialog["closed"].set()
            return {"status": "ok"}
        if mode == "subagent-rows":
            return await self._run_subagent_rows(body, __user__, __event_emitter__)
        if mode is None:
            marker = _SUBAGENT_TASK_ID_MARKER_RE.search(body.get("content") or "")
            if marker:
                return await self._run_subagent_detail(
                    {**body, "taskId": marker.group(1)}, __user__, __event_emitter__,
                )
        try:
            return await self._run_status(body, __user__, __event_emitter__)
        finally:
            # Every status run (re)delivers the composer Status button, so one
            # spark click is enough to install it in this tab. Sent last so it
            # never delays the dialog; idempotent and best effort (never
            # raises). Not on compact/drawer runs: the dialog that sends those
            # was opened by a status run, which already delivered it. The
            # Action is global (its spark shows under every model's replies),
            # so the chat is only vouched for when its model is the Pipe's.
            model = body.get("model")
            ours = isinstance(model, str) and model.startswith(_COMPOSER_DEFAULT_MODEL_PREFIX)
            await _emit_composer_button(
                __event_emitter__,
                session_id=body.get("session_id"),
                chat_id=body.get("chat_id") if ours else None,
                chat_model=model if ours else None,
            )

    async def _run_status(self, body: dict, __user__, __event_emitter__, *, show_loading=True, notice=None):
        """Opens the dialog at once with every section's title, then fills
        each section on its own the moment its own data is in (ELI-163): a
        slow or failing source shows in its section only.

        One request per source per open, all sent together: sessions.describe
        (Context, and the provider Rate limits needs), usage.status,
        sessions.list (Subagents: the store's rows, no transcripts read),
        tasks.list and cron.list (Background), and Open WebUI's copy of the
        chat (In-process agents, and Background's commands and agents). Read
        only when needed: the claude-cli usage fallback when usage.status has
        no windows, and the sub-agents' transcripts (sessions.preview) only
        when the Subagents section opens, at once when a child runs, else on
        the reader's first tap (mode "subagent-rows")."""
        chat_id = body.get("chat_id")
        user_id = (__user__ or {}).get("id") or "unknown"

        if not chat_id:
            await __event_emitter__({
                "type": "notification",
                "data": {"type": "error", "content": "OpenClaw status: no chat_id on this message"},
            })
            return {"status": "error", "detail": "missing chat_id"}

        session_key = _owui_session_key(self.valves.AGENT_ID, user_id, chat_id)
        # A refresh from inside the dialog (after a compact) replaces the
        # open's reads: the open stops following.
        previous = _dialog_of(body, user_id)
        if previous:
            _open_dialogs.pop(body["dialogId"], None)
            previous["closed"].set()
        dialog_id, dialog = _dialog_open(user_id, session_key)

        async def emit(code):
            await __event_emitter__({"type": "execute", "data": {"code": code}})

        # chat_id/message_id/session_id/model never depend on any RPC --
        # they're already in `body` -- so they're embedded once at open
        # time (IDENTITY in _MODAL_OPEN_JS_TEMPLATE) rather than threaded
        # through every section's own fill payload.
        if show_loading:
            identity = {
                "chatId": chat_id,
                "messageId": body.get("id"),
                "sessionId": body.get("session_id"),
                "owuiModel": body.get("model"),
                "dialogId": dialog_id,
                "controlUiUrl": _control_ui_session_url(self.valves.CONTROL_UI_URL, session_key),
                "subagentPollMs": int(_SUBAGENT_POLL_INTERVAL_S * 1000),
            }
            await emit(_render_modal_open_js(identity))
        else:
            # Post-compact refresh: the dialog is already open, but
            # _MODAL_COMPACTING_JS replaced the sections with its spinner;
            # put the sections back before the refreshed reads.
            await emit(_RESET_SECTIONS_JS.replace("__OPENCLAW_DIALOG_ID__", _json_for_js(dialog_id)))

        # The chat's newest messages from Open WebUI: no Gateway in it, so it
        # is read before connecting and its section fills even with no
        # Gateway.
        chat_task = asyncio.ensure_future(_load_owui_recent(chat_id, user_id))

        async def fill_agents():
            chat = await chat_task
            agents = _agent_call_rows(chat)
            await emit(_render_agents_fill_js({
                "agents": agents[:_SUBAGENT_LIST_CAP], "total": len(agents),
                "recent": _RECENT_MESSAGES if (chat or {}).get("truncated") else None,
                "fetchedAt": int(time.time() * 1000), "error": None,
            }))

        agents_ready = asyncio.ensure_future(fill_agents())

        try:
            conn, source = await _get_action_connection(lambda: self.valves)
        except Exception as ex:
            pipe_log(f"[status-action] connect failed: {ex}")
            for section in _GATEWAY_SECTIONS:
                await emit(_render_section_error_js(section, f"Could not connect: {ex}"))
            await agents_ready
            return {"status": "error", "detail": str(ex)}

        # Every source at once; each section awaits only its own.
        desc_task = asyncio.ensure_future(
            conn.send_request("sessions.describe", dict(key=session_key), timeout=5))
        usage_task = asyncio.ensure_future(conn.send_request("usage.status", {}, timeout=5))
        # The parent's child sessions (ELI-152), without reading every
        # session: `spawnedBy` gives the current ones (running, or ended in
        # the last 30 minutes), the child index (state.py) every child the
        # Pipe saw spawned with its last row. A new index is seeded once, from
        # one full list, after the section's first fill.
        current_task = asyncio.ensure_future(conn.send_request(
            "sessions.list", dict(spawnedBy=session_key, limit=50), timeout=5))
        seed_task = None if _subagent_index_seeded() else asyncio.ensure_future(
            conn.send_request("sessions.list", dict(limit=1000), timeout=30))
        tasks_task = asyncio.ensure_future(_read_background_tasks(conn, session_key))
        jobs_task = asyncio.ensure_future(_read_automations(conn))

        def list_children():
            return conn.send_request(
                "sessions.list", dict(spawnedBy=session_key, limit=50, includeLastMessage=True), timeout=5,
            )

        async def fill_context():
            """Also resolves provider/session_row for fill_limits to reuse
            (returned, not re-fetched) -- still reuses emit.py's small
            formatting primitives (_fmt_tokens, _format_goal_line) so
            wording matches the status line exactly."""
            try:
                desc = await desc_task
            except Exception as ex:
                pipe_log(f"[status-action] sessions.describe failed: {ex}")
                await emit(_render_context_fill_js({"error": f"Could not fetch context: {ex}"}))
                return None, {}

            session_row = (desc or {}).get("session") or {}
            provider = session_row.get("modelProvider") or "?"

            context_tokens = session_row.get("contextTokens")
            total_tokens = session_row.get("totalTokens")
            context_data = None
            if context_tokens and total_tokens is not None:
                context_data = {
                    "usedTokens": _fmt_tokens(total_tokens),
                    "totalTokens": _fmt_tokens(context_tokens),
                    "pct": round(total_tokens / context_tokens * 100, 1),
                }

            goal_data = None
            goal = session_row.get("goal")
            if goal:
                goal_line = _format_goal_line(goal)
                if goal_line:
                    tokens_used = goal.get("tokensUsed")
                    budget = goal.get("tokenBudget")
                    goal_pct = (
                        round(tokens_used / budget * 100, 1)
                        if (tokens_used is not None and budget) else None
                    )
                    goal_data = {"line": goal_line, "pct": goal_pct}

            await emit(_render_context_fill_js({
                "provider": provider,
                "model": session_row.get("model") or "",
                "context": context_data,
                "goal": goal_data,
                "notice": notice,
                "source": source,
                "fetchedAt": int(time.time() * 1000),
                "error": None,
            }))
            return provider, session_row

        async def fill_limits():
            # Which provider's windows to show is the session's: Context's
            # read of it, the same request.
            provider, session_row = await context_ready
            if provider is None:
                await emit(_render_limits_fill_js(
                    {"error": "Could not tell which provider this chat uses (its context did not load)."}))
                return
            try:
                usage = await usage_task
            except Exception as ex:
                pipe_log(f"[status-action] usage.status failed: {ex}")
                await emit(_render_limits_fill_js({"error": f"Could not fetch rate limits: {ex}"}))
                return

            windows_data = _limits_windows_for(usage, provider)
            if not windows_data and provider == "anthropic":
                windows_data = await _claude_cli_usage_windows(conn)

            await emit(_render_limits_fill_js({
                "provider": provider,
                "windows": windows_data,
                # Only used to word the empty-windows note -- a live run is
                # the one confirmed case (2026-07-11 live debugging) where
                # usage.status can transiently report zero windows for the
                # active provider, most likely because its rate-limit cache
                # refreshes from that run's own API response headers.
                "sessionActive": session_row.get("status") == "running",
                "source": source,
                "fetchedAt": int(time.time() * 1000),
                "error": None,
            }))

        async def fill_background():
            errors = []
            try:
                tasks = await tasks_task
            except Exception as ex:
                pipe_log(f"[status-action] tasks.list failed: {ex}")
                tasks = []
                errors.append(f"Could not read background tasks: {ex}")
            try:
                jobs = await jobs_task
            except Exception as ex:
                pipe_log(f"[status-action] cron.list failed: {ex}")
                jobs = []
                errors.append(f"Could not read automations: {ex}")
            chat = await chat_task
            data = _background_rows(tasks, jobs, _agent_call_rows(chat), session_key,
                                    commands=_exec_commands(chat))
            await emit(_render_background_fill_js({
                **data, "errors": errors, "source": source,
                "fetchedAt": int(time.time() * 1000), "error": None,
            }))

        # Every child seen so far by key, and what their transcripts told.
        children_seen, task_texts, latest = {}, {}, {}

        async def read_transcripts(keys):
            """The task and newest message of each of `keys` not read yet."""
            unread = [k for k in keys if k not in task_texts]
            if not unread:
                return
            try:
                previews = await conn.send_request(
                    "sessions.preview", dict(keys=unread, limit=20, maxChars=2000), timeout=5,
                )
            except Exception as ex:
                # Titles fall back to the spawn label; the rows still render.
                pipe_log(f"[status-action] sessions.preview (children) failed: {ex}")
                return
            texts, newest = _subagent_previews(previews)
            task_texts.update({k: None for k in unread})
            task_texts.update(texts)
            latest.update(newest)

        async def read_children():
            """The current children, then each indexed child they lack: its
            kept row when it had ended, else a lookup by its key. A failed
            list still shows the indexed children."""
            known = _subagent_children(session_key)
            error = None
            try:
                current = [r for r in ((await current_task) or {}).get("sessions") or []
                           if _is_child_of(r, session_key)]
            except Exception as ex:
                error, current = ex, []
            rows = {r["key"]: r for r in current}
            stale = [k for k, snap in known.items() if k not in rows and not _subagent_final(snap)]
            found = [r for r in await asyncio.gather(*(_lookup_child(conn, k) for k in stale[:_SUBAGENT_LIST_CAP]))
                     if r]
            rows.update({r["key"]: r for r in found})
            rows.update({k: snap for k, snap in known.items() if k not in rows and snap})
            if current or found:
                _subagent_remember(session_key, rows=current + found)
            if error is not None and not rows:
                raise error
            return {"sessions": list(rows.values())}

        async def seeded_children():
            """The seed's children of this chat the section lacks."""
            everything = (await seed_task) or {}
            _subagent_index_mark_seeded(everything.get("sessions") or [])
            return {"sessions": [snap for k, snap in _subagent_children(session_key).items()
                                 if snap and k not in children_seen]}

        def subagent_rows(shown):
            # A child's transcript may not hold its spawn message yet: then
            # the task its spawn call was given titles it (ELI-178).
            spawned = _subagent_tasks(session_key)
            return [{**_subagent_row(r, task_texts.get(r["key"]) or spawned.get(r["key"]),
                                     latest.get(r["key"])),
                     "controlUiUrl": _control_ui_session_url(self.valves.CONTROL_UI_URL, r["key"])}
                    for r in shown]

        async def fill_subagents(children, *, at_open=False):
            """Lists every child session of this chat (ELI-152), ended ones
            included, newest first, capped. Each row carries the fields its
            click hands the detail drawer (see S.openSubagentDrawer /
            Action._run_subagent_detail), so the drawer can paint its header
            instantly before its own RPCs resolve. A row's id is the child
            session key. At open, a section with no running child starts
            folded (the page's rule), so its transcripts wait for a tap.
            Returns the keys of the listed children still running."""
            try:
                children_resp = await children
            except Exception as ex:
                pipe_log(f"[status-action] sessions.list (children) failed: {ex}")
                await emit(_render_subagents_fill_js({"error": f"Could not fetch subagents: {ex}"}))
                return []
            for r in (children_resp or {}).get("sessions") or []:
                if _is_child_of(r, session_key):
                    children_seen[r["key"]] = r
            shown = sorted(children_seen.values(), key=_subagent_started, reverse=True)[:_SUBAGENT_LIST_CAP]
            running = [r["key"] for r in shown if _subagent_status(r.get("status")) in _LIVE_SUBAGENT_STATUSES]
            pending = at_open and not running and bool(shown)
            if not pending:
                await read_transcripts([r["key"] for r in shown])
            dialog["rows"], dialog["total"] = shown, len(children_seen)
            await emit(_render_subagents_fill_js({
                "tasks": subagent_rows(shown), "total": len(children_seen), "pending": pending,
                "source": source, "fetchedAt": int(time.time() * 1000), "error": None,
            }))
            return running

        context_ready = asyncio.ensure_future(fill_context())
        limits_ready = asyncio.ensure_future(fill_limits())
        background_ready = asyncio.ensure_future(fill_background())
        subagents_ready = asyncio.ensure_future(fill_subagents(read_children(), at_open=True))

        results = await asyncio.gather(context_ready, limits_ready, background_ready, subagents_ready,
                                       agents_ready, return_exceptions=True)
        for name, result in zip(("context", "limits", "background", "subagents", "agents"), results):
            if isinstance(result, BaseException):
                pipe_log(f"[status-action] {name} section failed: {result!r}")
                await emit(_render_section_error_js(name, f"Could not load this section: {result}"))
        listed = results[3] if isinstance(results[3], list) else []

        pipe_log(f"[status-action] status dialog filled ({source})")

        if seed_task is not None:
            try:
                before = len(children_seen)
                more = await seeded_children()
                if more["sessions"] and not dialog["closed"].is_set():
                    seen_running = await fill_subagents(_resolved(more))
                    listed = seen_running if len(children_seen) > before else listed
            except Exception as ex:
                pipe_log(f"[status-action] child index seed failed: {ex}")

        # The ticker counts a running child up while the dialog is open, so a
        # child that ends meanwhile must show its end (ELI-127). Hold this
        # request open, as the drawer does, and refill the section on each
        # pushed change to a listed child's run state, until none is listed,
        # the page closes the dialog, or the follow's bound passes. Each event
        # is taken before the read it guards, so no change slips between them.
        deadline = time.time() + _DIALOG_FOLLOW_MAX_S
        closed = dialog["closed"]
        while listed and not closed.is_set():
            changes = [conn.session_change_event(k) for k in listed]
            following = listed
            listed = await fill_subagents(list_children())
            if not listed or set(listed) - set(following):
                continue    # none left, or a new child: take its event first
            waits = [asyncio.ensure_future(ev.wait()) for ev in changes]
            waits.append(asyncio.ensure_future(closed.wait()))
            try:
                done, _pending = await asyncio.wait(
                    waits, timeout=max(deadline - time.time(), 0), return_when=asyncio.FIRST_COMPLETED)
            finally:
                for w in waits:
                    w.cancel()
            if not done:
                break
        return {"status": "ok"}

    async def _run_subagent_rows(self, body: dict, __user__, __event_emitter__):
        """The reader opened a folded Subagents section (ELI-163): read the
        listed children's transcripts, which the open left for this tap, and
        fill the section again. The rows are the open's, kept with its
        dialog, so the list is not read twice."""
        user_id = (__user__ or {}).get("id") or "unknown"
        dialog = _dialog_of(body, user_id)

        async def emit(code):
            await __event_emitter__({"type": "execute", "data": {"code": code}})

        if dialog is None:
            await emit(_render_subagents_fill_js({"error": "This dialog is out of date: open it again."}))
            return {"status": "error", "detail": "unknown dialog"}
        rows = dialog["rows"]
        try:
            conn, source = await _get_action_connection(lambda: self.valves)
            previews = await conn.send_request(
                "sessions.preview", dict(keys=[r["key"] for r in rows], limit=20, maxChars=2000), timeout=5)
        except Exception as ex:
            pipe_log(f"[status-action] sessions.preview (fold) failed: {ex}")
            previews, source = None, "action-own"
        texts, newest = _subagent_previews(previews)
        spawned = _subagent_tasks(dialog["session"])
        await emit(_render_subagents_fill_js({
            "tasks": [{**_subagent_row(r, texts.get(r["key"]) or spawned.get(r["key"]), newest.get(r["key"])),
                       "controlUiUrl": _control_ui_session_url(self.valves.CONTROL_UI_URL, r["key"])}
                      for r in rows],
            "total": dialog["total"], "pending": False,
            "source": source, "fetchedAt": int(time.time() * 1000), "error": None,
        }))
        return {"status": "ok"}

    async def _run_compact(self, body: dict, __user__, __event_emitter__):
        """Triggers /compact on the same session and waits for it to
        finish, then refreshes the dialog with post-compaction numbers.

        Uses chat.send(message="/compact") rather than the gateway's
        sessions.compact RPC: traced sessions.compact's handler and it
        explicitly rejects webchat-classified connections
        (rejectWebchatSessionMutation / isWebchatClient in the installed
        gateway bundle) -- and the Pipe's own connect params identify as
        client.id="webchat", so any connection this Action reuses from the
        Pipe is classified the same way. The RPC's own error message
        confirms the intended alternative: "use chat.send for
        session-scoped updates". This does mean the literal "/compact" text
        becomes a real turn in the session's stored transcript (visible to
        other surfaces that inspect that history), even though it never
        appears in OWUI's own chat bubble UI (a separate HTTP path this
        call never touches) -- a known, accepted trade-off, not an oversight.

        Polls sessions.describe for completion rather than registering a
        run consumer and reading the Pipe's event queue -- see the
        Milestone 4 plan notes for why: this only needs a boolean "still
        running" signal, not live text streaming, so the Pipe's much larger
        consumption loop (idle probes, steering, preview recovery) would be
        a lot of machinery for a narrow need.
        """
        chat_id = body.get("chat_id")
        user_id = (__user__ or {}).get("id") or "unknown"

        if not chat_id:
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js("Missing chat_id")},
            })
            return {"status": "error", "detail": "missing chat_id"}

        session_key = _owui_session_key(self.valves.AGENT_ID, user_id, chat_id)

        try:
            conn, source = await _get_action_connection(lambda: self.valves)
        except Exception as ex:
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js(f"Could not connect: {ex}")},
            })
            return {"status": "error", "detail": str(ex)}

        if conn.active_run_id_for_session(session_key):
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js(
                    "A response is currently in progress -- wait for it to "
                    "finish before compacting."
                )},
            })
            return {"status": "error", "detail": "session busy"}

        # Immediate, unambiguous visual feedback -- compaction can take a
        # while (it's an LLM summarization call), so the dialog needs a
        # definitive "in progress" state, not a skeleton that looks like
        # it's about to finish in a second.
        await __event_emitter__({"type": "execute", "data": {"code": _MODAL_COMPACTING_JS}})

        idempotency_key = f"{ACTION_RUN_PREFIX}compact-{chat_id}-{time.time()}"
        try:
            compact_params = _owui_chat_send_params(
                session_key=session_key,
                message="/compact",
                # ACTION_RUN_PREFIX: the turn path never gives this run a message.
                idempotency_key=idempotency_key,
                owui_chat_id=chat_id,
                owui_user_id=user_id,
            )
            # Explicit, not relying on the gateway's own default for an
            # omitted field: this compact run should never trigger outbound
            # delivery to other configured channels (Slack/Discord/etc.) --
            # same reasoning gateway.py's existing send_stop already applies
            # to its own chat.send("/stop") call.
            compact_params["deliver"] = False
            send_resp = await _run_request(conn, RUN_SEND, compact_params, timeout=30)
        except Exception as ex:
            pipe_log(f"[status-action] compact chat.send failed: {ex}")
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js(f"Could not start compact: {ex}")},
            })
            return {"status": "error", "detail": str(ex)}

        pipe_log(f"[status-action] compact started, runId={send_resp.get('runId')}")

        deadline = time.time() + 180  # matches `openclaw sessions compact`'s own default RPC timeout
        status = None
        while time.time() < deadline:
            await asyncio.sleep(1.5)
            try:
                desc = await conn.send_request("sessions.describe", dict(key=session_key), timeout=8)
            except Exception as ex:
                pipe_log(f"[status-action] compact poll failed: {ex}")
                continue
            status = ((desc or {}).get("session") or {}).get("status")
            if status in ("done", "failed", "cancelled"):
                break

        if status not in ("done", "failed", "cancelled"):
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js(
                    "Compact timed out -- it may still finish in the background."
                )},
            })
            return {"status": "error", "detail": "timeout"}

        if status != "done":
            await __event_emitter__({
                "type": "execute",
                "data": {"code": _render_sections_error_js(f"Compact {status}.")},
            })
            return {"status": "error", "detail": status}

        # The run is done either way; its reply says whether it compacted
        # (ELI-209). A reply that cannot be read leaves the numbers to speak.
        try:
            history = await conn.send_request("chat.history", dict(sessionKey=session_key, limit=10), timeout=8)
            refusal = _compact_refusal(_compact_reply((history or {}).get("messages"), idempotency_key))
        except Exception as ex:
            pipe_log(f"[status-action] compact reply read failed: {ex}")
            refusal = None
        if refusal:
            pipe_log(f"[status-action] compact refused: {refusal}")
            await self._run_status(body, __user__, __event_emitter__, show_loading=False, notice=refusal)
            return {"status": "error", "detail": refusal}

        pipe_log("[status-action] compact done, refreshing status")
        return await self._run_status(body, __user__, __event_emitter__, show_loading=False)

    async def _run_subagent_detail(self, body: dict, __user__, __event_emitter__):
        """Fills the sub-agent drawer once and returns. The open drawer asks
        again every _SUBAGENT_POLL_INTERVAL_S while its sub-agent runs (its
        own poll, `S.openDrawer`), so the refresh lives exactly as long as
        the drawer is open, with no deadline and nothing left polling for a
        closed one (ELI-155). A row click opens the drawer in the page and
        sends `opened`; without it (an old sub-agent message's toolbar
        click) the drawer is opened from here first."""
        task_id = body.get("taskId")
        if not task_id:
            await __event_emitter__({"type": "execute", "data": {
                "code": _render_drawer_error_js("Missing taskId")
            }})
            return {"status": "error", "detail": "missing taskId"}

        if not body.get("opened"):
            await __event_emitter__({"type": "execute", "data": {"code": _render_drawer_open_js({
                "id": task_id, "childSessionKey": task_id, "title": body.get("taskTitle"),
                "status": body.get("taskStatus"),
                "controlUiUrl": _control_ui_session_url(self.valves.CONTROL_UI_URL, task_id),
            })}})

        if not task_id.startswith("agent:"):
            # A Tasks API id from a message written before ELI-100; only the
            # removed tasks.get could resolve it to a child session.
            await __event_emitter__({"type": "execute", "data": {
                "code": _render_drawer_error_js("This sub-agent's details are no longer available.")
            }})
            return {"status": "error", "detail": "legacy task id"}

        try:
            conn, source = await _get_action_connection(lambda: self.valves)
        except Exception as ex:
            pipe_log(f"[status-action] subagent-detail connect failed: {ex}")
            await __event_emitter__({"type": "execute", "data": {
                "code": _render_drawer_error_js(f"Could not connect: {ex}", task_id)
            }})
            return {"status": "error", "detail": str(ex)}

        user_id = (__user__ or {}).get("id") if isinstance(__user__, dict) else None
        return await self._fill_subagent_detail(
            conn, source, task_id, __event_emitter__,
            # The header's "from" link is read once, with the drawer's first fill.
            parent_for=user_id if (body.get("first") or not body.get("opened")) else False,
            earlier=bool(body.get("earlier")),
        )

    async def _fill_subagent_detail(self, conn, source, child_key, __event_emitter__, *,
                                    parent_for=False, earlier=False):
        """One read of the child session and its whole run, pushed to the
        drawer: its header, and the run as a read-only chat. `parent_for`:
        the user to read the parent chat's title as, or False to skip it.
        `earlier`: the reader asked for the steps a normal read leaves out."""
        budget = _DRAWER_RUN_BYTES_EARLIER if earlier else _DRAWER_RUN_BYTES
        try:
            desc_resp, (messages, whole) = await asyncio.gather(
                conn.send_request("sessions.describe", dict(key=child_key), timeout=8),
                _read_child_history(conn, child_key, budget, all_pages=earlier),
            )
        except Exception as ex:
            pipe_log(f"[status-action] subagent detail fetch failed: {ex}")
            await __event_emitter__({"type": "execute", "data": {
                "code": _render_drawer_error_js(f"Could not fetch sub-agent: {ex}", child_key)
            }})
            return {"status": "error", "detail": str(ex)}

        session_row = (desc_resp or {}).get("session") or {}
        if not session_row:
            await __event_emitter__({"type": "execute", "data": {
                "code": _render_drawer_error_js("Sub-agent not found.", child_key)
            }})
            return {"status": "error", "detail": "sub-agent not found"}

        parent = session_row.get("spawnedBy") or session_row.get("parentSessionKey")
        task_text = _spawn_task_of(messages) or _subagent_tasks(parent).get(child_key)
        if task_text is None:
            task_text = await _previewed_task(conn, child_key)
        task = _subagent_row({"key": child_key, **session_row}, task_text)
        items, dropped = _cap_run_items(_without_bare_task(_drawer_run_items(messages), task_text), budget)
        claude_cli = (session_row.get("agentRuntime") or {}).get("id") == "claude-cli"
        note = latest = None
        if claude_cli and task["status"] in _LIVE_SUBAGENT_STATUSES:
            # A claude-cli run's messages reach its transcript when it ends
            # (measured, Gateway 2026.9.3); until then its newest line is
            # what the session list previews.
            note, latest = "cli-running", await _latest_preview(conn, child_key)
        elif claude_cli and task["status"] == "cancelled":
            note = "cli-stopped"   # stopped before it ended: nothing of it was saved
        parent = await _drawer_parent(conn, session_row, parent_for) if parent_for is not False else None

        await __event_emitter__({"type": "execute", "data": {"code": _render_drawer_fill_js({
            "childSessionKey": child_key,
            "task": {**{k: task[k] for k in ("title", "status", "startedAt", "endedAt", "task", "error")},
                     "model": session_row.get("model")},
            "parent": parent,
            "items": items,
            "earlier": {"count": dropped, "more": not whole} if dropped or not whole else None,
            "note": note, "latest": latest,
            "source": source, "fetchedAt": int(time.time() * 1000), "error": None,
        })}})
        return {"status": "ok"}
